INSERT INTO compliance_controls (control_id, framework, family, title, description) VALUES
  ('AC-1', 'NIST-800-53', 'Access Control', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] access control policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the access control policy and the associated access controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the access control policy and procedures; and
c. Review and update the current access control:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('AC-2', 'NIST-800-53', 'Access Control', 'Account Management', 'a. Define and document the types of accounts allowed and specifically prohibited for use within the system;
b. Assign account managers;
c. Require [Assignment: organization-defined prerequisites and criteria] for group and role membership;
d. Specify:
  1. Authorized users of the system;
  2. Group and role membership; and
  3. Access authorizations (i.e., privileges) and [Assignment: organization-defined attributes (as required)] for each account;
e. Require approvals by [Assignment: organization-defined personnel or roles] for requests to create accounts;
f. Create, enable, modify, disable, and remove accounts in accordance with [Assignment: organization-defined policy, procedures, prerequisites, and criteria];
g. Monitor the use of accounts;
h. Notify account managers and [Assignment: organization-defined personnel or roles] within:
  1. [Assignment: organization-defined time period] when accounts are no longer required;
  2. [Assignment: organization-defined time period] when users are terminated or transferred; and
  3. [Assignment: organization-defined time period] when system usage or need-to-know changes for an individual;
i. Authorize access to the system based on:
  1. A valid access authorization;
  2. Intended system usage; and
  3. [Assignment: organization-defined attributes (as required)];
j. Review accounts for compliance with account management requirements [Assignment: organization-defined frequency];
k. Establish and implement a process for changing shared or group account authenticators (if deployed) when individuals are removed from the group; and
l. Align account management processes with personnel termination and transfer processes.'),
  ('AC-2(1)', 'NIST-800-53', 'Access Control', 'Account Management | Automated System Account Management', 'Support the management of system accounts using [Assignment: organization-defined automated mechanisms].'),
  ('AC-2(2)', 'NIST-800-53', 'Access Control', 'Account Management | Automated Temporary and Emergency Account Management', 'Automatically [Selection: remove; disable] temporary and emergency accounts after [Assignment: organization-defined time period].'),
  ('AC-2(3)', 'NIST-800-53', 'Access Control', 'Account Management | Disable Accounts', 'Disable accounts within [Assignment: organization-defined time period] when the accounts:
  (a) Have expired;
  (b) Are no longer associated with a user or individual;
  (c) Are in violation of organizational policy; or
  (d) Have been inactive for [Assignment: organization-defined time period].'),
  ('AC-2(4)', 'NIST-800-53', 'Access Control', 'Account Management | Automated Audit Actions', 'Automatically audit account creation, modification, enabling, disabling, and removal actions.'),
  ('AC-2(5)', 'NIST-800-53', 'Access Control', 'Account Management | Inactivity Logout', 'Require that users log out when [Assignment: organization-defined time period of expected inactivity or description of when to log out].'),
  ('AC-2(6)', 'NIST-800-53', 'Access Control', 'Account Management | Dynamic Privilege Management', 'Implement [Assignment: organization-defined dynamic privilege management capabilities].'),
  ('AC-2(7)', 'NIST-800-53', 'Access Control', 'Account Management | Privileged User Accounts', '(a) Establish and administer privileged user accounts in accordance with [Selection: a role-based access scheme; an attribute-based access scheme];
(b) Monitor privileged role or attribute assignments;
(c) Monitor changes to roles or attributes; and
(d) Revoke access when privileged role or attribute assignments are no longer appropriate.'),
  ('AC-2(8)', 'NIST-800-53', 'Access Control', 'Account Management | Dynamic Account Management', 'Create, activate, manage, and deactivate [Assignment: organization-defined system accounts] dynamically.'),
  ('AC-2(9)', 'NIST-800-53', 'Access Control', 'Account Management | Restrictions on Use of Shared and Group Accounts', 'Only permit the use of shared and group accounts that meet [Assignment: organization-defined conditions].'),
  ('AC-2(11)', 'NIST-800-53', 'Access Control', 'Account Management | Usage Conditions', 'Enforce [Assignment: organization-defined circumstances and/or usage conditions] for [Assignment: organization-defined system accounts].'),
  ('AC-2(12)', 'NIST-800-53', 'Access Control', 'Account Management | Account Monitoring for Atypical Usage', '(a) Monitor system accounts for [Assignment: organization-defined atypical usage] ; and
(b) Report atypical usage of system accounts to [Assignment: organization-defined personnel or roles].'),
  ('AC-2(13)', 'NIST-800-53', 'Access Control', 'Account Management | Disable Accounts for High-risk Individuals', 'Disable accounts of individuals within [Assignment: organization-defined time period] of discovery of [Assignment: organization-defined significant risks].'),
  ('AC-3', 'NIST-800-53', 'Access Control', 'Access Enforcement', 'Enforce approved authorizations for logical access to information and system resources in accordance with applicable access control policies.'),
  ('AC-3(2)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Dual Authorization', 'Enforce dual authorization for [Assignment: organization-defined privileged commands and/or other actions].'),
  ('AC-3(3)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Mandatory Access Control', 'Enforce [Assignment: organization-defined mandatory access control policy] over the set of covered subjects and objects specified in the policy, and where the policy:
  (a) Is uniformly enforced across the covered subjects and objects within the system;
  (b) Specifies that a subject that has been granted access to information is constrained from doing any of the following;
    (1) Passing the information to unauthorized subjects or objects;
    (2) Granting its privileges to other subjects;
    (3) Changing one or more security attributes (specified by the policy) on subjects, objects, the system, or system components;
    (4) Choosing the security attributes and attribute values (specified by the policy) to be associated with newly created or modified objects; and
    (5) Changing the rules governing access control; and
  (c) Specifies that [Assignment: organization-defined subjects] may explicitly be granted [Assignment: organization-defined privileges] such that they are not limited by any defined subset (or all) of the above constraints.'),
  ('AC-3(4)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Discretionary Access Control', 'Enforce [Assignment: organization-defined discretionary access control policy] over the set of covered subjects and objects specified in the policy, and where the policy specifies that a subject that has been granted access to information can do one or more of the following:
  (a) Pass the information to any other subjects or objects;
  (b) Grant its privileges to other subjects;
  (c) Change security attributes on subjects, objects, the system, or the system’s components;
  (d) Choose the security attributes to be associated with newly created or revised objects; or
  (e) Change the rules governing access control.'),
  ('AC-3(5)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Security-relevant Information', 'Prevent access to [Assignment: organization-defined security-relevant information] except during secure, non-operable system states.'),
  ('AC-3(7)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Role-based Access Control', 'Enforce a role-based access control policy over defined subjects and objects and control access based upon [Assignment: organization-defined roles and users authorized to assume such roles].'),
  ('AC-3(8)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Revocation of Access Authorizations', 'Enforce the revocation of access authorizations resulting from changes to the security attributes of subjects and objects based on [Assignment: organization-defined rules].'),
  ('AC-3(9)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Controlled Release', 'Release information outside of the system only if:
  (a) The receiving [Assignment: organization-defined system or system component] provides [Assignment: organization-defined controls] ; and
  (b) [Assignment: organization-defined controls] are used to validate the appropriateness of the information designated for release.'),
  ('AC-3(10)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Audited Override of Access Control Mechanisms', 'Employ an audited override of automated access control mechanisms under [Assignment: organization-defined conditions] by [Assignment: organization-defined roles].'),
  ('AC-3(11)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Restrict Access to Specific Information Types', 'Restrict access to data repositories containing [Assignment: organization-defined information types].'),
  ('AC-3(12)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Assert and Enforce Application Access', '(a) Require applications to assert, as part of the installation process, the access needed to the following system applications and functions: [Assignment: organization-defined system applications and functions];
(b) Provide an enforcement mechanism to prevent unauthorized access; and
(c) Approve access changes after initial installation of the application.'),
  ('AC-3(13)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Attribute-based Access Control', 'Enforce attribute-based access control policy over defined subjects and objects and control access based upon [Assignment: organization-defined attributes].'),
  ('AC-3(14)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Individual Access', 'Provide [Assignment: organization-defined mechanisms] to enable individuals to have access to the following elements of their personally identifiable information: [Assignment: organization-defined elements].'),
  ('AC-3(15)', 'NIST-800-53', 'Access Control', 'Access Enforcement | Discretionary and Mandatory Access Control', '(a) Enforce [Assignment: organization-defined mandatory access control policy] over the set of covered subjects and objects specified in the policy; and
(b) Enforce [Assignment: organization-defined discretionary access control policy] over the set of covered subjects and objects specified in the policy.'),
  ('AC-4', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement', 'Enforce approved authorizations for controlling the flow of information within the system and between connected systems based on [Assignment: organization-defined information flow control policies].'),
  ('AC-4(1)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Object Security and Privacy Attributes', 'Use [Assignment: organization-defined security and privacy attributes] associated with [Assignment: organization-defined information, source, and destination objects] to enforce [Assignment: organization-defined information flow control policies] as a basis for flow control decisions.'),
  ('AC-4(2)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Processing Domains', 'Use protected processing domains to enforce [Assignment: organization-defined information flow control policies] as a basis for flow control decisions.'),
  ('AC-4(3)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Dynamic Information Flow Control', 'Enforce [Assignment: organization-defined information flow control policies].'),
  ('AC-4(4)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Flow Control of Encrypted Information', 'Prevent encrypted information from bypassing [Assignment: organization-defined information flow control mechanisms] by [Selection (one or more): decrypting the information; blocking the flow of the encrypted information; terminating communications sessions attempting to pass encrypted information; [Assignment: organization-defined procedure or method] ].'),
  ('AC-4(5)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Embedded Data Types', 'Enforce [Assignment: organization-defined limitations] on embedding data types within other data types.'),
  ('AC-4(6)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Metadata', 'Enforce information flow control based on [Assignment: organization-defined metadata].'),
  ('AC-4(7)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | One-way Flow Mechanisms', 'Enforce one-way information flows through hardware-based flow control mechanisms.'),
  ('AC-4(8)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Security and Privacy Policy Filters', '(a) Enforce information flow control using [Assignment: organization-defined security or privacy policy filters] as a basis for flow control decisions for [Assignment: organization-defined information flows] ; and
(b) [Selection (one or more): block; strip; modify; quarantine] data after a filter processing failure in accordance with [Assignment: organization-defined security or privacy policy].'),
  ('AC-4(9)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Human Reviews', 'Enforce the use of human reviews for [Assignment: organization-defined information flows] under the following conditions: [Assignment: organization-defined conditions].'),
  ('AC-4(10)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Enable and Disable Security or Privacy Policy Filters', 'Provide the capability for privileged administrators to enable and disable [Assignment: organization-defined security or privacy policy filters] under the following conditions: [Assignment: organization-defined conditions].'),
  ('AC-4(11)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Configuration of Security or Privacy Policy Filters', 'Provide the capability for privileged administrators to configure [Assignment: organization-defined security or privacy policy filters] to support different security or privacy policies.'),
  ('AC-4(12)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Data Type Identifiers', 'When transferring information between different security domains, use [Assignment: organization-defined data type identifiers] to validate data essential for information flow decisions.'),
  ('AC-4(13)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Decomposition into Policy-relevant Subcomponents', 'When transferring information between different security domains, decompose information into [Assignment: organization-defined policy-relevant subcomponents] for submission to policy enforcement mechanisms.'),
  ('AC-4(14)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Security or Privacy Policy Filter Constraints', 'When transferring information between different security domains, implement [Assignment: organization-defined security or privacy policy filters] requiring fully enumerated formats that restrict data structure and content.'),
  ('AC-4(15)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Detection of Unsanctioned Information', 'When transferring information between different security domains, examine the information for the presence of [Assignment: organization-defined unsanctioned information] and prohibit the transfer of such information in accordance with the [Assignment: organization-defined security or privacy policy].'),
  ('AC-4(17)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Domain Authentication', 'Uniquely identify and authenticate source and destination points by [Selection (one or more): organization, system, application, service, individual] for information transfer.'),
  ('AC-4(19)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Validation of Metadata', 'When transferring information between different security domains, implement [Assignment: organization-defined security or privacy policy filters] on metadata.'),
  ('AC-4(20)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Approved Solutions', 'Employ [Assignment: organization-defined solutions in approved configurations] to control the flow of [Assignment: organization-defined information] across security domains.'),
  ('AC-4(21)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Physical or Logical Separation of Information Flows', 'Separate information flows logically or physically using [Assignment: organization-defined mechanisms and/or techniques] to accomplish [Assignment: organization-defined required separations].'),
  ('AC-4(22)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Access Only', 'Provide access from a single device to computing platforms, applications, or data residing in multiple different security domains, while preventing information flow between the different security domains.'),
  ('AC-4(23)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Modify Non-releasable Information', 'When transferring information between different security domains, modify non-releasable information by implementing [Assignment: organization-defined modification action].'),
  ('AC-4(24)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Internal Normalized Format', 'When transferring information between different security domains, parse incoming data into an internal normalized format and regenerate the data to be consistent with its intended specification.'),
  ('AC-4(25)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Data Sanitization', 'When transferring information between different security domains, sanitize data to minimize [Selection (one or more): delivery of malicious content, command and control of malicious code, malicious code augmentation, and steganography-encoded data; spillage of sensitive information] in accordance with [Assignment: organization-defined policy].'),
  ('AC-4(26)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Audit Filtering Actions', 'When transferring information between different security domains, record and audit content filtering actions and results for the information being filtered.'),
  ('AC-4(27)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Redundant/Independent Filtering Mechanisms', 'When transferring information between different security domains, implement content filtering solutions that provide redundant and independent filtering mechanisms for each data type.'),
  ('AC-4(28)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Linear Filter Pipelines', 'When transferring information between different security domains, implement a linear content filter pipeline that is enforced with discretionary and mandatory access controls.'),
  ('AC-4(29)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Filter Orchestration Engines', 'When transferring information between different security domains, employ content filter orchestration engines to ensure that:
  (a) Content filtering mechanisms successfully complete execution without errors; and
  (b) Content filtering actions occur in the correct order and comply with [Assignment: organization-defined policy].'),
  ('AC-4(30)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Filter Mechanisms Using Multiple Processes', 'When transferring information between different security domains, implement content filtering mechanisms using multiple processes.'),
  ('AC-4(31)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Failed Content Transfer Prevention', 'When transferring information between different security domains, prevent the transfer of failed content to the receiving domain.'),
  ('AC-4(32)', 'NIST-800-53', 'Access Control', 'Information Flow Enforcement | Process Requirements for Information Transfer', 'When transferring information between different security domains, the process that transfers information between filter pipelines:
  (a) Does not filter message content;
  (b) Validates filtering metadata;
  (c) Ensures the content associated with the filtering metadata has successfully completed filtering; and
  (d) Transfers the content to the destination filter pipeline.'),
  ('AC-5', 'NIST-800-53', 'Access Control', 'Separation of Duties', 'a. Identify and document [Assignment: organization-defined duties of individuals] ; and
b. Define system access authorizations to support separation of duties.'),
  ('AC-6', 'NIST-800-53', 'Access Control', 'Least Privilege', 'Employ the principle of least privilege, allowing only authorized accesses for users (or processes acting on behalf of users) that are necessary to accomplish assigned organizational tasks.'),
  ('AC-6(1)', 'NIST-800-53', 'Access Control', 'Least Privilege | Authorize Access to Security Functions', 'Authorize access for [Assignment: organization-defined individuals and roles] to:
  (a) [Assignment: organization-defined security functions (deployed in hardware, software, and firmware)] ; and
  (b) [Assignment: organization-defined security-relevant information].'),
  ('AC-6(2)', 'NIST-800-53', 'Access Control', 'Least Privilege | Non-privileged Access for Nonsecurity Functions', 'Require that users of system accounts (or roles) with access to [Assignment: organization-defined security functions or security-relevant information] use non-privileged accounts or roles, when accessing nonsecurity functions.'),
  ('AC-6(3)', 'NIST-800-53', 'Access Control', 'Least Privilege | Network Access to Privileged Commands', 'Authorize network access to [Assignment: organization-defined privileged commands] only for [Assignment: organization-defined compelling operational needs] and document the rationale for such access in the security plan for the system.'),
  ('AC-6(4)', 'NIST-800-53', 'Access Control', 'Least Privilege | Separate Processing Domains', 'Provide separate processing domains to enable finer-grained allocation of user privileges.'),
  ('AC-6(5)', 'NIST-800-53', 'Access Control', 'Least Privilege | Privileged Accounts', 'Restrict privileged accounts on the system to [Assignment: organization-defined personnel or roles].'),
  ('AC-6(6)', 'NIST-800-53', 'Access Control', 'Least Privilege | Privileged Access by Non-organizational Users', 'Prohibit privileged access to the system by non-organizational users.'),
  ('AC-6(7)', 'NIST-800-53', 'Access Control', 'Least Privilege | Review of User Privileges', '(a) Review [Assignment: organization-defined frequency] the privileges assigned to [Assignment: organization-defined roles and classes] to validate the need for such privileges; and
(b) Reassign or remove privileges, if necessary, to correctly reflect organizational mission and business needs.'),
  ('AC-6(8)', 'NIST-800-53', 'Access Control', 'Least Privilege | Privilege Levels for Code Execution', 'Prevent the following software from executing at higher privilege levels than users executing the software: [Assignment: organization-defined software].'),
  ('AC-6(9)', 'NIST-800-53', 'Access Control', 'Least Privilege | Log Use of Privileged Functions', 'Log the execution of privileged functions.'),
  ('AC-6(10)', 'NIST-800-53', 'Access Control', 'Least Privilege | Prohibit Non-privileged Users from Executing Privileged Functions', 'Prevent non-privileged users from executing privileged functions.'),
  ('AC-7', 'NIST-800-53', 'Access Control', 'Unsuccessful Logon Attempts', 'a. Enforce a limit of [Assignment: organization-defined number] consecutive invalid logon attempts by a user during a [Assignment: organization-defined time period] ; and
b. Automatically [Selection (one or more): lock the account or node for [Assignment: organization-defined time period] ; lock the account or node until released by an administrator; delay next logon prompt per [Assignment: organization-defined delay algorithm] ; notify system administrator; take other [Assignment: organization-defined action] ] when the maximum number of unsuccessful attempts is exceeded.'),
  ('AC-7(2)', 'NIST-800-53', 'Access Control', 'Unsuccessful Logon Attempts | Purge or Wipe Mobile Device', 'Purge or wipe information from [Assignment: organization-defined mobile devices] based on [Assignment: organization-defined purging or wiping requirements and techniques] after [Assignment: organization-defined number] consecutive, unsuccessful device logon attempts.'),
  ('AC-7(3)', 'NIST-800-53', 'Access Control', 'Unsuccessful Logon Attempts | Biometric Attempt Limiting', 'Limit the number of unsuccessful biometric logon attempts to [Assignment: organization-defined number].'),
  ('AC-7(4)', 'NIST-800-53', 'Access Control', 'Unsuccessful Logon Attempts | Use of Alternate Authentication Factor', '(a) Allow the use of [Assignment: organization-defined authentication factors] that are different from the primary authentication factors after the number of organization-defined consecutive invalid logon attempts have been exceeded; and
(b) Enforce a limit of [Assignment: organization-defined number] consecutive invalid logon attempts through use of the alternative factors by a user during a [Assignment: organization-defined time period].'),
  ('AC-8', 'NIST-800-53', 'Access Control', 'System Use Notification', 'a. Display [Assignment: organization-defined system use notification] to users before granting access to the system that provides privacy and security notices consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and state that:
  1. Users are accessing a U.S. Government system;
  2. System usage may be monitored, recorded, and subject to audit;
  3. Unauthorized use of the system is prohibited and subject to criminal and civil penalties; and
  4. Use of the system indicates consent to monitoring and recording;
b. Retain the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the system; and
c. For publicly accessible systems:
  1. Display system use information [Assignment: organization-defined conditions] , before granting further access to the publicly accessible system;
  2. Display references, if any, to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities; and
  3. Include a description of the authorized uses of the system.'),
  ('AC-9', 'NIST-800-53', 'Access Control', 'Previous Logon Notification', 'Notify the user, upon successful logon to the system, of the date and time of the last logon.'),
  ('AC-9(1)', 'NIST-800-53', 'Access Control', 'Previous Logon Notification | Unsuccessful Logons', 'Notify the user, upon successful logon, of the number of unsuccessful logon attempts since the last successful logon.'),
  ('AC-9(2)', 'NIST-800-53', 'Access Control', 'Previous Logon Notification | Successful and Unsuccessful Logons', 'Notify the user, upon successful logon, of the number of [Selection: successful logons; unsuccessful logon attempts; both] during [Assignment: organization-defined time period].'),
  ('AC-9(3)', 'NIST-800-53', 'Access Control', 'Previous Logon Notification | Notification of Account Changes', 'Notify the user, upon successful logon, of changes to [Assignment: organization-defined security-related characteristics or parameters] during [Assignment: organization-defined time period].'),
  ('AC-9(4)', 'NIST-800-53', 'Access Control', 'Previous Logon Notification | Additional Logon Information', 'Notify the user, upon successful logon, of the following additional information: [Assignment: organization-defined additional information].'),
  ('AC-10', 'NIST-800-53', 'Access Control', 'Concurrent Session Control', 'Limit the number of concurrent sessions for each [Assignment: organization-defined account and/or account types] to [Assignment: organization-defined number].'),
  ('AC-11', 'NIST-800-53', 'Access Control', 'Device Lock', 'a. Prevent further access to the system by [Selection (one or more): initiating a device lock after [Assignment: organization-defined time period] of inactivity; requiring the user to initiate a device lock before leaving the system unattended] ; and
b. Retain the device lock until the user reestablishes access using established identification and authentication procedures.'),
  ('AC-11(1)', 'NIST-800-53', 'Access Control', 'Device Lock | Pattern-hiding Displays', 'Conceal, via the device lock, information previously visible on the display with a publicly viewable image.'),
  ('AC-12', 'NIST-800-53', 'Access Control', 'Session Termination', 'Automatically terminate a user session after [Assignment: organization-defined conditions or trigger events].'),
  ('AC-12(1)', 'NIST-800-53', 'Access Control', 'Session Termination | User-initiated Logouts', 'Provide a logout capability for user-initiated communications sessions whenever authentication is used to gain access to [Assignment: organization-defined information resources].'),
  ('AC-12(2)', 'NIST-800-53', 'Access Control', 'Session Termination | Termination Message', 'Display an explicit logout message to users indicating the termination of authenticated communications sessions.'),
  ('AC-12(3)', 'NIST-800-53', 'Access Control', 'Session Termination | Timeout Warning Message', 'Display an explicit message to users indicating that the session will end in [Assignment: organization-defined time].'),
  ('AC-14', 'NIST-800-53', 'Access Control', 'Permitted Actions Without Identification or Authentication', 'a. Identify [Assignment: organization-defined user actions] that can be performed on the system without identification or authentication consistent with organizational mission and business functions; and
b. Document and provide supporting rationale in the security plan for the system, user actions not requiring identification or authentication.'),
  ('AC-16', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes', 'a. Provide the means to associate [Assignment: organization-defined types of security and privacy attributes] with [Assignment: organization-defined security and privacy attribute values] for information in storage, in process, and/or in transmission;
b. Ensure that the attribute associations are made and retained with the information;
c. Establish the following permitted security and privacy attributes from the attributes defined in [AC-16a](#ac-16_smt.a) for [Assignment: organization-defined systems]: [Assignment: organization-defined security and privacy attributes];
d. Determine the following permitted attribute values or ranges for each of the established attributes: [Assignment: organization-defined attribute values or ranges];
e. Audit changes to attributes; and
f. Review [Assignment: organization-defined security and privacy attributes] for applicability [Assignment: organization-defined frequency].'),
  ('AC-16(1)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Dynamic Attribute Association', 'Dynamically associate security and privacy attributes with [Assignment: organization-defined subjects and objects] in accordance with the following security and privacy policies as information is created and combined: [Assignment: organization-defined security and privacy policies].'),
  ('AC-16(2)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Attribute Value Changes by Authorized Individuals', 'Provide authorized individuals (or processes acting on behalf of individuals) the capability to define or change the value of associated security and privacy attributes.'),
  ('AC-16(3)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Maintenance of Attribute Associations by System', 'Maintain the association and integrity of [Assignment: organization-defined security and privacy attributes] to [Assignment: organization-defined subjects and objects].'),
  ('AC-16(4)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Association of Attributes by Authorized Individuals', 'Provide the capability to associate [Assignment: organization-defined security and privacy attributes] with [Assignment: organization-defined subjects and objects] by authorized individuals (or processes acting on behalf of individuals).'),
  ('AC-16(5)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Attribute Displays on Objects to Be Output', 'Display security and privacy attributes in human-readable form on each object that the system transmits to output devices to identify [Assignment: organization-defined instructions] using [Assignment: organization-defined naming conventions].'),
  ('AC-16(6)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Maintenance of Attribute Association', 'Require personnel to associate and maintain the association of [Assignment: organization-defined security and privacy attributes] with [Assignment: organization-defined subjects and objects] in accordance with [Assignment: organization-defined security and privacy policies].'),
  ('AC-16(7)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Consistent Attribute Interpretation', 'Provide a consistent interpretation of security and privacy attributes transmitted between distributed system components.'),
  ('AC-16(8)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Association Techniques and Technologies', 'Implement [Assignment: organization-defined techniques and technologies] in associating security and privacy attributes to information.'),
  ('AC-16(9)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Attribute Reassignment — Regrading Mechanisms', 'Change security and privacy attributes associated with information only via regrading mechanisms validated using [Assignment: organization-defined techniques or procedures].'),
  ('AC-16(10)', 'NIST-800-53', 'Access Control', 'Security and Privacy Attributes | Attribute Configuration by Authorized Individuals', 'Provide authorized individuals the capability to define or change the type and value of security and privacy attributes available for association with subjects and objects.'),
  ('AC-17', 'NIST-800-53', 'Access Control', 'Remote Access', 'a. Establish and document usage restrictions, configuration/connection requirements, and implementation guidance for each type of remote access allowed; and
b. Authorize each type of remote access to the system prior to allowing such connections.'),
  ('AC-17(1)', 'NIST-800-53', 'Access Control', 'Remote Access | Monitoring and Control', 'Employ automated mechanisms to monitor and control remote access methods.'),
  ('AC-17(2)', 'NIST-800-53', 'Access Control', 'Remote Access | Protection of Confidentiality and Integrity Using Encryption', 'Implement cryptographic mechanisms to protect the confidentiality and integrity of remote access sessions.'),
  ('AC-17(3)', 'NIST-800-53', 'Access Control', 'Remote Access | Managed Access Control Points', 'Route remote accesses through authorized and managed network access control points.'),
  ('AC-17(4)', 'NIST-800-53', 'Access Control', 'Remote Access | Privileged Commands and Access', '(a) Authorize the execution of privileged commands and access to security-relevant information via remote access only in a format that provides assessable evidence and for the following needs: [Assignment: organization-defined needs] ; and
(b) Document the rationale for remote access in the security plan for the system.'),
  ('AC-17(6)', 'NIST-800-53', 'Access Control', 'Remote Access | Protection of Mechanism Information', 'Protect information about remote access mechanisms from unauthorized use and disclosure.'),
  ('AC-17(9)', 'NIST-800-53', 'Access Control', 'Remote Access | Disconnect or Disable Access', 'Provide the capability to disconnect or disable remote access to the system within [Assignment: organization-defined time period].'),
  ('AC-17(10)', 'NIST-800-53', 'Access Control', 'Remote Access | Authenticate Remote Commands', 'Implement [Assignment: organization-defined mechanisms] to authenticate [Assignment: organization-defined remote commands].'),
  ('AC-18', 'NIST-800-53', 'Access Control', 'Wireless Access', 'a. Establish configuration requirements, connection requirements, and implementation guidance for each type of wireless access; and
b. Authorize each type of wireless access to the system prior to allowing such connections.'),
  ('AC-18(1)', 'NIST-800-53', 'Access Control', 'Wireless Access | Authentication and Encryption', 'Protect wireless access to the system using authentication of [Selection (one or more): users; devices] and encryption.'),
  ('AC-18(3)', 'NIST-800-53', 'Access Control', 'Wireless Access | Disable Wireless Networking', 'Disable, when not intended for use, wireless networking capabilities embedded within system components prior to issuance and deployment.'),
  ('AC-18(4)', 'NIST-800-53', 'Access Control', 'Wireless Access | Restrict Configurations by Users', 'Identify and explicitly authorize users allowed to independently configure wireless networking capabilities.'),
  ('AC-18(5)', 'NIST-800-53', 'Access Control', 'Wireless Access | Antennas and Transmission Power Levels', 'Select radio antennas and calibrate transmission power levels to reduce the probability that signals from wireless access points can be received outside of organization-controlled boundaries.'),
  ('AC-19', 'NIST-800-53', 'Access Control', 'Access Control for Mobile Devices', 'a. Establish configuration requirements, connection requirements, and implementation guidance for organization-controlled mobile devices, to include when such devices are outside of controlled areas; and
b. Authorize the connection of mobile devices to organizational systems.'),
  ('AC-19(4)', 'NIST-800-53', 'Access Control', 'Access Control for Mobile Devices | Restrictions for Classified Information', '(a) Prohibit the use of unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information unless specifically permitted by the authorizing official; and
(b) Enforce the following restrictions on individuals permitted by the authorizing official to use unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information:
  (1) Connection of unclassified mobile devices to classified systems is prohibited;
  (2) Connection of unclassified mobile devices to unclassified systems requires approval from the authorizing official;
  (3) Use of internal or external modems or wireless interfaces within the unclassified mobile devices is prohibited; and
  (4) Unclassified mobile devices and the information stored on those devices are subject to random reviews and inspections by [Assignment: organization-defined security officials] , and if classified information is found, the incident handling policy is followed.
(c) Restrict the connection of classified mobile devices to classified systems in accordance with [Assignment: organization-defined security policies].'),
  ('AC-19(5)', 'NIST-800-53', 'Access Control', 'Access Control for Mobile Devices | Full Device or Container-based Encryption', 'Employ [Selection: full-device encryption; container-based encryption] to protect the confidentiality and integrity of information on [Assignment: organization-defined mobile devices].'),
  ('AC-20', 'NIST-800-53', 'Access Control', 'Use of External Systems', 'a. [Selection (one or more): establish [Assignment: organization-defined terms and conditions] ; identify [Assignment: organization-defined controls asserted] ] , consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to:
  1. Access the system from external systems; and
  2. Process, store, or transmit organization-controlled information using external systems; or
b. Prohibit the use of [Assignment: organization-defined prohibited types of external systems].'),
  ('AC-20(1)', 'NIST-800-53', 'Access Control', 'Use of External Systems | Limits on Authorized Use', 'Permit authorized individuals to use an external system to access the system or to process, store, or transmit organization-controlled information only after:
  (a) Verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans; or
  (b) Retention of approved system connection or processing agreements with the organizational entity hosting the external system.'),
  ('AC-20(2)', 'NIST-800-53', 'Access Control', 'Use of External Systems | Portable Storage Devices — Restricted Use', 'Restrict the use of organization-controlled portable storage devices by authorized individuals on external systems using [Assignment: organization-defined restrictions].'),
  ('AC-20(3)', 'NIST-800-53', 'Access Control', 'Use of External Systems | Non-organizationally Owned Systems — Restricted Use', 'Restrict the use of non-organizationally owned systems or system components to process, store, or transmit organizational information using [Assignment: organization-defined restrictions].'),
  ('AC-20(4)', 'NIST-800-53', 'Access Control', 'Use of External Systems | Network Accessible Storage Devices — Prohibited Use', 'Prohibit the use of [Assignment: organization-defined network-accessible storage devices] in external systems.'),
  ('AC-20(5)', 'NIST-800-53', 'Access Control', 'Use of External Systems | Portable Storage Devices — Prohibited Use', 'Prohibit the use of organization-controlled portable storage devices by authorized individuals on external systems.'),
  ('AC-21', 'NIST-800-53', 'Access Control', 'Information Sharing', 'a. Enable authorized users to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions for [Assignment: organization-defined information-sharing circumstances] ; and
b. Employ [Assignment: organization-defined automated mechanisms] to assist users in making information sharing and collaboration decisions.'),
  ('AC-21(1)', 'NIST-800-53', 'Access Control', 'Information Sharing | Automated Decision Support', 'Employ [Assignment: organization-defined automated mechanisms] to enforce information-sharing decisions by authorized users based on access authorizations of sharing partners and access restrictions on information to be shared.'),
  ('AC-21(2)', 'NIST-800-53', 'Access Control', 'Information Sharing | Information Search and Retrieval', 'Implement information search and retrieval services that enforce [Assignment: organization-defined information-sharing restrictions].'),
  ('AC-22', 'NIST-800-53', 'Access Control', 'Publicly Accessible Content', 'a. Designate individuals authorized to make information publicly accessible;
b. Train authorized individuals to ensure that publicly accessible information does not contain nonpublic information;
c. Review the proposed content of information prior to posting onto the publicly accessible system to ensure that nonpublic information is not included; and
d. Review the content on the publicly accessible system for nonpublic information [Assignment: organization-defined frequency] and remove such information, if discovered.'),
  ('AC-23', 'NIST-800-53', 'Access Control', 'Data Mining Protection', 'Employ [Assignment: organization-defined techniques] for [Assignment: organization-defined data storage objects] to detect and protect against unauthorized data mining.'),
  ('AC-24', 'NIST-800-53', 'Access Control', 'Access Control Decisions', '[Selection (one or more): establish procedures; implement mechanisms] to ensure [Assignment: organization-defined access control decisions] are applied to each access request prior to access enforcement.'),
  ('AC-24(1)', 'NIST-800-53', 'Access Control', 'Access Control Decisions | Transmit Access Authorization Information', 'Transmit [Assignment: organization-defined access authorization information] using [Assignment: organization-defined controls] to [Assignment: organization-defined systems] that enforce access control decisions.'),
  ('AC-24(2)', 'NIST-800-53', 'Access Control', 'Access Control Decisions | No User or Process Identity', 'Enforce access control decisions based on [Assignment: organization-defined security or privacy attributes] that do not include the identity of the user or process acting on behalf of the user.'),
  ('AC-25', 'NIST-800-53', 'Access Control', 'Reference Monitor', 'Implement a reference monitor for [Assignment: organization-defined access control policies] that is tamperproof, always invoked, and small enough to be subject to analysis and testing, the completeness of which can be assured.'),
  ('AT-1', 'NIST-800-53', 'Awareness and Training', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the awareness and training policy and the associated awareness and training controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the awareness and training policy and procedures; and
c. Review and update the current awareness and training:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('AT-2', 'NIST-800-53', 'Awareness and Training', 'Literacy Training and Awareness', 'a. Provide security and privacy literacy training to system users (including managers, senior executives, and contractors):
  1. As part of initial training for new users and [Assignment: organization-defined frequency] thereafter; and
  2. When required by system changes or following [Assignment: organization-defined events];
b. Employ the following techniques to increase the security and privacy awareness of system users [Assignment: organization-defined awareness techniques];
c. Update literacy training and awareness content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
d. Incorporate lessons learned from internal or external security incidents or breaches into literacy training and awareness techniques.'),
  ('AT-2(1)', 'NIST-800-53', 'Awareness and Training', 'Literacy Training and Awareness | Practical Exercises', 'Provide practical exercises in literacy training that simulate events and incidents.'),
  ('AT-2(2)', 'NIST-800-53', 'Awareness and Training', 'Literacy Training and Awareness | Insider Threat', 'Provide literacy training on recognizing and reporting potential indicators of insider threat.'),
  ('AT-2(3)', 'NIST-800-53', 'Awareness and Training', 'Literacy Training and Awareness | Social Engineering and Mining', 'Provide literacy training on recognizing and reporting potential and actual instances of social engineering and social mining.'),
  ('AT-2(4)', 'NIST-800-53', 'Awareness and Training', 'Literacy Training and Awareness | Suspicious Communications and Anomalous System Behavior', 'Provide literacy training on recognizing suspicious communications and anomalous behavior in organizational systems using [Assignment: organization-defined indicators of malicious code].'),
  ('AT-2(5)', 'NIST-800-53', 'Awareness and Training', 'Literacy Training and Awareness | Advanced Persistent Threat', 'Provide literacy training on the advanced persistent threat.'),
  ('AT-2(6)', 'NIST-800-53', 'Awareness and Training', 'Literacy Training and Awareness | Cyber Threat Environment', '(a) Provide literacy training on the cyber threat environment; and
(b) Reflect current cyber threat information in system operations.'),
  ('AT-3', 'NIST-800-53', 'Awareness and Training', 'Role-based Training', 'a. Provide role-based security and privacy training to personnel with the following roles and responsibilities: [Assignment: organization-defined roles and responsibilities]:
  1. Before authorizing access to the system, information, or performing assigned duties, and [Assignment: organization-defined frequency] thereafter; and
  2. When required by system changes;
b. Update role-based training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
c. Incorporate lessons learned from internal or external security incidents or breaches into role-based training.'),
  ('AT-3(1)', 'NIST-800-53', 'Awareness and Training', 'Role-based Training | Environmental Controls', 'Provide [Assignment: organization-defined personnel or roles] with initial and [Assignment: organization-defined frequency] training in the employment and operation of environmental controls.'),
  ('AT-3(2)', 'NIST-800-53', 'Awareness and Training', 'Role-based Training | Physical Security Controls', 'Provide [Assignment: organization-defined personnel or roles] with initial and [Assignment: organization-defined frequency] training in the employment and operation of physical security controls.'),
  ('AT-3(3)', 'NIST-800-53', 'Awareness and Training', 'Role-based Training | Practical Exercises', 'Provide practical exercises in security and privacy training that reinforce training objectives.'),
  ('AT-3(5)', 'NIST-800-53', 'Awareness and Training', 'Role-based Training | Processing Personally Identifiable Information', 'Provide [Assignment: organization-defined personnel or roles] with initial and [Assignment: organization-defined frequency] training in the employment and operation of personally identifiable information processing and transparency controls.'),
  ('AT-4', 'NIST-800-53', 'Awareness and Training', 'Training Records', 'a. Document and monitor information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training; and
b. Retain individual training records for [Assignment: organization-defined time period].'),
  ('AT-6', 'NIST-800-53', 'Awareness and Training', 'Training Feedback', 'Provide feedback on organizational training results to the following personnel [Assignment: organization-defined frequency]: [Assignment: organization-defined personnel].'),
  ('AU-1', 'NIST-800-53', 'Audit and Accountability', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] audit and accountability policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the audit and accountability policy and the associated audit and accountability controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the audit and accountability policy and procedures; and
c. Review and update the current audit and accountability:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('AU-2', 'NIST-800-53', 'Audit and Accountability', 'Event Logging', 'a. Identify the types of events that the system is capable of logging in support of the audit function: [Assignment: organization-defined event types];
b. Coordinate the event logging function with other organizational entities requiring audit-related information to guide and inform the selection criteria for events to be logged;
c. Specify the following event types for logging within the system: [Assignment: organization-defined event types (subset of the event types defined in [AU-2a.](#au-2_smt.a)) along with the frequency of (or situation requiring) logging for each identified event type];
d. Provide a rationale for why the event types selected for logging are deemed to be adequate to support after-the-fact investigations of incidents; and
e. Review and update the event types selected for logging [Assignment: organization-defined frequency].'),
  ('AU-3', 'NIST-800-53', 'Audit and Accountability', 'Content of Audit Records', 'Ensure that audit records contain information that establishes the following:
  a. What type of event occurred;
  b. When the event occurred;
  c. Where the event occurred;
  d. Source of the event;
  e. Outcome of the event; and
  f. Identity of any individuals, subjects, or objects/entities associated with the event.'),
  ('AU-3(1)', 'NIST-800-53', 'Audit and Accountability', 'Content of Audit Records | Additional Audit Information', 'Generate audit records containing the following additional information: [Assignment: organization-defined additional information].'),
  ('AU-3(3)', 'NIST-800-53', 'Audit and Accountability', 'Content of Audit Records | Limit Personally Identifiable Information Elements', 'Limit personally identifiable information contained in audit records to the following elements identified in the privacy risk assessment: [Assignment: organization-defined elements].'),
  ('AU-4', 'NIST-800-53', 'Audit and Accountability', 'Audit Log Storage Capacity', 'Allocate audit log storage capacity to accommodate [Assignment: organization-defined audit log retention requirements].'),
  ('AU-4(1)', 'NIST-800-53', 'Audit and Accountability', 'Audit Log Storage Capacity | Transfer to Alternate Storage', 'Transfer audit logs [Assignment: organization-defined frequency] to a different system, system component, or media other than the system or system component conducting the logging.'),
  ('AU-5', 'NIST-800-53', 'Audit and Accountability', 'Response to Audit Logging Process Failures', 'a. Alert [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period] in the event of an audit logging process failure; and
b. Take the following additional actions: [Assignment: organization-defined additional actions].'),
  ('AU-5(1)', 'NIST-800-53', 'Audit and Accountability', 'Response to Audit Logging Process Failures | Storage Capacity Warning', 'Provide a warning to [Assignment: organization-defined personnel, roles, and/or locations] within [Assignment: organization-defined time period] when allocated audit log storage volume reaches [Assignment: organization-defined percentage] of repository maximum audit log storage capacity.'),
  ('AU-5(2)', 'NIST-800-53', 'Audit and Accountability', 'Response to Audit Logging Process Failures | Real-time Alerts', 'Provide an alert within [Assignment: organization-defined real-time period] to [Assignment: organization-defined personnel, roles, and/or locations] when the following audit failure events occur: [Assignment: organization-defined audit logging failure events requiring real-time alerts].'),
  ('AU-5(3)', 'NIST-800-53', 'Audit and Accountability', 'Response to Audit Logging Process Failures | Configurable Traffic Volume Thresholds', 'Enforce configurable network communications traffic volume thresholds reflecting limits on audit log storage capacity and [Selection (one or more): reject; delay] network traffic above those thresholds.'),
  ('AU-5(4)', 'NIST-800-53', 'Audit and Accountability', 'Response to Audit Logging Process Failures | Shutdown on Failure', 'Invoke a [Selection (one or more): full system shutdown; partial system shutdown; degraded operational mode with limited mission or business functionality available] in the event of [Assignment: organization-defined audit logging failures] , unless an alternate audit logging capability exists.'),
  ('AU-5(5)', 'NIST-800-53', 'Audit and Accountability', 'Response to Audit Logging Process Failures | Alternate Audit Logging Capability', 'Provide an alternate audit logging capability in the event of a failure in primary audit logging capability that implements [Assignment: organization-defined alternate audit logging functionality].'),
  ('AU-6', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Review, Analysis, and Reporting', 'a. Review and analyze system audit records [Assignment: organization-defined frequency] for indications of [Assignment: organization-defined inappropriate or unusual activity] and the potential impact of the inappropriate or unusual activity;
b. Report findings to [Assignment: organization-defined personnel or roles] ; and
c. Adjust the level of audit record review, analysis, and reporting within the system when there is a change in risk based on law enforcement information, intelligence information, or other credible sources of information.'),
  ('AU-6(1)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Review, Analysis, and Reporting | Automated Process Integration', 'Integrate audit record review, analysis, and reporting processes using [Assignment: organization-defined automated mechanisms].'),
  ('AU-6(3)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Review, Analysis, and Reporting | Correlate Audit Record Repositories', 'Analyze and correlate audit records across different repositories to gain organization-wide situational awareness.'),
  ('AU-6(4)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Review, Analysis, and Reporting | Central Review and Analysis', 'Provide and implement the capability to centrally review and analyze audit records from multiple components within the system.'),
  ('AU-6(5)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Review, Analysis, and Reporting | Integrated Analysis of Audit Records', 'Integrate analysis of audit records with analysis of [Selection (one or more): vulnerability scanning information; performance data; system monitoring information; [Assignment: organization-defined data/information collected from other sources] ] to further enhance the ability to identify inappropriate or unusual activity.'),
  ('AU-6(6)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Review, Analysis, and Reporting | Correlation with Physical Monitoring', 'Correlate information from audit records with information obtained from monitoring physical access to further enhance the ability to identify suspicious, inappropriate, unusual, or malevolent activity.'),
  ('AU-6(7)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Review, Analysis, and Reporting | Permitted Actions', 'Specify the permitted actions for each [Selection (one or more): system process; role; user] associated with the review, analysis, and reporting of audit record information.'),
  ('AU-6(8)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Review, Analysis, and Reporting | Full Text Analysis of Privileged Commands', 'Perform a full text analysis of logged privileged commands in a physically distinct component or subsystem of the system, or other system that is dedicated to that analysis.'),
  ('AU-6(9)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Review, Analysis, and Reporting | Correlation with Information from Nontechnical Sources', 'Correlate information from nontechnical sources with audit record information to enhance organization-wide situational awareness.'),
  ('AU-7', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Reduction and Report Generation', 'Provide and implement an audit record reduction and report generation capability that:
  a. Supports on-demand audit record review, analysis, and reporting requirements and after-the-fact investigations of incidents; and
  b. Does not alter the original content or time ordering of audit records.'),
  ('AU-7(1)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Reduction and Report Generation | Automatic Processing', 'Provide and implement the capability to process, sort, and search audit records for events of interest based on the following content: [Assignment: organization-defined fields within audit records].'),
  ('AU-8', 'NIST-800-53', 'Audit and Accountability', 'Time Stamps', 'a. Use internal system clocks to generate time stamps for audit records; and
b. Record time stamps for audit records that meet [Assignment: organization-defined granularity of time measurement] and that use Coordinated Universal Time, have a fixed local time offset from Coordinated Universal Time, or that include the local time offset as part of the time stamp.'),
  ('AU-9', 'NIST-800-53', 'Audit and Accountability', 'Protection of Audit Information', 'a. Protect audit information and audit logging tools from unauthorized access, modification, and deletion; and
b. Alert [Assignment: organization-defined personnel or roles] upon detection of unauthorized access, modification, or deletion of audit information.'),
  ('AU-9(1)', 'NIST-800-53', 'Audit and Accountability', 'Protection of Audit Information | Hardware Write-once Media', 'Write audit trails to hardware-enforced, write-once media.'),
  ('AU-9(2)', 'NIST-800-53', 'Audit and Accountability', 'Protection of Audit Information | Store on Separate Physical Systems or Components', 'Store audit records [Assignment: organization-defined frequency] in a repository that is part of a physically different system or system component than the system or component being audited.'),
  ('AU-9(3)', 'NIST-800-53', 'Audit and Accountability', 'Protection of Audit Information | Cryptographic Protection', 'Implement cryptographic mechanisms to protect the integrity of audit information and audit tools.'),
  ('AU-9(4)', 'NIST-800-53', 'Audit and Accountability', 'Protection of Audit Information | Access by Subset of Privileged Users', 'Authorize access to management of audit logging functionality to only [Assignment: organization-defined subset of privileged users or roles].'),
  ('AU-9(5)', 'NIST-800-53', 'Audit and Accountability', 'Protection of Audit Information | Dual Authorization', 'Enforce dual authorization for [Selection (one or more): movement; deletion] of [Assignment: organization-defined audit information].'),
  ('AU-9(6)', 'NIST-800-53', 'Audit and Accountability', 'Protection of Audit Information | Read-only Access', 'Authorize read-only access to audit information to [Assignment: organization-defined subset of privileged users or roles].'),
  ('AU-9(7)', 'NIST-800-53', 'Audit and Accountability', 'Protection of Audit Information | Store on Component with Different Operating System', 'Store audit information on a component running a different operating system than the system or component being audited.'),
  ('AU-10', 'NIST-800-53', 'Audit and Accountability', 'Non-repudiation', 'Provide irrefutable evidence that an individual (or process acting on behalf of an individual) has performed [Assignment: organization-defined actions].'),
  ('AU-10(1)', 'NIST-800-53', 'Audit and Accountability', 'Non-repudiation | Association of Identities', '(a) Bind the identity of the information producer with the information to [Assignment: organization-defined strength of binding] ; and
(b) Provide the means for authorized individuals to determine the identity of the producer of the information.'),
  ('AU-10(2)', 'NIST-800-53', 'Audit and Accountability', 'Non-repudiation | Validate Binding of Information Producer Identity', '(a) Validate the binding of the information producer identity to the information at [Assignment: organization-defined frequency] ; and
(b) Perform [Assignment: organization-defined actions] in the event of a validation error.'),
  ('AU-10(3)', 'NIST-800-53', 'Audit and Accountability', 'Non-repudiation | Chain of Custody', 'Maintain reviewer or releaser credentials within the established chain of custody for information reviewed or released.'),
  ('AU-10(4)', 'NIST-800-53', 'Audit and Accountability', 'Non-repudiation | Validate Binding of Information Reviewer Identity', '(a) Validate the binding of the information reviewer identity to the information at the transfer or release points prior to release or transfer between [Assignment: organization-defined security domains] ; and
(b) Perform [Assignment: organization-defined actions] in the event of a validation error.'),
  ('AU-11', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Retention', 'Retain audit records for [Assignment: organization-defined time period] to provide support for after-the-fact investigations of incidents and to meet regulatory and organizational information retention requirements.'),
  ('AU-11(1)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Retention | Long-term Retrieval Capability', 'Employ [Assignment: organization-defined measures] to ensure that long-term audit records generated by the system can be retrieved.'),
  ('AU-12', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Generation', 'a. Provide audit record generation capability for the event types the system is capable of auditing as defined in [AU-2a](#au-2_smt.a) on [Assignment: organization-defined system components];
b. Allow [Assignment: organization-defined personnel or roles] to select the event types that are to be logged by specific components of the system; and
c. Generate audit records for the event types defined in [AU-2c](#au-2_smt.c) that include the audit record content defined in [AU-3](#au-3).'),
  ('AU-12(1)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Generation | System-wide and Time-correlated Audit Trail', 'Compile audit records from [Assignment: organization-defined system components] into a system-wide (logical or physical) audit trail that is time-correlated to within [Assignment: organization-defined level of tolerance].'),
  ('AU-12(2)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Generation | Standardized Formats', 'Produce a system-wide (logical or physical) audit trail composed of audit records in a standardized format.'),
  ('AU-12(3)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Generation | Changes by Authorized Individuals', 'Provide and implement the capability for [Assignment: organization-defined individuals or roles] to change the logging to be performed on [Assignment: organization-defined system components] based on [Assignment: organization-defined selectable event criteria] within [Assignment: organization-defined time thresholds].'),
  ('AU-12(4)', 'NIST-800-53', 'Audit and Accountability', 'Audit Record Generation | Query Parameter Audits of Personally Identifiable Information', 'Provide and implement the capability for auditing the parameters of user query events for data sets containing personally identifiable information.'),
  ('AU-13', 'NIST-800-53', 'Audit and Accountability', 'Monitoring for Information Disclosure', 'a. Monitor [Assignment: organization-defined open-source information and/or information sites] [Assignment: organization-defined frequency] for evidence of unauthorized disclosure of organizational information; and
b. If an information disclosure is discovered:
  1. Notify [Assignment: organization-defined personnel or roles] ; and
  2. Take the following additional actions: [Assignment: organization-defined additional actions].'),
  ('AU-13(1)', 'NIST-800-53', 'Audit and Accountability', 'Monitoring for Information Disclosure | Use of Automated Tools', 'Monitor open-source information and information sites using [Assignment: organization-defined automated mechanisms].'),
  ('AU-13(2)', 'NIST-800-53', 'Audit and Accountability', 'Monitoring for Information Disclosure | Review of Monitored Sites', 'Review the list of open-source information sites being monitored [Assignment: organization-defined frequency].'),
  ('AU-13(3)', 'NIST-800-53', 'Audit and Accountability', 'Monitoring for Information Disclosure | Unauthorized Replication of Information', 'Employ discovery techniques, processes, and tools to determine if external entities are replicating organizational information in an unauthorized manner.'),
  ('AU-14', 'NIST-800-53', 'Audit and Accountability', 'Session Audit', 'a. Provide and implement the capability for [Assignment: organization-defined users or roles] to [Selection (one or more): record; view; hear; log] the content of a user session under [Assignment: organization-defined circumstances] ; and
b. Develop, integrate, and use session auditing activities in consultation with legal counsel and in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.'),
  ('AU-14(1)', 'NIST-800-53', 'Audit and Accountability', 'Session Audit | System Start-up', 'Initiate session audits automatically at system start-up.'),
  ('AU-14(3)', 'NIST-800-53', 'Audit and Accountability', 'Session Audit | Remote Viewing and Listening', 'Provide and implement the capability for authorized users to remotely view and hear content related to an established user session in real time.'),
  ('AU-16', 'NIST-800-53', 'Audit and Accountability', 'Cross-organizational Audit Logging', 'Employ [Assignment: organization-defined methods] for coordinating [Assignment: organization-defined audit information] among external organizations when audit information is transmitted across organizational boundaries.'),
  ('AU-16(1)', 'NIST-800-53', 'Audit and Accountability', 'Cross-organizational Audit Logging | Identity Preservation', 'Preserve the identity of individuals in cross-organizational audit trails.')
ON CONFLICT (control_id) DO UPDATE
  SET family = EXCLUDED.family, title = EXCLUDED.title, description = EXCLUDED.description
  WHERE compliance_controls.framework = 'NIST-800-53';

INSERT INTO compliance_controls (control_id, framework, family, title, description) VALUES
  ('AU-16(2)', 'NIST-800-53', 'Audit and Accountability', 'Cross-organizational Audit Logging | Sharing of Audit Information', 'Provide cross-organizational audit information to [Assignment: organization-defined organizations] based on [Assignment: organization-defined cross-organizational sharing agreements].'),
  ('AU-16(3)', 'NIST-800-53', 'Audit and Accountability', 'Cross-organizational Audit Logging | Disassociability', 'Implement [Assignment: organization-defined measures] to disassociate individuals from audit information transmitted across organizational boundaries.'),
  ('CA-1', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the assessment, authorization, and monitoring policy and the associated assessment, authorization, and monitoring controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the assessment, authorization, and monitoring policy and procedures; and
c. Review and update the current assessment, authorization, and monitoring:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('CA-2', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Control Assessments', 'a. Select the appropriate assessor or assessment team for the type of assessment to be conducted;
b. Develop a control assessment plan that describes the scope of the assessment including:
  1. Controls and control enhancements under assessment;
  2. Assessment procedures to be used to determine control effectiveness; and
  3. Assessment environment, assessment team, and assessment roles and responsibilities;
c. Ensure the control assessment plan is reviewed and approved by the authorizing official or designated representative prior to conducting the assessment;
d. Assess the controls in the system and its environment of operation [Assignment: organization-defined assessment frequency] to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security and privacy requirements;
e. Produce a control assessment report that document the results of the assessment; and
f. Provide the results of the control assessment to [Assignment: organization-defined individuals or roles].'),
  ('CA-2(1)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Control Assessments | Independent Assessors', 'Employ independent assessors or assessment teams to conduct control assessments.'),
  ('CA-2(2)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Control Assessments | Specialized Assessments', 'Include as part of control assessments, [Assignment: organization-defined specialized assessment frequency], [Selection: announced; unannounced], [Selection (one or more): in-depth monitoring; security instrumentation; automated security test cases; vulnerability scanning; malicious user testing; insider threat assessment; performance and load testing; data leakage or data loss assessment; [Assignment: organization-defined other forms of assessment] ].'),
  ('CA-2(3)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Control Assessments | Leveraging Results from External Organizations', 'Leverage the results of control assessments performed by [Assignment: organization-defined external organization(s)] on [Assignment: organization-defined system] when the assessment meets [Assignment: organization-defined requirements].'),
  ('CA-3', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Information Exchange', 'a. Approve and manage the exchange of information between the system and other systems using [Selection (one or more): interconnection security agreements; information exchange security agreements; memoranda of understanding or agreement; service level agreements; user agreements; non-disclosure agreements; [Assignment: organization-defined type of agreement] ];
b. Document, as part of each exchange agreement, the interface characteristics, security and privacy requirements, controls, and responsibilities for each system, and the impact level of the information communicated; and
c. Review and update the agreements [Assignment: organization-defined frequency].'),
  ('CA-3(6)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Information Exchange | Transfer Authorizations', 'Verify that individuals or systems transferring data between interconnecting systems have the requisite authorizations (i.e., write permissions or privileges) prior to accepting such data.'),
  ('CA-3(7)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Information Exchange | Transitive Information Exchanges', '(a) Identify transitive (downstream) information exchanges with other systems through the systems identified in [CA-3a](#ca-3_smt.a) ; and
(b) Take measures to ensure that transitive (downstream) information exchanges cease when the controls on identified transitive (downstream) systems cannot be verified or validated.'),
  ('CA-5', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Plan of Action and Milestones', 'a. Develop a plan of action and milestones for the system to document the planned remediation actions of the organization to correct weaknesses or deficiencies noted during the assessment of the controls and to reduce or eliminate known vulnerabilities in the system; and
b. Update existing plan of action and milestones [Assignment: organization-defined frequency] based on the findings from control assessments, independent audits or reviews, and continuous monitoring activities.'),
  ('CA-5(1)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Plan of Action and Milestones | Automation Support for Accuracy and Currency', 'Ensure the accuracy, currency, and availability of the plan of action and milestones for the system using [Assignment: organization-defined automated mechanisms].'),
  ('CA-6', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Authorization', 'a. Assign a senior official as the authorizing official for the system;
b. Assign a senior official as the authorizing official for common controls available for inheritance by organizational systems;
c. Ensure that the authorizing official for the system, before commencing operations:
  1. Accepts the use of common controls inherited by the system; and
  2. Authorizes the system to operate;
d. Ensure that the authorizing official for common controls authorizes the use of those controls for inheritance by organizational systems;
e. Update the authorizations [Assignment: organization-defined frequency].'),
  ('CA-6(1)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Authorization | Joint Authorization — Intra-organization', 'Employ a joint authorization process for the system that includes multiple authorizing officials from the same organization conducting the authorization.'),
  ('CA-6(2)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Authorization | Joint Authorization — Inter-organization', 'Employ a joint authorization process for the system that includes multiple authorizing officials with at least one authorizing official from an organization external to the organization conducting the authorization.'),
  ('CA-7', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Continuous Monitoring', 'Develop a system-level continuous monitoring strategy and implement continuous monitoring in accordance with the organization-level continuous monitoring strategy that includes:
  a. Establishing the following system-level metrics to be monitored: [Assignment: organization-defined system-level metrics];
  b. Establishing [Assignment: organization-defined frequencies] for monitoring and [Assignment: organization-defined frequencies] for assessment of control effectiveness;
  c. Ongoing control assessments in accordance with the continuous monitoring strategy;
  d. Ongoing monitoring of system and organization-defined metrics in accordance with the continuous monitoring strategy;
  e. Correlation and analysis of information generated by control assessments and monitoring;
  f. Response actions to address results of the analysis of control assessment and monitoring information; and
  g. Reporting the security and privacy status of the system to [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency].'),
  ('CA-7(1)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Continuous Monitoring | Independent Assessment', 'Employ independent assessors or assessment teams to monitor the controls in the system on an ongoing basis.'),
  ('CA-7(3)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Continuous Monitoring | Trend Analyses', 'Employ trend analyses to determine if control implementations, the frequency of continuous monitoring activities, and the types of activities used in the continuous monitoring process need to be modified based on empirical data.'),
  ('CA-7(4)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Continuous Monitoring | Risk Monitoring', 'Ensure risk monitoring is an integral part of the continuous monitoring strategy that includes the following:
  (a) Effectiveness monitoring;
  (b) Compliance monitoring; and
  (c) Change monitoring.'),
  ('CA-7(5)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Continuous Monitoring | Consistency Analysis', 'Employ the following actions to validate that policies are established and implemented controls are operating in a consistent manner: [Assignment: organization-defined actions].'),
  ('CA-7(6)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Continuous Monitoring | Automation Support for Monitoring', 'Ensure the accuracy, currency, and availability of monitoring results for the system using [Assignment: organization-defined automated mechanisms].'),
  ('CA-8', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Penetration Testing', 'Conduct penetration testing [Assignment: organization-defined frequency] on [Assignment: organization-defined system(s) or system components].'),
  ('CA-8(1)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Penetration Testing | Independent Penetration Testing Agent or Team', 'Employ an independent penetration testing agent or team to perform penetration testing on the system or system components.'),
  ('CA-8(2)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Penetration Testing | Red Team Exercises', 'Employ the following red-team exercises to simulate attempts by adversaries to compromise organizational systems in accordance with applicable rules of engagement: [Assignment: organization-defined red team exercises].'),
  ('CA-8(3)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Penetration Testing | Facility Penetration Testing', 'Employ a penetration testing process that includes [Assignment: organization-defined frequency] [Selection (one or more): announced; unannounced] attempts to bypass or circumvent controls associated with physical access points to the facility.'),
  ('CA-9', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Internal System Connections', 'a. Authorize internal connections of [Assignment: organization-defined system components] to the system;
b. Document, for each internal connection, the interface characteristics, security and privacy requirements, and the nature of the information communicated;
c. Terminate internal system connections after [Assignment: organization-defined conditions] ; and
d. Review [Assignment: organization-defined frequency] the continued need for each internal connection.'),
  ('CA-9(1)', 'NIST-800-53', 'Assessment, Authorization, and Monitoring', 'Internal System Connections | Compliance Checks', 'Perform security and privacy compliance checks on constituent system components prior to the establishment of the internal connection.'),
  ('CM-1', 'NIST-800-53', 'Configuration Management', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] configuration management policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the configuration management policy and the associated configuration management controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the configuration management policy and procedures; and
c. Review and update the current configuration management:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('CM-2', 'NIST-800-53', 'Configuration Management', 'Baseline Configuration', 'a. Develop, document, and maintain under configuration control, a current baseline configuration of the system; and
b. Review and update the baseline configuration of the system:
  1. [Assignment: organization-defined frequency];
  2. When required due to [Assignment: organization-defined circumstances] ; and
  3. When system components are installed or upgraded.'),
  ('CM-2(2)', 'NIST-800-53', 'Configuration Management', 'Baseline Configuration | Automation Support for Accuracy and Currency', 'Maintain the currency, completeness, accuracy, and availability of the baseline configuration of the system using [Assignment: organization-defined automated mechanisms].'),
  ('CM-2(3)', 'NIST-800-53', 'Configuration Management', 'Baseline Configuration | Retention of Previous Configurations', 'Retain [Assignment: organization-defined number] of previous versions of baseline configurations of the system to support rollback.'),
  ('CM-2(6)', 'NIST-800-53', 'Configuration Management', 'Baseline Configuration | Development and Test Environments', 'Maintain a baseline configuration for system development and test environments that is managed separately from the operational baseline configuration.'),
  ('CM-2(7)', 'NIST-800-53', 'Configuration Management', 'Baseline Configuration | Configure Systems and Components for High-risk Areas', '(a) Issue [Assignment: organization-defined systems or system components] with [Assignment: organization-defined configurations] to individuals traveling to locations that the organization deems to be of significant risk; and
(b) Apply the following controls to the systems or components when the individuals return from travel: [Assignment: organization-defined controls].'),
  ('CM-3', 'NIST-800-53', 'Configuration Management', 'Configuration Change Control', 'a. Determine and document the types of changes to the system that are configuration-controlled;
b. Review proposed configuration-controlled changes to the system and approve or disapprove such changes with explicit consideration for security and privacy impact analyses;
c. Document configuration change decisions associated with the system;
d. Implement approved configuration-controlled changes to the system;
e. Retain records of configuration-controlled changes to the system for [Assignment: organization-defined time period];
f. Monitor and review activities associated with configuration-controlled changes to the system; and
g. Coordinate and provide oversight for configuration change control activities through [Assignment: organization-defined configuration change control element] that convenes [Selection (one or more): [Assignment: organization-defined frequency] ; when [Assignment: organization-defined configuration change conditions] ].'),
  ('CM-3(1)', 'NIST-800-53', 'Configuration Management', 'Configuration Change Control | Automated Documentation, Notification, and Prohibition of Changes', 'Use [Assignment: organization-defined automated mechanisms] to:
  (a) Document proposed changes to the system;
  (b) Notify [Assignment: organization-defined approval authorities] of proposed changes to the system and request change approval;
  (c) Highlight proposed changes to the system that have not been approved or disapproved within [Assignment: organization-defined time period];
  (d) Prohibit changes to the system until designated approvals are received;
  (e) Document all changes to the system; and
  (f) Notify [Assignment: organization-defined personnel] when approved changes to the system are completed.'),
  ('CM-3(2)', 'NIST-800-53', 'Configuration Management', 'Configuration Change Control | Testing, Validation, and Documentation of Changes', 'Test, validate, and document changes to the system before finalizing the implementation of the changes.'),
  ('CM-3(3)', 'NIST-800-53', 'Configuration Management', 'Configuration Change Control | Automated Change Implementation', 'Implement changes to the current system baseline and deploy the updated baseline across the installed base using [Assignment: organization-defined automated mechanisms].'),
  ('CM-3(4)', 'NIST-800-53', 'Configuration Management', 'Configuration Change Control | Security and Privacy Representatives', 'Require [Assignment: organization-defined security and privacy representatives] to be members of the [Assignment: organization-defined configuration change control element].'),
  ('CM-3(5)', 'NIST-800-53', 'Configuration Management', 'Configuration Change Control | Automated Security Response', 'Implement the following security responses automatically if baseline configurations are changed in an unauthorized manner: [Assignment: organization-defined security responses].'),
  ('CM-3(6)', 'NIST-800-53', 'Configuration Management', 'Configuration Change Control | Cryptography Management', 'Ensure that cryptographic mechanisms used to provide the following controls are under configuration management: [Assignment: organization-defined controls].'),
  ('CM-3(7)', 'NIST-800-53', 'Configuration Management', 'Configuration Change Control | Review System Changes', 'Review changes to the system [Assignment: organization-defined frequency] or when [Assignment: organization-defined circumstances] to determine whether unauthorized changes have occurred.'),
  ('CM-3(8)', 'NIST-800-53', 'Configuration Management', 'Configuration Change Control | Prevent or Restrict Configuration Changes', 'Prevent or restrict changes to the configuration of the system under the following circumstances: [Assignment: organization-defined circumstances].'),
  ('CM-4', 'NIST-800-53', 'Configuration Management', 'Impact Analyses', 'Analyze changes to the system to determine potential security and privacy impacts prior to change implementation.'),
  ('CM-4(1)', 'NIST-800-53', 'Configuration Management', 'Impact Analyses | Separate Test Environments', 'Analyze changes to the system in a separate test environment before implementation in an operational environment, looking for security and privacy impacts due to flaws, weaknesses, incompatibility, or intentional malice.'),
  ('CM-4(2)', 'NIST-800-53', 'Configuration Management', 'Impact Analyses | Verification of Controls', 'After system changes, verify that the impacted controls are implemented correctly, operating as intended, and producing the desired outcome with regard to meeting the security and privacy requirements for the system.'),
  ('CM-5', 'NIST-800-53', 'Configuration Management', 'Access Restrictions for Change', 'Define, document, approve, and enforce physical and logical access restrictions associated with changes to the system.'),
  ('CM-5(1)', 'NIST-800-53', 'Configuration Management', 'Access Restrictions for Change | Automated Access Enforcement and Audit Records', '(a) Enforce access restrictions using [Assignment: organization-defined automated mechanisms] ; and
(b) Automatically generate audit records of the enforcement actions.'),
  ('CM-5(4)', 'NIST-800-53', 'Configuration Management', 'Access Restrictions for Change | Dual Authorization', 'Enforce dual authorization for implementing changes to [Assignment: organization-defined system components and system-level information].'),
  ('CM-5(5)', 'NIST-800-53', 'Configuration Management', 'Access Restrictions for Change | Privilege Limitation for Production and Operation', '(a) Limit privileges to change system components and system-related information within a production or operational environment; and
(b) Review and reevaluate privileges [Assignment: organization-defined frequency].'),
  ('CM-5(6)', 'NIST-800-53', 'Configuration Management', 'Access Restrictions for Change | Limit Library Privileges', 'Limit privileges to change software resident within software libraries.'),
  ('CM-6', 'NIST-800-53', 'Configuration Management', 'Configuration Settings', 'a. Establish and document configuration settings for components employed within the system that reflect the most restrictive mode consistent with operational requirements using [Assignment: organization-defined common secure configurations];
b. Implement the configuration settings;
c. Identify, document, and approve any deviations from established configuration settings for [Assignment: organization-defined system components] based on [Assignment: organization-defined operational requirements] ; and
d. Monitor and control changes to the configuration settings in accordance with organizational policies and procedures.'),
  ('CM-6(1)', 'NIST-800-53', 'Configuration Management', 'Configuration Settings | Automated Management, Application, and Verification', 'Manage, apply, and verify configuration settings for [Assignment: organization-defined system components] using [Assignment: organization-defined automated mechanisms].'),
  ('CM-6(2)', 'NIST-800-53', 'Configuration Management', 'Configuration Settings | Respond to Unauthorized Changes', 'Take the following actions in response to unauthorized changes to [Assignment: organization-defined configuration settings]: [Assignment: organization-defined actions].'),
  ('CM-7', 'NIST-800-53', 'Configuration Management', 'Least Functionality', 'a. Configure the system to provide only [Assignment: organization-defined mission-essential capabilities] ; and
b. Prohibit or restrict the use of the following functions, ports, protocols, software, and/or services: [Assignment: organization-defined prohibited or restricted functions, system ports, protocols, software, and/or services].'),
  ('CM-7(1)', 'NIST-800-53', 'Configuration Management', 'Least Functionality | Periodic Review', '(a) Review the system [Assignment: organization-defined frequency] to identify unnecessary and/or nonsecure functions, ports, protocols, software, and services; and
(b) Disable or remove [Assignment: organization-defined functions, ports, protocols, software, and services within the system deemed to be unnecessary and/or nonsecure].'),
  ('CM-7(2)', 'NIST-800-53', 'Configuration Management', 'Least Functionality | Prevent Program Execution', 'Prevent program execution in accordance with [Selection (one or more): [Assignment: organization-defined policies, rules of behavior, and/or access agreements regarding software program usage and restrictions] ; rules authorizing the terms and conditions of software program usage].'),
  ('CM-7(3)', 'NIST-800-53', 'Configuration Management', 'Least Functionality | Registration Compliance', 'Ensure compliance with [Assignment: organization-defined registration requirements].'),
  ('CM-7(4)', 'NIST-800-53', 'Configuration Management', 'Least Functionality | Unauthorized Software — Deny-by-exception', '(a) Identify [Assignment: organization-defined software programs];
(b) Employ an allow-all, deny-by-exception policy to prohibit the execution of unauthorized software programs on the system; and
(c) Review and update the list of unauthorized software programs [Assignment: organization-defined frequency].'),
  ('CM-7(5)', 'NIST-800-53', 'Configuration Management', 'Least Functionality | Authorized Software — Allow-by-exception', '(a) Identify [Assignment: organization-defined software programs];
(b) Employ a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the system; and
(c) Review and update the list of authorized software programs [Assignment: organization-defined frequency].'),
  ('CM-7(6)', 'NIST-800-53', 'Configuration Management', 'Least Functionality | Confined Environments with Limited Privileges', 'Require that the following user-installed software execute in a confined physical or virtual machine environment with limited privileges: [Assignment: organization-defined user-installed software].'),
  ('CM-7(7)', 'NIST-800-53', 'Configuration Management', 'Least Functionality | Code Execution in Protected Environments', 'Allow execution of binary or machine-executable code only in confined physical or virtual machine environments and with the explicit approval of [Assignment: organization-defined personnel or roles] when such code is:
  (a) Obtained from sources with limited or no warranty; and/or
  (b) Without the provision of source code.'),
  ('CM-7(8)', 'NIST-800-53', 'Configuration Management', 'Least Functionality | Binary or Machine Executable Code', '(a) Prohibit the use of binary or machine-executable code from sources with limited or no warranty or without the provision of source code; and
(b) Allow exceptions only for compelling mission or operational requirements and with the approval of the authorizing official.'),
  ('CM-7(9)', 'NIST-800-53', 'Configuration Management', 'Least Functionality | Prohibiting The Use of Unauthorized Hardware', '(a) Identify [Assignment: organization-defined hardware components];
(b) Prohibit the use or connection of unauthorized hardware components;
(c) Review and update the list of authorized hardware components [Assignment: organization-defined frequency].'),
  ('CM-8', 'NIST-800-53', 'Configuration Management', 'System Component Inventory', 'a. Develop and document an inventory of system components that:
  1. Accurately reflects the system;
  2. Includes all components within the system;
  3. Does not include duplicate accounting of components or components assigned to any other system;
  4. Is at the level of granularity deemed necessary for tracking and reporting; and
  5. Includes the following information to achieve system component accountability: [Assignment: organization-defined information] ; and
b. Review and update the system component inventory [Assignment: organization-defined frequency].'),
  ('CM-8(1)', 'NIST-800-53', 'Configuration Management', 'System Component Inventory | Updates During Installation and Removal', 'Update the inventory of system components as part of component installations, removals, and system updates.'),
  ('CM-8(2)', 'NIST-800-53', 'Configuration Management', 'System Component Inventory | Automated Maintenance', 'Maintain the currency, completeness, accuracy, and availability of the inventory of system components using [Assignment: organization-defined automated mechanisms].'),
  ('CM-8(3)', 'NIST-800-53', 'Configuration Management', 'System Component Inventory | Automated Unauthorized Component Detection', '(a) Detect the presence of unauthorized hardware, software, and firmware components within the system using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency] ; and
(b) Take the following actions when unauthorized components are detected: [Selection (one or more): disable network access by unauthorized components; isolate unauthorized components; notify [Assignment: organization-defined personnel or roles] ].'),
  ('CM-8(4)', 'NIST-800-53', 'Configuration Management', 'System Component Inventory | Accountability Information', 'Include in the system component inventory information, a means for identifying by [Selection (one or more): name; position; role] , individuals responsible and accountable for administering those components.'),
  ('CM-8(6)', 'NIST-800-53', 'Configuration Management', 'System Component Inventory | Assessed Configurations and Approved Deviations', 'Include assessed component configurations and any approved deviations to current deployed configurations in the system component inventory.'),
  ('CM-8(7)', 'NIST-800-53', 'Configuration Management', 'System Component Inventory | Centralized Repository', 'Provide a centralized repository for the inventory of system components.'),
  ('CM-8(8)', 'NIST-800-53', 'Configuration Management', 'System Component Inventory | Automated Location Tracking', 'Support the tracking of system components by geographic location using [Assignment: organization-defined automated mechanisms].'),
  ('CM-8(9)', 'NIST-800-53', 'Configuration Management', 'System Component Inventory | Assignment of Components to Systems', '(a) Assign system components to a system; and
(b) Receive an acknowledgement from [Assignment: organization-defined personnel or roles] of this assignment.'),
  ('CM-9', 'NIST-800-53', 'Configuration Management', 'Configuration Management Plan', 'Develop, document, and implement a configuration management plan for the system that:
  a. Addresses roles, responsibilities, and configuration management processes and procedures;
  b. Establishes a process for identifying configuration items throughout the system development life cycle and for managing the configuration of the configuration items;
  c. Defines the configuration items for the system and places the configuration items under configuration management;
  d. Is reviewed and approved by [Assignment: organization-defined personnel or roles] ; and
  e. Protects the configuration management plan from unauthorized disclosure and modification.'),
  ('CM-9(1)', 'NIST-800-53', 'Configuration Management', 'Configuration Management Plan | Assignment of Responsibility', 'Assign responsibility for developing the configuration management process to organizational personnel that are not directly involved in system development.'),
  ('CM-10', 'NIST-800-53', 'Configuration Management', 'Software Usage Restrictions', 'a. Use software and associated documentation in accordance with contract agreements and copyright laws;
b. Track the use of software and associated documentation protected by quantity licenses to control copying and distribution; and
c. Control and document the use of peer-to-peer file sharing technology to ensure that this capability is not used for the unauthorized distribution, display, performance, or reproduction of copyrighted work.'),
  ('CM-10(1)', 'NIST-800-53', 'Configuration Management', 'Software Usage Restrictions | Open-source Software', 'Establish the following restrictions on the use of open-source software: [Assignment: organization-defined restrictions].'),
  ('CM-11', 'NIST-800-53', 'Configuration Management', 'User-installed Software', 'a. Establish [Assignment: organization-defined policies] governing the installation of software by users;
b. Enforce software installation policies through the following methods: [Assignment: organization-defined methods] ; and
c. Monitor policy compliance [Assignment: organization-defined frequency].'),
  ('CM-11(2)', 'NIST-800-53', 'Configuration Management', 'User-installed Software | Software Installation with Privileged Status', 'Allow user installation of software only with explicit privileged status.'),
  ('CM-11(3)', 'NIST-800-53', 'Configuration Management', 'User-installed Software | Automated Enforcement and Monitoring', 'Enforce and monitor compliance with software installation policies using [Assignment: organization-defined automated mechanisms].'),
  ('CM-12', 'NIST-800-53', 'Configuration Management', 'Information Location', 'a. Identify and document the location of [Assignment: organization-defined information] and the specific system components on which the information is processed and stored;
b. Identify and document the users who have access to the system and system components where the information is processed and stored; and
c. Document changes to the location (i.e., system or system components) where the information is processed and stored.'),
  ('CM-12(1)', 'NIST-800-53', 'Configuration Management', 'Information Location | Automated Tools to Support Information Location', 'Use automated tools to identify [Assignment: organization-defined information by information type] on [Assignment: organization-defined system components] to ensure controls are in place to protect organizational information and individual privacy.'),
  ('CM-13', 'NIST-800-53', 'Configuration Management', 'Data Action Mapping', 'Develop and document a map of system data actions.'),
  ('CM-14', 'NIST-800-53', 'Configuration Management', 'Signed Components', 'Prevent the installation of [Assignment: organization-defined software and firmware components] without verification that the component has been digitally signed using a certificate that is recognized and approved by the organization.'),
  ('CP-1', 'NIST-800-53', 'Contingency Planning', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the contingency planning policy and the associated contingency planning controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the contingency planning policy and procedures; and
c. Review and update the current contingency planning:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('CP-2', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan', 'a. Develop a contingency plan for the system that:
  1. Identifies essential mission and business functions and associated contingency requirements;
  2. Provides recovery objectives, restoration priorities, and metrics;
  3. Addresses contingency roles, responsibilities, assigned individuals with contact information;
  4. Addresses maintaining essential mission and business functions despite a system disruption, compromise, or failure;
  5. Addresses eventual, full system restoration without deterioration of the controls originally planned and implemented;
  6. Addresses the sharing of contingency information; and
  7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];
b. Distribute copies of the contingency plan to [Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements];
c. Coordinate contingency planning activities with incident handling activities;
d. Review the contingency plan for the system [Assignment: organization-defined frequency];
e. Update the contingency plan to address changes to the organization, system, or environment of operation and problems encountered during contingency plan implementation, execution, or testing;
f. Communicate contingency plan changes to [Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements];
g. Incorporate lessons learned from contingency plan testing, training, or actual contingency activities into contingency testing and training; and
h. Protect the contingency plan from unauthorized disclosure and modification.'),
  ('CP-2(1)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan | Coordinate with Related Plans', 'Coordinate contingency plan development with organizational elements responsible for related plans.'),
  ('CP-2(2)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan | Capacity Planning', 'Conduct capacity planning so that necessary capacity for information processing, telecommunications, and environmental support exists during contingency operations.'),
  ('CP-2(3)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan | Resume Mission and Business Functions', 'Plan for the resumption of [Selection: all; essential] mission and business functions within [Assignment: organization-defined time period] of contingency plan activation.'),
  ('CP-2(5)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan | Continue Mission and Business Functions', 'Plan for the continuance of [Selection: all; essential] mission and business functions with minimal or no loss of operational continuity and sustains that continuity until full system restoration at primary processing and/or storage sites.'),
  ('CP-2(6)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan | Alternate Processing and Storage Sites', 'Plan for the transfer of [Selection: all; essential] mission and business functions to alternate processing and/or storage sites with minimal or no loss of operational continuity and sustain that continuity through system restoration to primary processing and/or storage sites.'),
  ('CP-2(7)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan | Coordinate with External Service Providers', 'Coordinate the contingency plan with the contingency plans of external service providers to ensure that contingency requirements can be satisfied.'),
  ('CP-2(8)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan | Identify Critical Assets', 'Identify critical system assets supporting [Selection: all; essential] mission and business functions.'),
  ('CP-3', 'NIST-800-53', 'Contingency Planning', 'Contingency Training', 'a. Provide contingency training to system users consistent with assigned roles and responsibilities:
  1. Within [Assignment: organization-defined time period] of assuming a contingency role or responsibility;
  2. When required by system changes; and
  3. [Assignment: organization-defined frequency] thereafter; and
b. Review and update contingency training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('CP-3(1)', 'NIST-800-53', 'Contingency Planning', 'Contingency Training | Simulated Events', 'Incorporate simulated events into contingency training to facilitate effective response by personnel in crisis situations.'),
  ('CP-3(2)', 'NIST-800-53', 'Contingency Planning', 'Contingency Training | Mechanisms Used in Training Environments', 'Employ mechanisms used in operations to provide a more thorough and realistic contingency training environment.'),
  ('CP-4', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan Testing', 'a. Test the contingency plan for the system [Assignment: organization-defined frequency] using the following tests to determine the effectiveness of the plan and the readiness to execute the plan: [Assignment: organization-defined tests].
b. Review the contingency plan test results; and
c. Initiate corrective actions, if needed.'),
  ('CP-4(1)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan Testing | Coordinate with Related Plans', 'Coordinate contingency plan testing with organizational elements responsible for related plans.'),
  ('CP-4(2)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan Testing | Alternate Processing Site', 'Test the contingency plan at the alternate processing site:
  (a) To familiarize contingency personnel with the facility and available resources; and
  (b) To evaluate the capabilities of the alternate processing site to support contingency operations.'),
  ('CP-4(3)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan Testing | Automated Testing', 'Test the contingency plan using [Assignment: organization-defined automated mechanisms].'),
  ('CP-4(4)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan Testing | Full Recovery and Reconstitution', 'Include a full recovery and reconstitution of the system to a known state as part of contingency plan testing.'),
  ('CP-4(5)', 'NIST-800-53', 'Contingency Planning', 'Contingency Plan Testing | Self-challenge', 'Employ [Assignment: organization-defined mechanisms] to [Assignment: organization-defined system or system component] to disrupt and adversely affect the system or system component.'),
  ('CP-6', 'NIST-800-53', 'Contingency Planning', 'Alternate Storage Site', 'a. Establish an alternate storage site, including necessary agreements to permit the storage and retrieval of system backup information; and
b. Ensure that the alternate storage site provides controls equivalent to that of the primary site.'),
  ('CP-6(1)', 'NIST-800-53', 'Contingency Planning', 'Alternate Storage Site | Separation from Primary Site', 'Identify an alternate storage site that is sufficiently separated from the primary storage site to reduce susceptibility to the same threats.'),
  ('CP-6(2)', 'NIST-800-53', 'Contingency Planning', 'Alternate Storage Site | Recovery Time and Recovery Point Objectives', 'Configure the alternate storage site to facilitate recovery operations in accordance with recovery time and recovery point objectives.'),
  ('CP-6(3)', 'NIST-800-53', 'Contingency Planning', 'Alternate Storage Site | Accessibility', 'Identify potential accessibility problems to the alternate storage site in the event of an area-wide disruption or disaster and outline explicit mitigation actions.'),
  ('CP-7', 'NIST-800-53', 'Contingency Planning', 'Alternate Processing Site', 'a. Establish an alternate processing site, including necessary agreements to permit the transfer and resumption of [Assignment: organization-defined system operations] for essential mission and business functions within [Assignment: organization-defined time period] when the primary processing capabilities are unavailable;
b. Make available at the alternate processing site, the equipment and supplies required to transfer and resume operations or put contracts in place to support delivery to the site within the organization-defined time period for transfer and resumption; and
c. Provide controls at the alternate processing site that are equivalent to those at the primary site.'),
  ('CP-7(1)', 'NIST-800-53', 'Contingency Planning', 'Alternate Processing Site | Separation from Primary Site', 'Identify an alternate processing site that is sufficiently separated from the primary processing site to reduce susceptibility to the same threats.'),
  ('CP-7(2)', 'NIST-800-53', 'Contingency Planning', 'Alternate Processing Site | Accessibility', 'Identify potential accessibility problems to alternate processing sites in the event of an area-wide disruption or disaster and outlines explicit mitigation actions.'),
  ('CP-7(3)', 'NIST-800-53', 'Contingency Planning', 'Alternate Processing Site | Priority of Service', 'Develop alternate processing site agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives).'),
  ('CP-7(4)', 'NIST-800-53', 'Contingency Planning', 'Alternate Processing Site | Preparation for Use', 'Prepare the alternate processing site so that the site can serve as the operational site supporting essential mission and business functions.'),
  ('CP-7(6)', 'NIST-800-53', 'Contingency Planning', 'Alternate Processing Site | Inability to Return to Primary Site', 'Plan and prepare for circumstances that preclude returning to the primary processing site.'),
  ('CP-8', 'NIST-800-53', 'Contingency Planning', 'Telecommunications Services', 'Establish alternate telecommunications services, including necessary agreements to permit the resumption of [Assignment: organization-defined system operations] for essential mission and business functions within [Assignment: organization-defined time period] when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites.'),
  ('CP-8(1)', 'NIST-800-53', 'Contingency Planning', 'Telecommunications Services | Priority of Service Provisions', '(a) Develop primary and alternate telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives); and
(b) Request Telecommunications Service Priority for all telecommunications services used for national security emergency preparedness if the primary and/or alternate telecommunications services are provided by a common carrier.'),
  ('CP-8(2)', 'NIST-800-53', 'Contingency Planning', 'Telecommunications Services | Single Points of Failure', 'Obtain alternate telecommunications services to reduce the likelihood of sharing a single point of failure with primary telecommunications services.'),
  ('CP-8(3)', 'NIST-800-53', 'Contingency Planning', 'Telecommunications Services | Separation of Primary and Alternate Providers', 'Obtain alternate telecommunications services from providers that are separated from primary service providers to reduce susceptibility to the same threats.'),
  ('CP-8(4)', 'NIST-800-53', 'Contingency Planning', 'Telecommunications Services | Provider Contingency Plan', '(a) Require primary and alternate telecommunications service providers to have contingency plans;
(b) Review provider contingency plans to ensure that the plans meet organizational contingency requirements; and
(c) Obtain evidence of contingency testing and training by providers [Assignment: organization-defined frequency].'),
  ('CP-8(5)', 'NIST-800-53', 'Contingency Planning', 'Telecommunications Services | Alternate Telecommunication Service Testing', 'Test alternate telecommunication services [Assignment: organization-defined frequency].'),
  ('CP-9', 'NIST-800-53', 'Contingency Planning', 'System Backup', 'a. Conduct backups of user-level information contained in [Assignment: organization-defined system components] [Assignment: organization-defined frequency];
b. Conduct backups of system-level information contained in the system [Assignment: organization-defined frequency];
c. Conduct backups of system documentation, including security- and privacy-related documentation [Assignment: organization-defined frequency] ; and
d. Protect the confidentiality, integrity, and availability of backup information.'),
  ('CP-9(1)', 'NIST-800-53', 'Contingency Planning', 'System Backup | Testing for Reliability and Integrity', 'Test backup information [Assignment: organization-defined frequency] to verify media reliability and information integrity.'),
  ('CP-9(2)', 'NIST-800-53', 'Contingency Planning', 'System Backup | Test Restoration Using Sampling', 'Use a sample of backup information in the restoration of selected system functions as part of contingency plan testing.'),
  ('CP-9(3)', 'NIST-800-53', 'Contingency Planning', 'System Backup | Separate Storage for Critical Information', 'Store backup copies of [Assignment: organization-defined critical system software and other security-related information] in a separate facility or in a fire rated container that is not collocated with the operational system.'),
  ('CP-9(5)', 'NIST-800-53', 'Contingency Planning', 'System Backup | Transfer to Alternate Storage Site', 'Transfer system backup information to the alternate storage site [Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives].'),
  ('CP-9(6)', 'NIST-800-53', 'Contingency Planning', 'System Backup | Redundant Secondary System', 'Conduct system backup by maintaining a redundant secondary system that is not collocated with the primary system and that can be activated without loss of information or disruption to operations.'),
  ('CP-9(7)', 'NIST-800-53', 'Contingency Planning', 'System Backup | Dual Authorization for Deletion or Destruction', 'Enforce dual authorization for the deletion or destruction of [Assignment: organization-defined backup information].'),
  ('CP-9(8)', 'NIST-800-53', 'Contingency Planning', 'System Backup | Cryptographic Protection', 'Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of [Assignment: organization-defined backup information].'),
  ('CP-10', 'NIST-800-53', 'Contingency Planning', 'System Recovery and Reconstitution', 'Provide for the recovery and reconstitution of the system to a known state within [Assignment: organization-defined time period consistent with recovery time and recovery point objectives] after a disruption, compromise, or failure.'),
  ('CP-10(2)', 'NIST-800-53', 'Contingency Planning', 'System Recovery and Reconstitution | Transaction Recovery', 'Implement transaction recovery for systems that are transaction-based.'),
  ('CP-10(4)', 'NIST-800-53', 'Contingency Planning', 'System Recovery and Reconstitution | Restore Within Time Period', 'Provide the capability to restore system components within [Assignment: organization-defined restoration time periods] from configuration-controlled and integrity-protected information representing a known, operational state for the components.'),
  ('CP-10(6)', 'NIST-800-53', 'Contingency Planning', 'System Recovery and Reconstitution | Component Protection', 'Protect system components used for recovery and reconstitution.'),
  ('CP-11', 'NIST-800-53', 'Contingency Planning', 'Alternate Communications Protocols', 'Provide the capability to employ [Assignment: organization-defined alternative communications protocols] in support of maintaining continuity of operations.'),
  ('CP-12', 'NIST-800-53', 'Contingency Planning', 'Safe Mode', 'When [Assignment: organization-defined conditions] are detected, enter a safe mode of operation with [Assignment: organization-defined restrictions].'),
  ('CP-13', 'NIST-800-53', 'Contingency Planning', 'Alternative Security Mechanisms', 'Employ [Assignment: organization-defined alternative or supplemental security mechanisms] for satisfying [Assignment: organization-defined security functions] when the primary means of implementing the security function is unavailable or compromised.'),
  ('IA-1', 'NIST-800-53', 'Identification and Authentication', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the identification and authentication policy and the associated identification and authentication controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the identification and authentication policy and procedures; and
c. Review and update the current identification and authentication:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('IA-2', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Organizational Users)', 'Uniquely identify and authenticate organizational users and associate that unique identification with processes acting on behalf of those users.'),
  ('IA-2(1)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Organizational Users) | Multi-factor Authentication to Privileged Accounts', 'Implement multi-factor authentication for access to privileged accounts.'),
  ('IA-2(2)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Organizational Users) | Multi-factor Authentication to Non-privileged Accounts', 'Implement multi-factor authentication for access to non-privileged accounts.'),
  ('IA-2(5)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Organizational Users) | Individual Authentication with Group Authentication', 'When shared accounts or authenticators are employed, require users to be individually authenticated before granting access to the shared accounts or resources.'),
  ('IA-2(6)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Organizational Users) | Access to Accounts —separate Device', 'Implement multi-factor authentication for [Selection (one or more): local; network; remote] access to [Selection (one or more): privileged accounts; non-privileged accounts] such that:
  (a) One of the factors is provided by a device separate from the system gaining access; and
  (b) The device meets [Assignment: organization-defined strength of mechanism requirements].'),
  ('IA-2(8)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Organizational Users) | Access to Accounts — Replay Resistant', 'Implement replay-resistant authentication mechanisms for access to [Selection (one or more): privileged accounts; non-privileged accounts].'),
  ('IA-2(10)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Organizational Users) | Single Sign-on', 'Provide a single sign-on capability for [Assignment: organization-defined system accounts and services].'),
  ('IA-2(12)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Organizational Users) | Acceptance of PIV Credentials', 'Accept and electronically verify Personal Identity Verification-compliant credentials.'),
  ('IA-2(13)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Organizational Users) | Out-of-band Authentication', 'Implement the following out-of-band authentication mechanisms under [Assignment: organization-defined conditions]: [Assignment: organization-defined out-of-band authentication].'),
  ('IA-3', 'NIST-800-53', 'Identification and Authentication', 'Device Identification and Authentication', 'Uniquely identify and authenticate [Assignment: organization-defined devices and/or types of devices] before establishing a [Selection (one or more): local; remote; network] connection.'),
  ('IA-3(1)', 'NIST-800-53', 'Identification and Authentication', 'Device Identification and Authentication | Cryptographic Bidirectional Authentication', 'Authenticate [Assignment: organization-defined devices and/or types of devices] before establishing [Selection (one or more): local; remote; network] connection using bidirectional authentication that is cryptographically based.'),
  ('IA-3(3)', 'NIST-800-53', 'Identification and Authentication', 'Device Identification and Authentication | Dynamic Address Allocation', '(a) Where addresses are allocated dynamically, standardize dynamic address allocation lease information and the lease duration assigned to devices in accordance with [Assignment: organization-defined lease information and lease duration] ; and
(b) Audit lease information when assigned to a device.'),
  ('IA-3(4)', 'NIST-800-53', 'Identification and Authentication', 'Device Identification and Authentication | Device Attestation', 'Handle device identification and authentication based on attestation by [Assignment: organization-defined configuration management process].'),
  ('IA-4', 'NIST-800-53', 'Identification and Authentication', 'Identifier Management', 'Manage system identifiers by:
  a. Receiving authorization from [Assignment: organization-defined personnel or roles] to assign an individual, group, role, service, or device identifier;
  b. Selecting an identifier that identifies an individual, group, role, service, or device;
  c. Assigning the identifier to the intended individual, group, role, service, or device; and
  d. Preventing reuse of identifiers for [Assignment: organization-defined time period].'),
  ('IA-4(1)', 'NIST-800-53', 'Identification and Authentication', 'Identifier Management | Prohibit Account Identifiers as Public Identifiers', 'Prohibit the use of system account identifiers that are the same as public identifiers for individual accounts.'),
  ('IA-4(4)', 'NIST-800-53', 'Identification and Authentication', 'Identifier Management | Identify User Status', 'Manage individual identifiers by uniquely identifying each individual as [Assignment: organization-defined characteristics].'),
  ('IA-4(5)', 'NIST-800-53', 'Identification and Authentication', 'Identifier Management | Dynamic Management', 'Manage individual identifiers dynamically in accordance with [Assignment: organization-defined dynamic identifier policy].'),
  ('IA-4(6)', 'NIST-800-53', 'Identification and Authentication', 'Identifier Management | Cross-organization Management', 'Coordinate with the following external organizations for cross-organization management of identifiers: [Assignment: organization-defined external organizations].'),
  ('IA-4(8)', 'NIST-800-53', 'Identification and Authentication', 'Identifier Management | Pairwise Pseudonymous Identifiers', 'Generate pairwise pseudonymous identifiers.'),
  ('IA-4(9)', 'NIST-800-53', 'Identification and Authentication', 'Identifier Management | Attribute Maintenance and Protection', 'Maintain the attributes for each uniquely identified individual, device, or service in [Assignment: organization-defined protected central storage].'),
  ('IA-5', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management', 'Manage system authenticators by:
  a. Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, service, or device receiving the authenticator;
  b. Establishing initial authenticator content for any authenticators issued by the organization;
  c. Ensuring that authenticators have sufficient strength of mechanism for their intended use;
  d. Establishing and implementing administrative procedures for initial authenticator distribution, for lost or compromised or damaged authenticators, and for revoking authenticators;
  e. Changing default authenticators prior to first use;
  f. Changing or refreshing authenticators [Assignment: organization-defined time period by authenticator type] or when [Assignment: organization-defined events] occur;
  g. Protecting authenticator content from unauthorized disclosure and modification;
  h. Requiring individuals to take, and having devices implement, specific controls to protect authenticators; and
  i. Changing authenticators for group or role accounts when membership to those accounts changes.'),
  ('IA-5(1)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Password-based Authentication', 'For password-based authentication:
  (a) Maintain a list of commonly-used, expected, or compromised passwords and update the list [Assignment: organization-defined frequency] and when organizational passwords are suspected to have been compromised directly or indirectly;
  (b) Verify, when users create or update passwords, that the passwords are not found on the list of commonly-used, expected, or compromised passwords in IA-5(1)(a);
  (c) Transmit passwords only over cryptographically-protected channels;
  (d) Store passwords using an approved salted key derivation function, preferably using a keyed hash;
  (e) Require immediate selection of a new password upon account recovery;
  (f) Allow user selection of long passwords and passphrases, including spaces and all printable characters;
  (g) Employ automated tools to assist the user in selecting strong password authenticators; and
  (h) Enforce the following composition and complexity rules: [Assignment: organization-defined composition and complexity rules].'),
  ('IA-5(2)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Public Key-based Authentication', '(a) For public key-based authentication:
  (1) Enforce authorized access to the corresponding private key; and
  (2) Map the authenticated identity to the account of the individual or group; and
(b) When public key infrastructure (PKI) is used:
  (1) Validate certificates by constructing and verifying a certification path to an accepted trust anchor, including checking certificate status information; and
  (2) Implement a local cache of revocation data to support path discovery and validation.'),
  ('IA-5(5)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Change Authenticators Prior to Delivery', 'Require developers and installers of system components to provide unique authenticators or change default authenticators prior to delivery and installation.'),
  ('IA-5(6)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Protection of Authenticators', 'Protect authenticators commensurate with the security category of the information to which use of the authenticator permits access.'),
  ('IA-5(7)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | No Embedded Unencrypted Static Authenticators', 'Ensure that unencrypted static authenticators are not embedded in applications or other forms of static storage.'),
  ('IA-5(8)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Multiple System Accounts', 'Implement [Assignment: organization-defined security controls] to manage the risk of compromise due to individuals having accounts on multiple systems.'),
  ('IA-5(9)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Federated Credential Management', 'Use the following external organizations to federate credentials: [Assignment: organization-defined external organizations].'),
  ('IA-5(10)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Dynamic Credential Binding', 'Bind identities and authenticators dynamically using the following rules: [Assignment: organization-defined binding rules].'),
  ('IA-5(12)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Biometric Authentication Performance', 'For biometric-based authentication, employ mechanisms that satisfy the following biometric quality requirements [Assignment: organization-defined biometric quality requirements].'),
  ('IA-5(13)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Expiration of Cached Authenticators', 'Prohibit the use of cached authenticators after [Assignment: organization-defined time period].'),
  ('IA-5(14)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Managing Content of PKI Trust Stores', 'For PKI-based authentication, employ an organization-wide methodology for managing the content of PKI trust stores installed across all platforms, including networks, operating systems, browsers, and applications.'),
  ('IA-5(15)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | GSA-approved Products and Services', 'Use only General Services Administration-approved products and services for identity, credential, and access management.'),
  ('IA-5(16)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | In-person or Trusted External Party Authenticator Issuance', 'Require that the issuance of [Assignment: organization-defined types of and/or specific authenticators] be conducted [Selection: in person; by a trusted external party] before [Assignment: organization-defined registration authority] with authorization by [Assignment: organization-defined personnel or roles].'),
  ('IA-5(17)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Presentation Attack Detection for Biometric Authenticators', 'Employ presentation attack detection mechanisms for biometric-based authentication.'),
  ('IA-5(18)', 'NIST-800-53', 'Identification and Authentication', 'Authenticator Management | Password Managers', '(a) Employ [Assignment: organization-defined password managers] to generate and manage passwords; and
(b) Protect the passwords using [Assignment: organization-defined controls].'),
  ('IA-6', 'NIST-800-53', 'Identification and Authentication', 'Authentication Feedback', 'Obscure feedback of authentication information during the authentication process to protect the information from possible exploitation and use by unauthorized individuals.'),
  ('IA-7', 'NIST-800-53', 'Identification and Authentication', 'Cryptographic Module Authentication', 'Implement mechanisms for authentication to a cryptographic module that meet the requirements of applicable laws, executive orders, directives, policies, regulations, standards, and guidelines for such authentication.'),
  ('IA-8', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Non-organizational Users)', 'Uniquely identify and authenticate non-organizational users or processes acting on behalf of non-organizational users.'),
  ('IA-8(1)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Non-organizational Users) | Acceptance of PIV Credentials from Other Agencies', 'Accept and electronically verify Personal Identity Verification-compliant credentials from other federal agencies.'),
  ('IA-8(2)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Non-organizational Users) | Acceptance of External Authenticators', '(a) Accept only external authenticators that are NIST-compliant; and
(b) Document and maintain a list of accepted external authenticators.'),
  ('IA-8(4)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Non-organizational Users) | Use of Defined Profiles', 'Conform to the following profiles for identity management [Assignment: organization-defined identity management profiles].'),
  ('IA-8(5)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Non-organizational Users) | Acceptance of PIV-I Credentials', 'Accept and verify federated or PKI credentials that meet [Assignment: organization-defined policy].'),
  ('IA-8(6)', 'NIST-800-53', 'Identification and Authentication', 'Identification and Authentication (Non-organizational Users) | Disassociability', 'Implement the following measures to disassociate user attributes or identifier assertion relationships among individuals, credential service providers, and relying parties: [Assignment: organization-defined measures].'),
  ('IA-9', 'NIST-800-53', 'Identification and Authentication', 'Service Identification and Authentication', 'Uniquely identify and authenticate [Assignment: organization-defined system services and applications] before establishing communications with devices, users, or other services or applications.'),
  ('IA-10', 'NIST-800-53', 'Identification and Authentication', 'Adaptive Authentication', 'Require individuals accessing the system to employ [Assignment: organization-defined supplemental authentication techniques or mechanisms] under specific [Assignment: organization-defined circumstances or situations].'),
  ('IA-11', 'NIST-800-53', 'Identification and Authentication', 'Re-authentication', 'Require users to re-authenticate when [Assignment: organization-defined circumstances or situations].'),
  ('IA-12', 'NIST-800-53', 'Identification and Authentication', 'Identity Proofing', 'a. Identity proof users that require accounts for logical access to systems based on appropriate identity assurance level requirements as specified in applicable standards and guidelines;
b. Resolve user identities to a unique individual; and
c. Collect, validate, and verify identity evidence.'),
  ('IA-12(1)', 'NIST-800-53', 'Identification and Authentication', 'Identity Proofing | Supervisor Authorization', 'Require that the registration process to receive an account for logical access includes supervisor or sponsor authorization.'),
  ('IA-12(2)', 'NIST-800-53', 'Identification and Authentication', 'Identity Proofing | Identity Evidence', 'Require evidence of individual identification be presented to the registration authority.'),
  ('IA-12(3)', 'NIST-800-53', 'Identification and Authentication', 'Identity Proofing | Identity Evidence Validation and Verification', 'Require that the presented identity evidence be validated and verified through [Assignment: organization-defined methods of validation and verification].'),
  ('IA-12(4)', 'NIST-800-53', 'Identification and Authentication', 'Identity Proofing | In-person Validation and Verification', 'Require that the validation and verification of identity evidence be conducted in person before a designated registration authority.'),
  ('IA-12(5)', 'NIST-800-53', 'Identification and Authentication', 'Identity Proofing | Address Confirmation', 'Require that a [Selection: registration code; notice of proofing] be delivered through an out-of-band channel to verify the users address (physical or digital) of record.'),
  ('IA-12(6)', 'NIST-800-53', 'Identification and Authentication', 'Identity Proofing | Accept Externally-proofed Identities', 'Accept externally-proofed identities at [Assignment: organization-defined identity assurance level].'),
  ('IA-13', 'NIST-800-53', 'Identification and Authentication', 'Identity Providers and Authorization Servers', 'Employ identity providers and authorization servers to manage user, device, and non-person entity (NPE) identities, attributes, and access rights supporting authentication and authorization decisions in accordance with [Assignment: organization-defined policy] using [Assignment: organization-defined mechanisms].'),
  ('IA-13(1)', 'NIST-800-53', 'Identification and Authentication', 'Identity Providers and Authorization Servers | Protection of Cryptographic Keys', 'Cryptographic keys that protect access tokens are generated, managed, and protected from disclosure and misuse.'),
  ('IA-13(2)', 'NIST-800-53', 'Identification and Authentication', 'Identity Providers and Authorization Servers | Verification of Identity Assertions and Access Tokens', 'The source and integrity of identity assertions and access tokens are verified before granting access to system and information resources.'),
  ('IA-13(3)', 'NIST-800-53', 'Identification and Authentication', 'Identity Providers and Authorization Servers | Token Management', 'In accordance with [Assignment: organization-defined policy], assertions and access tokens are:
  (a) generated;
  (b) issued;
  (c) refreshed;
  (d) revoked;
  (e) time-restricted; and
  (f) audience-restricted.'),
  ('IR-1', 'NIST-800-53', 'Incident Response', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the incident response policy and the associated incident response controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the incident response policy and procedures; and
c. Review and update the current incident response:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('IR-2', 'NIST-800-53', 'Incident Response', 'Incident Response Training', 'a. Provide incident response training to system users consistent with assigned roles and responsibilities:
  1. Within [Assignment: organization-defined time period] of assuming an incident response role or responsibility or acquiring system access;
  2. When required by system changes; and
  3. [Assignment: organization-defined frequency] thereafter; and
b. Review and update incident response training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('IR-2(1)', 'NIST-800-53', 'Incident Response', 'Incident Response Training | Simulated Events', 'Incorporate simulated events into incident response training to facilitate the required response by personnel in crisis situations.'),
  ('IR-2(2)', 'NIST-800-53', 'Incident Response', 'Incident Response Training | Automated Training Environments', 'Provide an incident response training environment using [Assignment: organization-defined automated mechanisms].'),
  ('IR-2(3)', 'NIST-800-53', 'Incident Response', 'Incident Response Training | Breach', 'Provide incident response training on how to identify and respond to a breach, including the organization’s process for reporting a breach.'),
  ('IR-3', 'NIST-800-53', 'Incident Response', 'Incident Response Testing', 'Test the effectiveness of the incident response capability for the system [Assignment: organization-defined frequency] using the following tests: [Assignment: organization-defined tests].'),
  ('IR-3(1)', 'NIST-800-53', 'Incident Response', 'Incident Response Testing | Automated Testing', 'Test the incident response capability using [Assignment: organization-defined automated mechanisms].'),
  ('IR-3(2)', 'NIST-800-53', 'Incident Response', 'Incident Response Testing | Coordination with Related Plans', 'Coordinate incident response testing with organizational elements responsible for related plans.'),
  ('IR-3(3)', 'NIST-800-53', 'Incident Response', 'Incident Response Testing | Continuous Improvement', 'Use qualitative and quantitative data from testing to:
  (a) Determine the effectiveness of incident response processes;
  (b) Continuously improve incident response processes; and
  (c) Provide incident response measures and metrics that are accurate, consistent, and in a reproducible format.')
ON CONFLICT (control_id) DO UPDATE
  SET family = EXCLUDED.family, title = EXCLUDED.title, description = EXCLUDED.description
  WHERE compliance_controls.framework = 'NIST-800-53';

INSERT INTO compliance_controls (control_id, framework, family, title, description) VALUES
  ('IR-4', 'NIST-800-53', 'Incident Response', 'Incident Handling', 'a. Implement an incident handling capability for incidents that is consistent with the incident response plan and includes preparation, detection and analysis, containment, eradication, and recovery;
b. Coordinate incident handling activities with contingency planning activities;
c. Incorporate lessons learned from ongoing incident handling activities into incident response procedures, training, and testing, and implement the resulting changes accordingly; and
d. Ensure the rigor, intensity, scope, and results of incident handling activities are comparable and predictable across the organization.'),
  ('IR-4(1)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Automated Incident Handling Processes', 'Support the incident handling process using [Assignment: organization-defined automated mechanisms].'),
  ('IR-4(2)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Dynamic Reconfiguration', 'Include the following types of dynamic reconfiguration for [Assignment: organization-defined system components] as part of the incident response capability: [Assignment: organization-defined types of dynamic reconfiguration].'),
  ('IR-4(3)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Continuity of Operations', 'Identify [Assignment: organization-defined classes of incidents] and take the following actions in response to those incidents to ensure continuation of organizational mission and business functions: [Assignment: organization-defined actions].'),
  ('IR-4(4)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Information Correlation', 'Correlate incident information and individual incident responses to achieve an organization-wide perspective on incident awareness and response.'),
  ('IR-4(5)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Automatic Disabling of System', 'Implement a configurable capability to automatically disable the system if [Assignment: organization-defined security violations] are detected.'),
  ('IR-4(6)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Insider Threats', 'Implement an incident handling capability for incidents involving insider threats.'),
  ('IR-4(7)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Insider Threats — Intra-organization Coordination', 'Coordinate an incident handling capability for insider threats that includes the following organizational entities [Assignment: organization-defined entities].'),
  ('IR-4(8)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Correlation with External Organizations', 'Coordinate with [Assignment: organization-defined external organizations] to correlate and share [Assignment: organization-defined incident information] to achieve a cross-organization perspective on incident awareness and more effective incident responses.'),
  ('IR-4(9)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Dynamic Response Capability', 'Employ [Assignment: organization-defined dynamic response capabilities] to respond to incidents.'),
  ('IR-4(10)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Supply Chain Coordination', 'Coordinate incident handling activities involving supply chain events with other organizations involved in the supply chain.'),
  ('IR-4(11)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Integrated Incident Response Team', 'Establish and maintain an integrated incident response team that can be deployed to any location identified by the organization in [Assignment: organization-defined time period].'),
  ('IR-4(12)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Malicious Code and Forensic Analysis', 'Analyze malicious code and/or other residual artifacts remaining in the system after the incident.'),
  ('IR-4(13)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Behavior Analysis', 'Analyze anomalous or suspected adversarial behavior in or related to [Assignment: organization-defined environments or resources].'),
  ('IR-4(14)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Security Operations Center', 'Establish and maintain a security operations center.'),
  ('IR-4(15)', 'NIST-800-53', 'Incident Response', 'Incident Handling | Public Relations and Reputation Repair', '(a) Manage public relations associated with an incident; and
(b) Employ measures to repair the reputation of the organization.'),
  ('IR-5', 'NIST-800-53', 'Incident Response', 'Incident Monitoring', 'Track and document incidents.'),
  ('IR-5(1)', 'NIST-800-53', 'Incident Response', 'Incident Monitoring | Automated Tracking, Data Collection, and Analysis', 'Track incidents and collect and analyze incident information using [Assignment: organization-defined automated mechanisms].'),
  ('IR-6', 'NIST-800-53', 'Incident Response', 'Incident Reporting', 'a. Require personnel to report suspected incidents to the organizational incident response capability within [Assignment: organization-defined time period] ; and
b. Report incident information to [Assignment: organization-defined authorities].'),
  ('IR-6(1)', 'NIST-800-53', 'Incident Response', 'Incident Reporting | Automated Reporting', 'Report incidents using [Assignment: organization-defined automated mechanisms].'),
  ('IR-6(2)', 'NIST-800-53', 'Incident Response', 'Incident Reporting | Vulnerabilities Related to Incidents', 'Report system vulnerabilities associated with reported incidents to [Assignment: organization-defined personnel or roles].'),
  ('IR-6(3)', 'NIST-800-53', 'Incident Response', 'Incident Reporting | Supply Chain Coordination', 'Provide incident information to the provider of the product or service and other organizations involved in the supply chain or supply chain governance for systems or system components related to the incident.'),
  ('IR-7', 'NIST-800-53', 'Incident Response', 'Incident Response Assistance', 'Provide an incident response support resource, integral to the organizational incident response capability, that offers advice and assistance to users of the system for the handling and reporting of incidents.'),
  ('IR-7(1)', 'NIST-800-53', 'Incident Response', 'Incident Response Assistance | Automation Support for Availability of Information and Support', 'Increase the availability of incident response information and support using [Assignment: organization-defined automated mechanisms].'),
  ('IR-7(2)', 'NIST-800-53', 'Incident Response', 'Incident Response Assistance | Coordination with External Providers', '(a) Establish a direct, cooperative relationship between its incident response capability and external providers of system protection capability; and
(b) Identify organizational incident response team members to the external providers.'),
  ('IR-8', 'NIST-800-53', 'Incident Response', 'Incident Response Plan', 'a. Develop an incident response plan that:
  1. Provides the organization with a roadmap for implementing its incident response capability;
  2. Describes the structure and organization of the incident response capability;
  3. Provides a high-level approach for how the incident response capability fits into the overall organization;
  4. Meets the unique requirements of the organization, which relate to mission, size, structure, and functions;
  5. Defines reportable incidents;
  6. Provides metrics for measuring the incident response capability within the organization;
  7. Defines the resources and management support needed to effectively maintain and mature an incident response capability;
  8. Addresses the sharing of incident information;
  9. Is reviewed and approved by [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency] ; and
  10. Explicitly designates responsibility for incident response to [Assignment: organization-defined entities, personnel, or roles].
b. Distribute copies of the incident response plan to [Assignment: organization-defined incident response personnel];
c. Update the incident response plan to address system and organizational changes or problems encountered during plan implementation, execution, or testing;
d. Communicate incident response plan changes to [Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements] ; and
e. Protect the incident response plan from unauthorized disclosure and modification.'),
  ('IR-8(1)', 'NIST-800-53', 'Incident Response', 'Incident Response Plan | Breaches', 'Include the following in the Incident Response Plan for breaches involving personally identifiable information:
  (a) A process to determine if notice to individuals or other organizations, including oversight organizations, is needed;
  (b) An assessment process to determine the extent of the harm, embarrassment, inconvenience, or unfairness to affected individuals and any mechanisms to mitigate such harms; and
  (c) Identification of applicable privacy requirements.'),
  ('IR-9', 'NIST-800-53', 'Incident Response', 'Information Spillage Response', 'Respond to information spills by:
  a. Assigning [Assignment: organization-defined personnel or roles] with responsibility for responding to information spills;
  b. Identifying the specific information involved in the system contamination;
  c. Alerting [Assignment: organization-defined personnel or roles] of the information spill using a method of communication not associated with the spill;
  d. Isolating the contaminated system or system component;
  e. Eradicating the information from the contaminated system or component;
  f. Identifying other systems or system components that may have been subsequently contaminated; and
  g. Performing the following additional actions: [Assignment: organization-defined actions].'),
  ('IR-9(2)', 'NIST-800-53', 'Incident Response', 'Information Spillage Response | Training', 'Provide information spillage response training [Assignment: organization-defined frequency].'),
  ('IR-9(3)', 'NIST-800-53', 'Incident Response', 'Information Spillage Response | Post-spill Operations', 'Implement the following procedures to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions: [Assignment: organization-defined procedures].'),
  ('IR-9(4)', 'NIST-800-53', 'Incident Response', 'Information Spillage Response | Exposure to Unauthorized Personnel', 'Employ the following controls for personnel exposed to information not within assigned access authorizations: [Assignment: organization-defined controls].'),
  ('MA-1', 'NIST-800-53', 'Maintenance', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the maintenance policy and the associated maintenance controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the maintenance policy and procedures; and
c. Review and update the current maintenance:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('MA-2', 'NIST-800-53', 'Maintenance', 'Controlled Maintenance', 'a. Schedule, document, and review records of maintenance, repair, and replacement on system components in accordance with manufacturer or vendor specifications and/or organizational requirements;
b. Approve and monitor all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location;
c. Require that [Assignment: organization-defined personnel or roles] explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement;
d. Sanitize equipment to remove the following information from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement: [Assignment: organization-defined information];
e. Check all potentially impacted controls to verify that the controls are still functioning properly following maintenance, repair, or replacement actions; and
f. Include the following information in organizational maintenance records: [Assignment: organization-defined information].'),
  ('MA-2(2)', 'NIST-800-53', 'Maintenance', 'Controlled Maintenance | Automated Maintenance Activities', '(a) Schedule, conduct, and document maintenance, repair, and replacement actions for the system using [Assignment: organization-defined automated mechanisms] ; and
(b) Produce up-to date, accurate, and complete records of all maintenance, repair, and replacement actions requested, scheduled, in process, and completed.'),
  ('MA-3', 'NIST-800-53', 'Maintenance', 'Maintenance Tools', 'a. Approve, control, and monitor the use of system maintenance tools; and
b. Review previously approved system maintenance tools [Assignment: organization-defined frequency].'),
  ('MA-3(1)', 'NIST-800-53', 'Maintenance', 'Maintenance Tools | Inspect Tools', 'Inspect the maintenance tools used by maintenance personnel for improper or unauthorized modifications.'),
  ('MA-3(2)', 'NIST-800-53', 'Maintenance', 'Maintenance Tools | Inspect Media', 'Check media containing diagnostic and test programs for malicious code before the media are used in the system.'),
  ('MA-3(3)', 'NIST-800-53', 'Maintenance', 'Maintenance Tools | Prevent Unauthorized Removal', 'Prevent the removal of maintenance equipment containing organizational information by:
  (a) Verifying that there is no organizational information contained on the equipment;
  (b) Sanitizing or destroying the equipment;
  (c) Retaining the equipment within the facility; or
  (d) Obtaining an exemption from [Assignment: organization-defined personnel or roles] explicitly authorizing removal of the equipment from the facility.'),
  ('MA-3(4)', 'NIST-800-53', 'Maintenance', 'Maintenance Tools | Restricted Tool Use', 'Restrict the use of maintenance tools to authorized personnel only.'),
  ('MA-3(5)', 'NIST-800-53', 'Maintenance', 'Maintenance Tools | Execution with Privilege', 'Monitor the use of maintenance tools that execute with increased privilege.'),
  ('MA-3(6)', 'NIST-800-53', 'Maintenance', 'Maintenance Tools | Software Updates and Patches', 'Inspect maintenance tools to ensure the latest software updates and patches are installed.'),
  ('MA-4', 'NIST-800-53', 'Maintenance', 'Nonlocal Maintenance', 'a. Approve and monitor nonlocal maintenance and diagnostic activities;
b. Allow the use of nonlocal maintenance and diagnostic tools only as consistent with organizational policy and documented in the security plan for the system;
c. Employ strong authentication in the establishment of nonlocal maintenance and diagnostic sessions;
d. Maintain records for nonlocal maintenance and diagnostic activities; and
e. Terminate session and network connections when nonlocal maintenance is completed.'),
  ('MA-4(1)', 'NIST-800-53', 'Maintenance', 'Nonlocal Maintenance | Logging and Review', '(a) Log [Assignment: organization-defined audit events] for nonlocal maintenance and diagnostic sessions; and
(b) Review the audit records of the maintenance and diagnostic sessions to detect anomalous behavior.'),
  ('MA-4(3)', 'NIST-800-53', 'Maintenance', 'Nonlocal Maintenance | Comparable Security and Sanitization', '(a) Require that nonlocal maintenance and diagnostic services be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or
(b) Remove the component to be serviced from the system prior to nonlocal maintenance or diagnostic services; sanitize the component (for organizational information); and after the service is performed, inspect and sanitize the component (for potentially malicious software) before reconnecting the component to the system.'),
  ('MA-4(4)', 'NIST-800-53', 'Maintenance', 'Nonlocal Maintenance | Authentication and Separation of Maintenance Sessions', 'Protect nonlocal maintenance sessions by:
  (a) Employing [Assignment: organization-defined authenticators that are replay resistant] ; and
  (b) Separating the maintenance sessions from other network sessions with the system by either:
    (1) Physically separated communications paths; or
    (2) Logically separated communications paths.'),
  ('MA-4(5)', 'NIST-800-53', 'Maintenance', 'Nonlocal Maintenance | Approvals and Notifications', '(a) Require the approval of each nonlocal maintenance session by [Assignment: organization-defined personnel or roles] ; and
(b) Notify the following personnel or roles of the date and time of planned nonlocal maintenance: [Assignment: organization-defined personnel and roles].'),
  ('MA-4(6)', 'NIST-800-53', 'Maintenance', 'Nonlocal Maintenance | Cryptographic Protection', 'Implement the following cryptographic mechanisms to protect the integrity and confidentiality of nonlocal maintenance and diagnostic communications: [Assignment: organization-defined cryptographic mechanisms].'),
  ('MA-4(7)', 'NIST-800-53', 'Maintenance', 'Nonlocal Maintenance | Disconnect Verification', 'Verify session and network connection termination after the completion of nonlocal maintenance and diagnostic sessions.'),
  ('MA-5', 'NIST-800-53', 'Maintenance', 'Maintenance Personnel', 'a. Establish a process for maintenance personnel authorization and maintain a list of authorized maintenance organizations or personnel;
b. Verify that non-escorted personnel performing maintenance on the system possess the required access authorizations; and
c. Designate organizational personnel with required access authorizations and technical competence to supervise the maintenance activities of personnel who do not possess the required access authorizations.'),
  ('MA-5(1)', 'NIST-800-53', 'Maintenance', 'Maintenance Personnel | Individuals Without Appropriate Access', '(a) Implement procedures for the use of maintenance personnel that lack appropriate security clearances or are not U.S. citizens, that include the following requirements:
  (1) Maintenance personnel who do not have needed access authorizations, clearances, or formal access approvals are escorted and supervised during the performance of maintenance and diagnostic activities on the system by approved organizational personnel who are fully cleared, have appropriate access authorizations, and are technically qualified; and
  (2) Prior to initiating maintenance or diagnostic activities by personnel who do not have needed access authorizations, clearances or formal access approvals, all volatile information storage components within the system are sanitized and all nonvolatile storage media are removed or physically disconnected from the system and secured; and
(b) Develop and implement [Assignment: organization-defined alternate controls] in the event a system component cannot be sanitized, removed, or disconnected from the system.'),
  ('MA-5(2)', 'NIST-800-53', 'Maintenance', 'Maintenance Personnel | Security Clearances for Classified Systems', 'Verify that personnel performing maintenance and diagnostic activities on a system processing, storing, or transmitting classified information possess security clearances and formal access approvals for at least the highest classification level and for compartments of information on the system.'),
  ('MA-5(3)', 'NIST-800-53', 'Maintenance', 'Maintenance Personnel | Citizenship Requirements for Classified Systems', 'Verify that personnel performing maintenance and diagnostic activities on a system processing, storing, or transmitting classified information are U.S. citizens.'),
  ('MA-5(4)', 'NIST-800-53', 'Maintenance', 'Maintenance Personnel | Foreign Nationals', 'Ensure that:
  (a) Foreign nationals with appropriate security clearances are used to conduct maintenance and diagnostic activities on classified systems only when the systems are jointly owned and operated by the United States and foreign allied governments, or owned and operated solely by foreign allied governments; and
  (b) Approvals, consents, and detailed operational conditions regarding the use of foreign nationals to conduct maintenance and diagnostic activities on classified systems are fully documented within Memoranda of Agreements.'),
  ('MA-5(5)', 'NIST-800-53', 'Maintenance', 'Maintenance Personnel | Non-system Maintenance', 'Ensure that non-escorted personnel performing maintenance activities not directly associated with the system but in the physical proximity of the system, have required access authorizations.'),
  ('MA-6', 'NIST-800-53', 'Maintenance', 'Timely Maintenance', 'Obtain maintenance support and/or spare parts for [Assignment: organization-defined system components] within [Assignment: organization-defined time period] of failure.'),
  ('MA-6(1)', 'NIST-800-53', 'Maintenance', 'Timely Maintenance | Preventive Maintenance', 'Perform preventive maintenance on [Assignment: organization-defined system components] at [Assignment: organization-defined time intervals].'),
  ('MA-6(2)', 'NIST-800-53', 'Maintenance', 'Timely Maintenance | Predictive Maintenance', 'Perform predictive maintenance on [Assignment: organization-defined system components] at [Assignment: organization-defined time intervals].'),
  ('MA-6(3)', 'NIST-800-53', 'Maintenance', 'Timely Maintenance | Automated Support for Predictive Maintenance', 'Transfer predictive maintenance data to a maintenance management system using [Assignment: organization-defined automated mechanisms].'),
  ('MA-7', 'NIST-800-53', 'Maintenance', 'Field Maintenance', 'Restrict or prohibit field maintenance on [Assignment: organization-defined systems or system components] to [Assignment: organization-defined trusted maintenance facilities].'),
  ('MP-1', 'NIST-800-53', 'Media Protection', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] media protection policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the media protection policy and the associated media protection controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the media protection policy and procedures; and
c. Review and update the current media protection:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('MP-2', 'NIST-800-53', 'Media Protection', 'Media Access', 'Restrict access to [Assignment: organization-defined types of digital and/or non-digital media] to [Assignment: organization-defined personnel or roles].'),
  ('MP-3', 'NIST-800-53', 'Media Protection', 'Media Marking', 'a. Mark system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; and
b. Exempt [Assignment: organization-defined types of media exempted from marking] from marking if the media remain within [Assignment: organization-defined controlled areas].'),
  ('MP-4', 'NIST-800-53', 'Media Protection', 'Media Storage', 'a. Physically control and securely store [Assignment: organization-defined types of digital and/or non-digital media] within [Assignment: organization-defined controlled areas] ; and
b. Protect system media types defined in MP-4a until the media are destroyed or sanitized using approved equipment, techniques, and procedures.'),
  ('MP-4(2)', 'NIST-800-53', 'Media Protection', 'Media Storage | Automated Restricted Access', 'Restrict access to media storage areas and log access attempts and access granted using [Assignment: organization-defined automated mechanisms].'),
  ('MP-5', 'NIST-800-53', 'Media Protection', 'Media Transport', 'a. Protect and control [Assignment: organization-defined types of system media] during transport outside of controlled areas using [Assignment: organization-defined controls];
b. Maintain accountability for system media during transport outside of controlled areas;
c. Document activities associated with the transport of system media; and
d. Restrict the activities associated with the transport of system media to authorized personnel.'),
  ('MP-5(3)', 'NIST-800-53', 'Media Protection', 'Media Transport | Custodians', 'Employ an identified custodian during transport of system media outside of controlled areas.'),
  ('MP-6', 'NIST-800-53', 'Media Protection', 'Media Sanitization', 'a. Sanitize [Assignment: organization-defined system media] prior to disposal, release out of organizational control, or release for reuse using [Assignment: organization-defined sanitization techniques and procedures] ; and
b. Employ sanitization mechanisms with the strength and integrity commensurate with the security category or classification of the information.'),
  ('MP-6(1)', 'NIST-800-53', 'Media Protection', 'Media Sanitization | Review, Approve, Track, Document, and Verify', 'Review, approve, track, document, and verify media sanitization and disposal actions.'),
  ('MP-6(2)', 'NIST-800-53', 'Media Protection', 'Media Sanitization | Equipment Testing', 'Test sanitization equipment and procedures [Assignment: organization-defined frequency] to ensure that the intended sanitization is being achieved.'),
  ('MP-6(3)', 'NIST-800-53', 'Media Protection', 'Media Sanitization | Nondestructive Techniques', 'Apply nondestructive sanitization techniques to portable storage devices prior to connecting such devices to the system under the following circumstances: [Assignment: organization-defined circumstances].'),
  ('MP-6(7)', 'NIST-800-53', 'Media Protection', 'Media Sanitization | Dual Authorization', 'Enforce dual authorization for the sanitization of [Assignment: organization-defined system media].'),
  ('MP-6(8)', 'NIST-800-53', 'Media Protection', 'Media Sanitization | Remote Purging or Wiping of Information', 'Provide the capability to purge or wipe information from [Assignment: organization-defined systems or system components] [Selection: remotely; under [Assignment: organization-defined conditions] ].'),
  ('MP-7', 'NIST-800-53', 'Media Protection', 'Media Use', 'a. [Selection: restrict; prohibit] the use of [Assignment: organization-defined types of system media] on [Assignment: organization-defined systems or system components] using [Assignment: organization-defined controls] ; and
b. Prohibit the use of portable storage devices in organizational systems when such devices have no identifiable owner.'),
  ('MP-7(2)', 'NIST-800-53', 'Media Protection', 'Media Use | Prohibit Use of Sanitization-resistant Media', 'Prohibit the use of sanitization-resistant media in organizational systems.'),
  ('MP-8', 'NIST-800-53', 'Media Protection', 'Media Downgrading', 'a. Establish [Assignment: organization-defined system media downgrading process] that includes employing downgrading mechanisms with strength and integrity commensurate with the security category or classification of the information;
b. Verify that the system media downgrading process is commensurate with the security category and/or classification level of the information to be removed and the access authorizations of the potential recipients of the downgraded information;
c. Identify [Assignment: organization-defined system media requiring downgrading] ; and
d. Downgrade the identified system media using the established process.'),
  ('MP-8(1)', 'NIST-800-53', 'Media Protection', 'Media Downgrading | Documentation of Process', 'Document system media downgrading actions.'),
  ('MP-8(2)', 'NIST-800-53', 'Media Protection', 'Media Downgrading | Equipment Testing', 'Test downgrading equipment and procedures [Assignment: organization-defined frequency] to ensure that downgrading actions are being achieved.'),
  ('MP-8(3)', 'NIST-800-53', 'Media Protection', 'Media Downgrading | Controlled Unclassified Information', 'Downgrade system media containing controlled unclassified information prior to public release.'),
  ('MP-8(4)', 'NIST-800-53', 'Media Protection', 'Media Downgrading | Classified Information', 'Downgrade system media containing classified information prior to release to individuals without required access authorizations.'),
  ('PE-1', 'NIST-800-53', 'Physical and Environmental Protection', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the physical and environmental protection policy and the associated physical and environmental protection controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the physical and environmental protection policy and procedures; and
c. Review and update the current physical and environmental protection:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('PE-2', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Authorizations', 'a. Develop, approve, and maintain a list of individuals with authorized access to the facility where the system resides;
b. Issue authorization credentials for facility access;
c. Review the access list detailing authorized facility access by individuals [Assignment: organization-defined frequency] ; and
d. Remove individuals from the facility access list when access is no longer required.'),
  ('PE-2(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Authorizations | Access by Position or Role', 'Authorize physical access to the facility where the system resides based on position or role.'),
  ('PE-2(2)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Authorizations | Two Forms of Identification', 'Require two forms of identification from the following forms of identification for visitor access to the facility where the system resides: [Assignment: organization-defined list of acceptable forms of identification].'),
  ('PE-2(3)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Authorizations | Restrict Unescorted Access', 'Restrict unescorted access to the facility where the system resides to personnel with [Selection (one or more): security clearances for all information contained within the system; formal access authorizations for all information contained within the system; need for access to all information contained within the system; [Assignment: organization-defined physical access authorizations] ].'),
  ('PE-3', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Control', 'a. Enforce physical access authorizations at [Assignment: organization-defined entry and exit points] by:
  1. Verifying individual access authorizations before granting access to the facility; and
  2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment: organization-defined systems or devices] ; guards];
b. Maintain physical access audit logs for [Assignment: organization-defined entry or exit points];
c. Control access to areas within the facility designated as publicly accessible by implementing the following controls: [Assignment: organization-defined physical access controls];
d. Escort visitors and control visitor activity [Assignment: organization-defined circumstances];
e. Secure keys, combinations, and other physical access devices;
f. Inventory [Assignment: organization-defined physical access devices] every [Assignment: organization-defined frequency] ; and
g. Change combinations and keys [Assignment: organization-defined frequency] and/or when keys are lost, combinations are compromised, or when individuals possessing the keys or combinations are transferred or terminated.'),
  ('PE-3(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Control | System Access', 'Enforce physical access authorizations to the system in addition to the physical access controls for the facility at [Assignment: organization-defined physical spaces].'),
  ('PE-3(2)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Control | Facility and Systems', 'Perform security checks [Assignment: organization-defined frequency] at the physical perimeter of the facility or system for exfiltration of information or removal of system components.'),
  ('PE-3(3)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Control | Continuous Guards', 'Employ guards to control [Assignment: organization-defined physical access points] to the facility where the system resides 24 hours per day, 7 days per week.'),
  ('PE-3(4)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Control | Lockable Casings', 'Use lockable physical casings to protect [Assignment: organization-defined system components] from unauthorized physical access.'),
  ('PE-3(5)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Control | Tamper Protection', 'Employ [Assignment: organization-defined anti-tamper technologies] to [Selection (one or more): detect; prevent] physical tampering or alteration of [Assignment: organization-defined hardware components] within the system.'),
  ('PE-3(7)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Control | Physical Barriers', 'Limit access using physical barriers.'),
  ('PE-3(8)', 'NIST-800-53', 'Physical and Environmental Protection', 'Physical Access Control | Access Control Vestibules', 'Employ access control vestibules at [Assignment: organization-defined locations].'),
  ('PE-4', 'NIST-800-53', 'Physical and Environmental Protection', 'Access Control for Transmission', 'Control physical access to [Assignment: organization-defined system distribution and transmission lines] within organizational facilities using [Assignment: organization-defined security controls].'),
  ('PE-5', 'NIST-800-53', 'Physical and Environmental Protection', 'Access Control for Output Devices', 'Control physical access to output from [Assignment: organization-defined output devices] to prevent unauthorized individuals from obtaining the output.'),
  ('PE-5(2)', 'NIST-800-53', 'Physical and Environmental Protection', 'Access Control for Output Devices | Link to Individual Identity', 'Link individual identity to receipt of output from output devices.'),
  ('PE-6', 'NIST-800-53', 'Physical and Environmental Protection', 'Monitoring Physical Access', 'a. Monitor physical access to the facility where the system resides to detect and respond to physical security incidents;
b. Review physical access logs [Assignment: organization-defined frequency] and upon occurrence of [Assignment: organization-defined events] ; and
c. Coordinate results of reviews and investigations with the organizational incident response capability.'),
  ('PE-6(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Monitoring Physical Access | Intrusion Alarms and Surveillance Equipment', 'Monitor physical access to the facility where the system resides using physical intrusion alarms and surveillance equipment.'),
  ('PE-6(2)', 'NIST-800-53', 'Physical and Environmental Protection', 'Monitoring Physical Access | Automated Intrusion Recognition and Responses', 'Recognize [Assignment: organization-defined classes or types of intrusions] and initiate [Assignment: organization-defined response actions] using [Assignment: organization-defined automated mechanisms].'),
  ('PE-6(3)', 'NIST-800-53', 'Physical and Environmental Protection', 'Monitoring Physical Access | Video Surveillance', '(a) Employ video surveillance of [Assignment: organization-defined operational areas];
(b) Review video recordings [Assignment: organization-defined frequency] ; and
(c) Retain video recordings for [Assignment: organization-defined time period].'),
  ('PE-6(4)', 'NIST-800-53', 'Physical and Environmental Protection', 'Monitoring Physical Access | Monitoring Physical Access to Systems', 'Monitor physical access to the system in addition to the physical access monitoring of the facility at [Assignment: organization-defined physical spaces].'),
  ('PE-8', 'NIST-800-53', 'Physical and Environmental Protection', 'Visitor Access Records', 'a. Maintain visitor access records to the facility where the system resides for [Assignment: organization-defined time period];
b. Review visitor access records [Assignment: organization-defined frequency] ; and
c. Report anomalies in visitor access records to [Assignment: organization-defined personnel].'),
  ('PE-8(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Visitor Access Records | Automated Records Maintenance and Review', 'Maintain and review visitor access records using [Assignment: organization-defined automated mechanisms].'),
  ('PE-8(3)', 'NIST-800-53', 'Physical and Environmental Protection', 'Visitor Access Records | Limit Personally Identifiable Information Elements', 'Limit personally identifiable information contained in visitor access records to the following elements identified in the privacy risk assessment: [Assignment: organization-defined elements].'),
  ('PE-9', 'NIST-800-53', 'Physical and Environmental Protection', 'Power Equipment and Cabling', 'Protect power equipment and power cabling for the system from damage and destruction.'),
  ('PE-9(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Power Equipment and Cabling | Redundant Cabling', 'Employ redundant power cabling paths that are physically separated by [Assignment: organization-defined distance].'),
  ('PE-9(2)', 'NIST-800-53', 'Physical and Environmental Protection', 'Power Equipment and Cabling | Automatic Voltage Controls', 'Employ automatic voltage controls for [Assignment: organization-defined critical system components].'),
  ('PE-10', 'NIST-800-53', 'Physical and Environmental Protection', 'Emergency Shutoff', 'a. Provide the capability of shutting off power to [Assignment: organization-defined system or individual system components] in emergency situations;
b. Place emergency shutoff switches or devices in [Assignment: organization-defined location] to facilitate access for authorized personnel; and
c. Protect emergency power shutoff capability from unauthorized activation.'),
  ('PE-11', 'NIST-800-53', 'Physical and Environmental Protection', 'Emergency Power', 'Provide an uninterruptible power supply to facilitate [Selection: an orderly shutdown of the system; transition of the system to long-term alternate power] in the event of a primary power source loss.'),
  ('PE-11(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Emergency Power | Alternate Power Supply — Minimal Operational Capability', 'Provide an alternate power supply for the system that is activated [Selection: manually; automatically] and that can maintain minimally required operational capability in the event of an extended loss of the primary power source.'),
  ('PE-11(2)', 'NIST-800-53', 'Physical and Environmental Protection', 'Emergency Power | Alternate Power Supply — Self-contained', 'Provide an alternate power supply for the system that is activated [Selection: manually; automatically] and that is:
  (a) Self-contained;
  (b) Not reliant on external power generation; and
  (c) Capable of maintaining [Selection: minimally required operational capability; full operational capability] in the event of an extended loss of the primary power source.'),
  ('PE-12', 'NIST-800-53', 'Physical and Environmental Protection', 'Emergency Lighting', 'Employ and maintain automatic emergency lighting for the system that activates in the event of a power outage or disruption and that covers emergency exits and evacuation routes within the facility.'),
  ('PE-12(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Emergency Lighting | Essential Mission and Business Functions', 'Provide emergency lighting for all areas within the facility supporting essential mission and business functions.'),
  ('PE-13', 'NIST-800-53', 'Physical and Environmental Protection', 'Fire Protection', 'Employ and maintain fire detection and suppression systems that are supported by an independent energy source.'),
  ('PE-13(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Fire Protection | Detection Systems — Automatic Activation and Notification', 'Employ fire detection systems that activate automatically and notify [Assignment: organization-defined personnel or roles] and [Assignment: organization-defined emergency responders] in the event of a fire.'),
  ('PE-13(2)', 'NIST-800-53', 'Physical and Environmental Protection', 'Fire Protection | Suppression Systems — Automatic Activation and Notification', '(a) Employ fire suppression systems that activate automatically and notify [Assignment: organization-defined personnel or roles] and [Assignment: organization-defined emergency responders] ; and
(b) Employ an automatic fire suppression capability when the facility is not staffed on a continuous basis.'),
  ('PE-13(4)', 'NIST-800-53', 'Physical and Environmental Protection', 'Fire Protection | Inspections', 'Ensure that the facility undergoes [Assignment: organization-defined frequency] fire protection inspections by authorized and qualified inspectors and identified deficiencies are resolved within [Assignment: organization-defined time period].'),
  ('PE-14', 'NIST-800-53', 'Physical and Environmental Protection', 'Environmental Controls', 'a. Maintain [Selection (one or more): temperature; humidity; pressure; radiation; [Assignment: organization-defined environmental control] ] levels within the facility where the system resides at [Assignment: organization-defined acceptable levels] ; and
b. Monitor environmental control levels [Assignment: organization-defined frequency].'),
  ('PE-14(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Environmental Controls | Automatic Controls', 'Employ the following automatic environmental controls in the facility to prevent fluctuations potentially harmful to the system: [Assignment: organization-defined automatic environmental controls].'),
  ('PE-14(2)', 'NIST-800-53', 'Physical and Environmental Protection', 'Environmental Controls | Monitoring with Alarms and Notifications', 'Employ environmental control monitoring that provides an alarm or notification of changes potentially harmful to personnel or equipment to [Assignment: organization-defined personnel or roles].'),
  ('PE-15', 'NIST-800-53', 'Physical and Environmental Protection', 'Water Damage Protection', 'Protect the system from damage resulting from water leakage by providing master shutoff or isolation valves that are accessible, working properly, and known to key personnel.'),
  ('PE-15(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Water Damage Protection | Automation Support', 'Detect the presence of water near the system and alert [Assignment: organization-defined personnel or roles] using [Assignment: organization-defined automated mechanisms].'),
  ('PE-16', 'NIST-800-53', 'Physical and Environmental Protection', 'Delivery and Removal', 'a. Authorize and control [Assignment: organization-defined types of system components] entering and exiting the facility; and
b. Maintain records of the system components.'),
  ('PE-17', 'NIST-800-53', 'Physical and Environmental Protection', 'Alternate Work Site', 'a. Determine and document the [Assignment: organization-defined alternate work sites] allowed for use by employees;
b. Employ the following controls at alternate work sites: [Assignment: organization-defined controls];
c. Assess the effectiveness of controls at alternate work sites; and
d. Provide a means for employees to communicate with information security and privacy personnel in case of incidents.'),
  ('PE-18', 'NIST-800-53', 'Physical and Environmental Protection', 'Location of System Components', 'Position system components within the facility to minimize potential damage from [Assignment: organization-defined physical and environmental hazards] and to minimize the opportunity for unauthorized access.'),
  ('PE-19', 'NIST-800-53', 'Physical and Environmental Protection', 'Information Leakage', 'Protect the system from information leakage due to electromagnetic signals emanations.'),
  ('PE-19(1)', 'NIST-800-53', 'Physical and Environmental Protection', 'Information Leakage | National Emissions Policies and Procedures', 'Protect system components, associated data communications, and networks in accordance with national Emissions Security policies and procedures based on the security category or classification of the information.'),
  ('PE-20', 'NIST-800-53', 'Physical and Environmental Protection', 'Asset Monitoring and Tracking', 'Employ [Assignment: organization-defined asset location technologies] to track and monitor the location and movement of [Assignment: organization-defined assets] within [Assignment: organization-defined controlled areas].'),
  ('PE-21', 'NIST-800-53', 'Physical and Environmental Protection', 'Electromagnetic Pulse Protection', 'Employ [Assignment: organization-defined protective measures] against electromagnetic pulse damage for [Assignment: organization-defined system and system components].'),
  ('PE-22', 'NIST-800-53', 'Physical and Environmental Protection', 'Component Marking', 'Mark [Assignment: organization-defined system hardware components] indicating the impact level or classification level of the information permitted to be processed, stored, or transmitted by the hardware component.'),
  ('PE-23', 'NIST-800-53', 'Physical and Environmental Protection', 'Facility Location', 'a. Plan the location or site of the facility where the system resides considering physical and environmental hazards; and
b. For existing facilities, consider the physical and environmental hazards in the organizational risk management strategy.'),
  ('PL-1', 'NIST-800-53', 'Planning', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] planning policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the planning policy and the associated planning controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the planning policy and procedures; and
c. Review and update the current planning:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('PL-2', 'NIST-800-53', 'Planning', 'System Security and Privacy Plans', 'a. Develop security and privacy plans for the system that:
  1. Are consistent with the organization’s enterprise architecture;
  2. Explicitly define the constituent system components;
  3. Describe the operational context of the system in terms of mission and business processes;
  4. Identify the individuals that fulfill system roles and responsibilities;
  5. Identify the information types processed, stored, and transmitted by the system;
  6. Provide the security categorization of the system, including supporting rationale;
  7. Describe any specific threats to the system that are of concern to the organization;
  8. Provide the results of a privacy risk assessment for systems processing personally identifiable information;
  9. Describe the operational environment for the system and any dependencies on or connections to other systems or system components;
  10. Provide an overview of the security and privacy requirements for the system;
  11. Identify any relevant control baselines or overlays, if applicable;
  12. Describe the controls in place or planned for meeting the security and privacy requirements, including a rationale for any tailoring decisions;
  13. Include risk determinations for security and privacy architecture and design decisions;
  14. Include security- and privacy-related activities affecting the system that require planning and coordination with [Assignment: organization-defined individuals or groups] ; and
  15. Are reviewed and approved by the authorizing official or designated representative prior to plan implementation.
b. Distribute copies of the plans and communicate subsequent changes to the plans to [Assignment: organization-defined personnel or roles];
c. Review the plans [Assignment: organization-defined frequency];
d. Update the plans to address changes to the system and environment of operation or problems identified during plan implementation or control assessments; and
e. Protect the plans from unauthorized disclosure and modification.'),
  ('PL-4', 'NIST-800-53', 'Planning', 'Rules of Behavior', 'a. Establish and provide to individuals requiring access to the system, the rules that describe their responsibilities and expected behavior for information and system usage, security, and privacy;
b. Receive a documented acknowledgment from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the system;
c. Review and update the rules of behavior [Assignment: organization-defined frequency] ; and
d. Require individuals who have acknowledged a previous version of the rules of behavior to read and re-acknowledge [Selection (one or more): [Assignment: organization-defined frequency] ; when the rules are revised or updated].'),
  ('PL-4(1)', 'NIST-800-53', 'Planning', 'Rules of Behavior | Social Media and External Site/Application Usage Restrictions', 'Include in the rules of behavior, restrictions on:
  (a) Use of social media, social networking sites, and external sites/applications;
  (b) Posting organizational information on public websites; and
  (c) Use of organization-provided identifiers (e.g., email addresses) and authentication secrets (e.g., passwords) for creating accounts on external sites/applications.'),
  ('PL-7', 'NIST-800-53', 'Planning', 'Concept of Operations', 'a. Develop a Concept of Operations (CONOPS) for the system describing how the organization intends to operate the system from the perspective of information security and privacy; and
b. Review and update the CONOPS [Assignment: organization-defined frequency].'),
  ('PL-8', 'NIST-800-53', 'Planning', 'Security and Privacy Architectures', 'a. Develop security and privacy architectures for the system that:
  1. Describe the requirements and approach to be taken for protecting the confidentiality, integrity, and availability of organizational information;
  2. Describe the requirements and approach to be taken for processing personally identifiable information to minimize privacy risk to individuals;
  3. Describe how the architectures are integrated into and support the enterprise architecture; and
  4. Describe any assumptions about, and dependencies on, external systems and services;
b. Review and update the architectures [Assignment: organization-defined frequency] to reflect changes in the enterprise architecture; and
c. Reflect planned architecture changes in security and privacy plans, Concept of Operations (CONOPS), criticality analysis, organizational procedures, and procurements and acquisitions.'),
  ('PL-8(1)', 'NIST-800-53', 'Planning', 'Security and Privacy Architectures | Defense in Depth', 'Design the security and privacy architectures for the system using a defense-in-depth approach that:
  (a) Allocates [Assignment: organization-defined controls] to [Assignment: organization-defined locations and architectural layers] ; and
  (b) Ensures that the allocated controls operate in a coordinated and mutually reinforcing manner.'),
  ('PL-8(2)', 'NIST-800-53', 'Planning', 'Security and Privacy Architectures | Supplier Diversity', 'Require that [Assignment: organization-defined controls] allocated to [Assignment: organization-defined locations and architectural layers] are obtained from different suppliers.'),
  ('PL-9', 'NIST-800-53', 'Planning', 'Central Management', 'Centrally manage [Assignment: organization-defined controls and related processes].'),
  ('PL-10', 'NIST-800-53', 'Planning', 'Baseline Selection', 'Select a control baseline for the system.'),
  ('PL-11', 'NIST-800-53', 'Planning', 'Baseline Tailoring', 'Tailor the selected control baseline by applying specified tailoring actions.'),
  ('PM-1', 'NIST-800-53', 'Program Management', 'Information Security Program Plan', 'a. Develop and disseminate an organization-wide information security program plan that:
  1. Provides an overview of the requirements for the security program and a description of the security program management controls and common controls in place or planned for meeting those requirements;
  2. Includes the identification and assignment of roles, responsibilities, management commitment, coordination among organizational entities, and compliance;
  3. Reflects the coordination among organizational entities responsible for information security; and
  4. Is approved by a senior official with responsibility and accountability for the risk being incurred to organizational operations (including mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation;
b. Review and update the organization-wide information security program plan [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
c. Protect the information security program plan from unauthorized disclosure and modification.'),
  ('PM-2', 'NIST-800-53', 'Program Management', 'Information Security Program Leadership Role', 'Appoint a senior agency information security officer with the mission and resources to coordinate, develop, implement, and maintain an organization-wide information security program.'),
  ('PM-3', 'NIST-800-53', 'Program Management', 'Information Security and Privacy Resources', 'a. Include the resources needed to implement the information security and privacy programs in capital planning and investment requests and document all exceptions to this requirement;
b. Prepare documentation required for addressing information security and privacy programs in capital planning and investment requests in accordance with applicable laws, executive orders, directives, policies, regulations, standards; and
c. Make available for expenditure, the planned information security and privacy resources.'),
  ('PM-4', 'NIST-800-53', 'Program Management', 'Plan of Action and Milestones Process', 'a. Implement a process to ensure that plans of action and milestones for the information security, privacy, and supply chain risk management programs and associated organizational systems:
  1. Are developed and maintained;
  2. Document the remedial information security, privacy, and supply chain risk management actions to adequately respond to risk to organizational operations and assets, individuals, other organizations, and the Nation; and
  3. Are reported in accordance with established reporting requirements.
b. Review plans of action and milestones for consistency with the organizational risk management strategy and organization-wide priorities for risk response actions.'),
  ('PM-5', 'NIST-800-53', 'Program Management', 'System Inventory', 'Develop and update [Assignment: organization-defined frequency] an inventory of organizational systems.'),
  ('PM-5(1)', 'NIST-800-53', 'Program Management', 'System Inventory | Inventory of Personally Identifiable Information', 'Establish, maintain, and update [Assignment: organization-defined frequency] an inventory of all systems, applications, and projects that process personally identifiable information.'),
  ('PM-6', 'NIST-800-53', 'Program Management', 'Measures of Performance', 'Develop, monitor, and report on the results of information security and privacy measures of performance.'),
  ('PM-7', 'NIST-800-53', 'Program Management', 'Enterprise Architecture', 'Develop and maintain an enterprise architecture with consideration for information security, privacy, and the resulting risk to organizational operations and assets, individuals, other organizations, and the Nation.'),
  ('PM-7(1)', 'NIST-800-53', 'Program Management', 'Enterprise Architecture | Offloading', 'Offload [Assignment: organization-defined non-essential functions or services] to other systems, system components, or an external provider.'),
  ('PM-8', 'NIST-800-53', 'Program Management', 'Critical Infrastructure Plan', 'Address information security and privacy issues in the development, documentation, and updating of a critical infrastructure and key resources protection plan.'),
  ('PM-9', 'NIST-800-53', 'Program Management', 'Risk Management Strategy', 'a. Develops a comprehensive strategy to manage:
  1. Security risk to organizational operations and assets, individuals, other organizations, and the Nation associated with the operation and use of organizational systems; and
  2. Privacy risk to individuals resulting from the authorized processing of personally identifiable information;
b. Implement the risk management strategy consistently across the organization; and
c. Review and update the risk management strategy [Assignment: organization-defined frequency] or as required, to address organizational changes.'),
  ('PM-10', 'NIST-800-53', 'Program Management', 'Authorization Process', 'a. Manage the security and privacy state of organizational systems and the environments in which those systems operate through authorization processes;
b. Designate individuals to fulfill specific roles and responsibilities within the organizational risk management process; and
c. Integrate the authorization processes into an organization-wide risk management program.'),
  ('PM-11', 'NIST-800-53', 'Program Management', 'Mission and Business Process Definition', 'a. Define organizational mission and business processes with consideration for information security and privacy and the resulting risk to organizational operations, organizational assets, individuals, other organizations, and the Nation; and
b. Determine information protection and personally identifiable information processing needs arising from the defined mission and business processes; and
c. Review and revise the mission and business processes [Assignment: organization-defined frequency].'),
  ('PM-12', 'NIST-800-53', 'Program Management', 'Insider Threat Program', 'Implement an insider threat program that includes a cross-discipline insider threat incident handling team.'),
  ('PM-13', 'NIST-800-53', 'Program Management', 'Security and Privacy Workforce', 'Establish a security and privacy workforce development and improvement program.'),
  ('PM-14', 'NIST-800-53', 'Program Management', 'Testing, Training, and Monitoring', 'a. Implement a process for ensuring that organizational plans for conducting security and privacy testing, training, and monitoring activities associated with organizational systems:
  1. Are developed and maintained; and
  2. Continue to be executed; and
b. Review testing, training, and monitoring plans for consistency with the organizational risk management strategy and organization-wide priorities for risk response actions.'),
  ('PM-15', 'NIST-800-53', 'Program Management', 'Security and Privacy Groups and Associations', 'Establish and institutionalize contact with selected groups and associations within the security and privacy communities:
  a. To facilitate ongoing security and privacy education and training for organizational personnel;
  b. To maintain currency with recommended security and privacy practices, techniques, and technologies; and
  c. To share current security and privacy information, including threats, vulnerabilities, and incidents.'),
  ('PM-16', 'NIST-800-53', 'Program Management', 'Threat Awareness Program', 'Implement a threat awareness program that includes a cross-organization information-sharing capability for threat intelligence.'),
  ('PM-16(1)', 'NIST-800-53', 'Program Management', 'Threat Awareness Program | Automated Means for Sharing Threat Intelligence', 'Employ automated mechanisms to maximize the effectiveness of sharing threat intelligence information.'),
  ('PM-17', 'NIST-800-53', 'Program Management', 'Protecting Controlled Unclassified Information on External Systems', 'a. Establish policy and procedures to ensure that requirements for the protection of controlled unclassified information that is processed, stored or transmitted on external systems, are implemented in accordance with applicable laws, executive orders, directives, policies, regulations, and standards; and
b. Review and update the policy and procedures [Assignment: organization-defined frequency].'),
  ('PM-18', 'NIST-800-53', 'Program Management', 'Privacy Program Plan', 'a. Develop and disseminate an organization-wide privacy program plan that provides an overview of the agency’s privacy program, and:
  1. Includes a description of the structure of the privacy program and the resources dedicated to the privacy program;
  2. Provides an overview of the requirements for the privacy program and a description of the privacy program management controls and common controls in place or planned for meeting those requirements;
  3. Includes the role of the senior agency official for privacy and the identification and assignment of roles of other privacy officials and staff and their responsibilities;
  4. Describes management commitment, compliance, and the strategic goals and objectives of the privacy program;
  5. Reflects coordination among organizational entities responsible for the different aspects of privacy; and
  6. Is approved by a senior official with responsibility and accountability for the privacy risk being incurred to organizational operations (including mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation; and
b. Update the plan [Assignment: organization-defined frequency] and to address changes in federal privacy laws and policy and organizational changes and problems identified during plan implementation or privacy control assessments.'),
  ('PM-19', 'NIST-800-53', 'Program Management', 'Privacy Program Leadership Role', 'Appoint a senior agency official for privacy with the authority, mission, accountability, and resources to coordinate, develop, and implement, applicable privacy requirements and manage privacy risks through the organization-wide privacy program.'),
  ('PM-20', 'NIST-800-53', 'Program Management', 'Dissemination of Privacy Program Information', 'Maintain a central resource webpage on the organization’s principal public website that serves as a central source of information about the organization’s privacy program and that:
  a. Ensures that the public has access to information about organizational privacy activities and can communicate with its senior agency official for privacy;
  b. Ensures that organizational privacy practices and reports are publicly available; and
  c. Employs publicly facing email addresses and/or phone lines to enable the public to provide feedback and/or direct questions to privacy offices regarding privacy practices.'),
  ('PM-20(1)', 'NIST-800-53', 'Program Management', 'Dissemination of Privacy Program Information | Privacy Policies on Websites, Applications, and Digital Services', 'Develop and post privacy policies on all external-facing websites, mobile applications, and other digital services, that:
  (a) Are written in plain language and organized in a way that is easy to understand and navigate;
  (b) Provide information needed by the public to make an informed decision about whether and how to interact with the organization; and
  (c) Are updated whenever the organization makes a substantive change to the practices it describes and includes a time/date stamp to inform the public of the date of the most recent changes.'),
  ('PM-21', 'NIST-800-53', 'Program Management', 'Accounting of Disclosures', 'a. Develop and maintain an accurate accounting of disclosures of personally identifiable information, including:
  1. Date, nature, and purpose of each disclosure; and
  2. Name and address, or other contact information of the individual or organization to which the disclosure was made;
b. Retain the accounting of disclosures for the length of the time the personally identifiable information is maintained or five years after the disclosure is made, whichever is longer; and
c. Make the accounting of disclosures available to the individual to whom the personally identifiable information relates upon request.'),
  ('PM-22', 'NIST-800-53', 'Program Management', 'Personally Identifiable Information Quality Management', 'Develop and document organization-wide policies and procedures for:
  a. Reviewing for the accuracy, relevance, timeliness, and completeness of personally identifiable information across the information life cycle;
  b. Correcting or deleting inaccurate or outdated personally identifiable information;
  c. Disseminating notice of corrected or deleted personally identifiable information to individuals or other appropriate entities; and
  d. Appeals of adverse decisions on correction or deletion requests.'),
  ('PM-23', 'NIST-800-53', 'Program Management', 'Data Governance Body', 'Establish a Data Governance Body consisting of [Assignment: organization-defined roles] with [Assignment: organization-defined responsibilities].'),
  ('PM-24', 'NIST-800-53', 'Program Management', 'Data Integrity Board', 'Establish a Data Integrity Board to:
  a. Review proposals to conduct or participate in a matching program; and
  b. Conduct an annual review of all matching programs in which the agency has participated.'),
  ('PM-25', 'NIST-800-53', 'Program Management', 'Minimization of Personally Identifiable Information Used in Testing, Training, and Research', 'a. Develop, document, and implement policies and procedures that address the use of personally identifiable information for internal testing, training, and research;
b. Limit or minimize the amount of personally identifiable information used for internal testing, training, and research purposes;
c. Authorize the use of personally identifiable information when such information is required for internal testing, training, and research; and
d. Review and update policies and procedures [Assignment: organization-defined frequency].'),
  ('PM-26', 'NIST-800-53', 'Program Management', 'Complaint Management', 'Implement a process for receiving and responding to complaints, concerns, or questions from individuals about the organizational security and privacy practices that includes:
  a. Mechanisms that are easy to use and readily accessible by the public;
  b. All information necessary for successfully filing complaints;
  c. Tracking mechanisms to ensure all complaints received are reviewed and addressed within [Assignment: organization-defined time period];
  d. Acknowledgement of receipt of complaints, concerns, or questions from individuals within [Assignment: organization-defined time period] ; and
  e. Response to complaints, concerns, or questions from individuals within [Assignment: organization-defined time period].'),
  ('PM-27', 'NIST-800-53', 'Program Management', 'Privacy Reporting', 'a. Develop [Assignment: organization-defined privacy reports] and disseminate to:
  1. [Assignment: organization-defined oversight bodies] to demonstrate accountability with statutory, regulatory, and policy privacy mandates; and
  2. [Assignment: organization-defined officials] and other personnel with responsibility for monitoring privacy program compliance; and
b. Review and update privacy reports [Assignment: organization-defined frequency].'),
  ('PM-28', 'NIST-800-53', 'Program Management', 'Risk Framing', 'a. Identify and document:
  1. Assumptions affecting risk assessments, risk responses, and risk monitoring;
  2. Constraints affecting risk assessments, risk responses, and risk monitoring;
  3. Priorities and trade-offs considered by the organization for managing risk; and
  4. Organizational risk tolerance;
b. Distribute the results of risk framing activities to [Assignment: organization-defined personnel] ; and
c. Review and update risk framing considerations [Assignment: organization-defined frequency].'),
  ('PM-29', 'NIST-800-53', 'Program Management', 'Risk Management Program Leadership Roles', 'a. Appoint a Senior Accountable Official for Risk Management to align organizational information security and privacy management processes with strategic, operational, and budgetary planning processes; and
b. Establish a Risk Executive (function) to view and analyze risk from an organization-wide perspective and ensure management of risk is consistent across the organization.'),
  ('PM-30', 'NIST-800-53', 'Program Management', 'Supply Chain Risk Management Strategy', 'a. Develop an organization-wide strategy for managing supply chain risks associated with the development, acquisition, maintenance, and disposal of systems, system components, and system services;
b. Implement the supply chain risk management strategy consistently across the organization; and
c. Review and update the supply chain risk management strategy on [Assignment: organization-defined frequency] or as required, to address organizational changes.'),
  ('PM-30(1)', 'NIST-800-53', 'Program Management', 'Supply Chain Risk Management Strategy | Suppliers of Critical or Mission-essential Items', 'Identify, prioritize, and assess suppliers of critical or mission-essential technologies, products, and services.'),
  ('PM-31', 'NIST-800-53', 'Program Management', 'Continuous Monitoring Strategy', 'Develop an organization-wide continuous monitoring strategy and implement continuous monitoring programs that include:
  a. Establishing the following organization-wide metrics to be monitored: [Assignment: organization-defined metrics];
  b. Establishing [Assignment: organization-defined monitoring frequencies] and [Assignment: organization-defined assessment frequencies] for control effectiveness;
  c. Ongoing monitoring of organizationally-defined metrics in accordance with the continuous monitoring strategy;
  d. Correlation and analysis of information generated by control assessments and monitoring;
  e. Response actions to address results of the analysis of control assessment and monitoring information; and
  f. Reporting the security and privacy status of organizational systems to [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency].'),
  ('PM-32', 'NIST-800-53', 'Program Management', 'Purposing', 'Analyze [Assignment: organization-defined systems or system components] supporting mission essential services or functions to ensure that the information resources are being used consistent with their intended purpose.'),
  ('PS-1', 'NIST-800-53', 'Personnel Security', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the personnel security policy and the associated personnel security controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the personnel security policy and procedures; and
c. Review and update the current personnel security:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('PS-2', 'NIST-800-53', 'Personnel Security', 'Position Risk Designation', 'a. Assign a risk designation to all organizational positions;
b. Establish screening criteria for individuals filling those positions; and
c. Review and update position risk designations [Assignment: organization-defined frequency].'),
  ('PS-3', 'NIST-800-53', 'Personnel Security', 'Personnel Screening', 'a. Screen individuals prior to authorizing access to the system; and
b. Rescreen individuals in accordance with [Assignment: organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of rescreening].'),
  ('PS-3(1)', 'NIST-800-53', 'Personnel Security', 'Personnel Screening | Classified Information', 'Verify that individuals accessing a system processing, storing, or transmitting classified information are cleared and indoctrinated to the highest classification level of the information to which they have access on the system.'),
  ('PS-3(2)', 'NIST-800-53', 'Personnel Security', 'Personnel Screening | Formal Indoctrination', 'Verify that individuals accessing a system processing, storing, or transmitting types of classified information that require formal indoctrination, are formally indoctrinated for all the relevant types of information to which they have access on the system.'),
  ('PS-3(3)', 'NIST-800-53', 'Personnel Security', 'Personnel Screening | Information Requiring Special Protective Measures', 'Verify that individuals accessing a system processing, storing, or transmitting information requiring special protection:
  (a) Have valid access authorizations that are demonstrated by assigned official government duties; and
  (b) Satisfy [Assignment: organization-defined additional personnel screening criteria].'),
  ('PS-3(4)', 'NIST-800-53', 'Personnel Security', 'Personnel Screening | Citizenship Requirements', 'Verify that individuals accessing a system processing, storing, or transmitting [Assignment: organization-defined information types] meet [Assignment: organization-defined citizenship requirements].'),
  ('PS-4', 'NIST-800-53', 'Personnel Security', 'Personnel Termination', 'Upon termination of individual employment:
  a. Disable system access within [Assignment: organization-defined time period];
  b. Terminate or revoke any authenticators and credentials associated with the individual;
  c. Conduct exit interviews that include a discussion of [Assignment: organization-defined information security topics];
  d. Retrieve all security-related organizational system-related property; and
  e. Retain access to organizational information and systems formerly controlled by terminated individual.'),
  ('PS-4(1)', 'NIST-800-53', 'Personnel Security', 'Personnel Termination | Post-employment Requirements', '(a) Notify terminated individuals of applicable, legally binding post-employment requirements for the protection of organizational information; and
(b) Require terminated individuals to sign an acknowledgment of post-employment requirements as part of the organizational termination process.'),
  ('PS-4(2)', 'NIST-800-53', 'Personnel Security', 'Personnel Termination | Automated Actions', 'Use [Assignment: organization-defined automated mechanisms] to [Selection (one or more): notify [Assignment: organization-defined personnel or roles] of individual termination actions; disable access to system resources].'),
  ('PS-5', 'NIST-800-53', 'Personnel Security', 'Personnel Transfer', 'a. Review and confirm ongoing operational need for current logical and physical access authorizations to systems and facilities when individuals are reassigned or transferred to other positions within the organization;
b. Initiate [Assignment: organization-defined transfer or reassignment actions] within [Assignment: organization-defined time period following the formal transfer action];
c. Modify access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and
d. Notify [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period].'),
  ('PS-6', 'NIST-800-53', 'Personnel Security', 'Access Agreements', 'a. Develop and document access agreements for organizational systems;
b. Review and update the access agreements [Assignment: organization-defined frequency] ; and
c. Verify that individuals requiring access to organizational information and systems:
  1. Sign appropriate access agreements prior to being granted access; and
  2. Re-sign access agreements to maintain access to organizational systems when access agreements have been updated or [Assignment: organization-defined frequency].'),
  ('PS-6(2)', 'NIST-800-53', 'Personnel Security', 'Access Agreements | Classified Information Requiring Special Protection', 'Verify that access to classified information requiring special protection is granted only to individuals who:
  (a) Have a valid access authorization that is demonstrated by assigned official government duties;
  (b) Satisfy associated personnel security criteria; and
  (c) Have read, understood, and signed a nondisclosure agreement.'),
  ('PS-6(3)', 'NIST-800-53', 'Personnel Security', 'Access Agreements | Post-employment Requirements', '(a) Notify individuals of applicable, legally binding post-employment requirements for protection of organizational information; and
(b) Require individuals to sign an acknowledgment of these requirements, if applicable, as part of granting initial access to covered information.'),
  ('PS-7', 'NIST-800-53', 'Personnel Security', 'External Personnel Security', 'a. Establish personnel security requirements, including security roles and responsibilities for external providers;
b. Require external providers to comply with personnel security policies and procedures established by the organization;
c. Document personnel security requirements;
d. Require external providers to notify [Assignment: organization-defined personnel or roles] of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges, or who have system privileges within [Assignment: organization-defined time period] ; and
e. Monitor provider compliance with personnel security requirements.'),
  ('PS-8', 'NIST-800-53', 'Personnel Security', 'Personnel Sanctions', 'a. Employ a formal sanctions process for individuals failing to comply with established information security and privacy policies and procedures; and
b. Notify [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period] when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.'),
  ('PS-9', 'NIST-800-53', 'Personnel Security', 'Position Descriptions', 'Incorporate security and privacy roles and responsibilities into organizational position descriptions.'),
  ('PT-1', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] personally identifiable information processing and transparency policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the personally identifiable information processing and transparency policy and the associated personally identifiable information processing and transparency controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the personally identifiable information processing and transparency policy and procedures; and
c. Review and update the current personally identifiable information processing and transparency:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('PT-2', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Authority to Process Personally Identifiable Information', 'a. Determine and document the [Assignment: organization-defined authority] that permits the [Assignment: organization-defined processing] of personally identifiable information; and
b. Restrict the [Assignment: organization-defined processing] of personally identifiable information to only that which is authorized.'),
  ('PT-2(1)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Authority to Process Personally Identifiable Information | Data Tagging', 'Attach data tags containing [Assignment: organization-defined authorized processing] to [Assignment: organization-defined elements of personally identifiable information].'),
  ('PT-2(2)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Authority to Process Personally Identifiable Information | Automation', 'Manage enforcement of the authorized processing of personally identifiable information using [Assignment: organization-defined automated mechanisms].'),
  ('PT-3', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Personally Identifiable Information Processing Purposes', 'a. Identify and document the [Assignment: organization-defined purpose(s)] for processing personally identifiable information;
b. Describe the purpose(s) in the public privacy notices and policies of the organization;
c. Restrict the [Assignment: organization-defined processing] of personally identifiable information to only that which is compatible with the identified purpose(s); and
d. Monitor changes in processing personally identifiable information and implement [Assignment: organization-defined mechanisms] to ensure that any changes are made in accordance with [Assignment: organization-defined requirements].')
ON CONFLICT (control_id) DO UPDATE
  SET family = EXCLUDED.family, title = EXCLUDED.title, description = EXCLUDED.description
  WHERE compliance_controls.framework = 'NIST-800-53';

INSERT INTO compliance_controls (control_id, framework, family, title, description) VALUES
  ('PT-3(1)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Personally Identifiable Information Processing Purposes | Data Tagging', 'Attach data tags containing the following purposes to [Assignment: organization-defined elements of personally identifiable information]: [Assignment: organization-defined processing purposes].'),
  ('PT-3(2)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Personally Identifiable Information Processing Purposes | Automation', 'Track processing purposes of personally identifiable information using [Assignment: organization-defined automated mechanisms].'),
  ('PT-4', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Consent', 'Implement [Assignment: organization-defined tools or mechanisms] for individuals to consent to the processing of their personally identifiable information prior to its collection that facilitate individuals’ informed decision-making.'),
  ('PT-4(1)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Consent | Tailored Consent', 'Provide [Assignment: organization-defined mechanisms] to allow individuals to tailor processing permissions to selected elements of personally identifiable information.'),
  ('PT-4(2)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Consent | Just-in-time Consent', 'Present [Assignment: organization-defined consent mechanisms] to individuals at [Assignment: organization-defined frequency] and in conjunction with [Assignment: organization-defined personally identifiable information processing].'),
  ('PT-4(3)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Consent | Revocation', 'Implement [Assignment: organization-defined tools or mechanisms] for individuals to revoke consent to the processing of their personally identifiable information.'),
  ('PT-5', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Privacy Notice', 'Provide notice to individuals about the processing of personally identifiable information that:
  a. Is available to individuals upon first interacting with an organization, and subsequently at [Assignment: organization-defined frequency];
  b. Is clear and easy-to-understand, expressing information about personally identifiable information processing in plain language;
  c. Identifies the authority that authorizes the processing of personally identifiable information;
  d. Identifies the purposes for which personally identifiable information is to be processed; and
  e. Includes [Assignment: organization-defined information].'),
  ('PT-5(1)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Privacy Notice | Just-in-time Notice', 'Present notice of personally identifiable information processing to individuals at a time and location where the individual provides personally identifiable information or in conjunction with a data action, or [Assignment: organization-defined frequency].'),
  ('PT-5(2)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Privacy Notice | Privacy Act Statements', 'Include Privacy Act statements on forms that collect information that will be maintained in a Privacy Act system of records, or provide Privacy Act statements on separate forms that can be retained by individuals.'),
  ('PT-6', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'System of Records Notice', 'For systems that process information that will be maintained in a Privacy Act system of records:
  a. Draft system of records notices in accordance with OMB guidance and submit new and significantly modified system of records notices to the OMB and appropriate congressional committees for advance review;
  b. Publish system of records notices in the Federal Register; and
  c. Keep system of records notices accurate, up-to-date, and scoped in accordance with policy.'),
  ('PT-6(1)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'System of Records Notice | Routine Uses', 'Review all routine uses published in the system of records notice at [Assignment: organization-defined frequency] to ensure continued accuracy, and to ensure that routine uses continue to be compatible with the purpose for which the information was collected.'),
  ('PT-6(2)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'System of Records Notice | Exemption Rules', 'Review all Privacy Act exemptions claimed for the system of records at [Assignment: organization-defined frequency] to ensure they remain appropriate and necessary in accordance with law, that they have been promulgated as regulations, and that they are accurately described in the system of records notice.'),
  ('PT-7', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Specific Categories of Personally Identifiable Information', 'Apply [Assignment: organization-defined processing conditions] for specific categories of personally identifiable information.'),
  ('PT-7(1)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Specific Categories of Personally Identifiable Information | Social Security Numbers', 'When a system processes Social Security numbers:
  (a) Eliminate unnecessary collection, maintenance, and use of Social Security numbers, and explore alternatives to their use as a personal identifier;
  (b) Do not deny any individual any right, benefit, or privilege provided by law because of such individual’s refusal to disclose his or her Social Security number; and
  (c) Inform any individual who is asked to disclose his or her Social Security number whether that disclosure is mandatory or voluntary, by what statutory or other authority such number is solicited, and what uses will be made of it.'),
  ('PT-7(2)', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Specific Categories of Personally Identifiable Information | First Amendment Information', 'Prohibit the processing of information describing how any individual exercises rights guaranteed by the First Amendment unless expressly authorized by statute or by the individual or unless pertinent to and within the scope of an authorized law enforcement activity.'),
  ('PT-8', 'NIST-800-53', 'Personally Identifiable Information Processing and Transparency', 'Computer Matching Requirements', 'When a system or organization processes information for the purpose of conducting a matching program:
  a. Obtain approval from the Data Integrity Board to conduct the matching program;
  b. Develop and enter into a computer matching agreement;
  c. Publish a matching notice in the Federal Register;
  d. Independently verify the information produced by the matching program before taking adverse action against an individual, if required; and
  e. Provide individuals with notice and an opportunity to contest the findings before taking adverse action against an individual.'),
  ('RA-1', 'NIST-800-53', 'Risk Assessment', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the risk assessment policy and the associated risk assessment controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the risk assessment policy and procedures; and
c. Review and update the current risk assessment:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('RA-2', 'NIST-800-53', 'Risk Assessment', 'Security Categorization', 'a. Categorize the system and information it processes, stores, and transmits;
b. Document the security categorization results, including supporting rationale, in the security plan for the system; and
c. Verify that the authorizing official or authorizing official designated representative reviews and approves the security categorization decision.'),
  ('RA-2(1)', 'NIST-800-53', 'Risk Assessment', 'Security Categorization | Impact-level Prioritization', 'Conduct an impact-level prioritization of organizational systems to obtain additional granularity on system impact levels.'),
  ('RA-3', 'NIST-800-53', 'Risk Assessment', 'Risk Assessment', 'a. Conduct a risk assessment, including:
  1. Identifying threats to and vulnerabilities in the system;
  2. Determining the likelihood and magnitude of harm from unauthorized access, use, disclosure, disruption, modification, or destruction of the system, the information it processes, stores, or transmits, and any related information; and
  3. Determining the likelihood and impact of adverse effects on individuals arising from the processing of personally identifiable information;
b. Integrate risk assessment results and risk management decisions from the organization and mission or business process perspectives with system-level risk assessments;
c. Document risk assessment results in [Selection: security and privacy plans; risk assessment report; [Assignment: organization-defined document] ];
d. Review risk assessment results [Assignment: organization-defined frequency];
e. Disseminate risk assessment results to [Assignment: organization-defined personnel or roles] ; and
f. Update the risk assessment [Assignment: organization-defined frequency] or when there are significant changes to the system, its environment of operation, or other conditions that may impact the security or privacy state of the system.'),
  ('RA-3(1)', 'NIST-800-53', 'Risk Assessment', 'Risk Assessment | Supply Chain Risk Assessment', '(a) Assess supply chain risks associated with [Assignment: organization-defined systems, system components, and system services] ; and
(b) Update the supply chain risk assessment [Assignment: organization-defined frequency] , when there are significant changes to the relevant supply chain, or when changes to the system, environments of operation, or other conditions may necessitate a change in the supply chain.'),
  ('RA-3(2)', 'NIST-800-53', 'Risk Assessment', 'Risk Assessment | Use of All-source Intelligence', 'Use all-source intelligence to assist in the analysis of risk.'),
  ('RA-3(3)', 'NIST-800-53', 'Risk Assessment', 'Risk Assessment | Dynamic Threat Awareness', 'Determine the current cyber threat environment on an ongoing basis using [Assignment: organization-defined means].'),
  ('RA-3(4)', 'NIST-800-53', 'Risk Assessment', 'Risk Assessment | Predictive Cyber Analytics', 'Employ the following advanced automation and analytics capabilities to predict and identify risks to [Assignment: organization-defined systems or system components]: [Assignment: organization-defined advanced automation and analytics capabilities].'),
  ('RA-5', 'NIST-800-53', 'Risk Assessment', 'Vulnerability Monitoring and Scanning', 'a. Monitor and scan for vulnerabilities in the system and hosted applications [Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process] and when new vulnerabilities potentially affecting the system are identified and reported;
b. Employ vulnerability monitoring tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for:
  1. Enumerating platforms, software flaws, and improper configurations;
  2. Formatting checklists and test procedures; and
  3. Measuring vulnerability impact;
c. Analyze vulnerability scan reports and results from vulnerability monitoring;
d. Remediate legitimate vulnerabilities [Assignment: organization-defined response times] in accordance with an organizational assessment of risk;
e. Share information obtained from the vulnerability monitoring process and control assessments with [Assignment: organization-defined personnel or roles] to help eliminate similar vulnerabilities in other systems; and
f. Employ vulnerability monitoring tools that include the capability to readily update the vulnerabilities to be scanned.'),
  ('RA-5(2)', 'NIST-800-53', 'Risk Assessment', 'Vulnerability Monitoring and Scanning | Update Vulnerabilities to Be Scanned', 'Update the system vulnerabilities to be scanned [Selection (one or more): [Assignment: organization-defined frequency] ; prior to a new scan; when new vulnerabilities are identified and reported].'),
  ('RA-5(3)', 'NIST-800-53', 'Risk Assessment', 'Vulnerability Monitoring and Scanning | Breadth and Depth of Coverage', 'Define the breadth and depth of vulnerability scanning coverage.'),
  ('RA-5(4)', 'NIST-800-53', 'Risk Assessment', 'Vulnerability Monitoring and Scanning | Discoverable Information', 'Determine information about the system that is discoverable and take [Assignment: organization-defined corrective actions].'),
  ('RA-5(5)', 'NIST-800-53', 'Risk Assessment', 'Vulnerability Monitoring and Scanning | Privileged Access', 'Implement privileged access authorization to [Assignment: organization-defined system components] for [Assignment: organization-defined vulnerability scanning activities].'),
  ('RA-5(6)', 'NIST-800-53', 'Risk Assessment', 'Vulnerability Monitoring and Scanning | Automated Trend Analyses', 'Compare the results of multiple vulnerability scans using [Assignment: organization-defined automated mechanisms].'),
  ('RA-5(8)', 'NIST-800-53', 'Risk Assessment', 'Vulnerability Monitoring and Scanning | Review Historic Audit Logs', 'Review historic audit logs to determine if a vulnerability identified in a [Assignment: organization-defined system] has been previously exploited within an [Assignment: organization-defined time period].'),
  ('RA-5(10)', 'NIST-800-53', 'Risk Assessment', 'Vulnerability Monitoring and Scanning | Correlate Scanning Information', 'Correlate the output from vulnerability scanning tools to determine the presence of multi-vulnerability and multi-hop attack vectors.'),
  ('RA-5(11)', 'NIST-800-53', 'Risk Assessment', 'Vulnerability Monitoring and Scanning | Public Disclosure Program', 'Establish a public reporting channel for receiving reports of vulnerabilities in organizational systems and system components.'),
  ('RA-6', 'NIST-800-53', 'Risk Assessment', 'Technical Surveillance Countermeasures Survey', 'Employ a technical surveillance countermeasures survey at [Assignment: organization-defined locations] [Selection (one or more): [Assignment: organization-defined frequency] ; when [Assignment: organization-defined events or indicators] ].'),
  ('RA-7', 'NIST-800-53', 'Risk Assessment', 'Risk Response', 'Respond to findings from security and privacy assessments, monitoring, and audits in accordance with organizational risk tolerance.'),
  ('RA-8', 'NIST-800-53', 'Risk Assessment', 'Privacy Impact Assessments', 'Conduct privacy impact assessments for systems, programs, or other activities before:
  a. Developing or procuring information technology that processes personally identifiable information; and
  b. Initiating a new collection of personally identifiable information that:
    1. Will be processed using information technology; and
    2. Includes personally identifiable information permitting the physical or virtual (online) contacting of a specific individual, if identical questions have been posed to, or identical reporting requirements imposed on, ten or more individuals, other than agencies, instrumentalities, or employees of the federal government.'),
  ('RA-9', 'NIST-800-53', 'Risk Assessment', 'Criticality Analysis', 'Identify critical system components and functions by performing a criticality analysis for [Assignment: organization-defined systems, system components, or system services] at [Assignment: organization-defined decision points in the system development life cycle].'),
  ('RA-10', 'NIST-800-53', 'Risk Assessment', 'Threat Hunting', 'a. Establish and maintain a cyber threat hunting capability to:
  1. Search for indicators of compromise in organizational systems; and
  2. Detect, track, and disrupt threats that evade existing controls; and
b. Employ the threat hunting capability [Assignment: organization-defined frequency].'),
  ('SA-1', 'NIST-800-53', 'System and Services Acquisition', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the system and services acquisition policy and the associated system and services acquisition controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and services acquisition policy and procedures; and
c. Review and update the current system and services acquisition:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('SA-2', 'NIST-800-53', 'System and Services Acquisition', 'Allocation of Resources', 'a. Determine the high-level information security and privacy requirements for the system or system service in mission and business process planning;
b. Determine, document, and allocate the resources required to protect the system or system service as part of the organizational capital planning and investment control process; and
c. Establish a discrete line item for information security and privacy in organizational programming and budgeting documentation.'),
  ('SA-3', 'NIST-800-53', 'System and Services Acquisition', 'System Development Life Cycle', 'a. Acquire, develop, and manage the system using [Assignment: organization-defined system-development life cycle] that incorporates information security and privacy considerations;
b. Define and document information security and privacy roles and responsibilities throughout the system development life cycle;
c. Identify individuals having information security and privacy roles and responsibilities; and
d. Integrate the organizational information security and privacy risk management process into system development life cycle activities.'),
  ('SA-3(1)', 'NIST-800-53', 'System and Services Acquisition', 'System Development Life Cycle | Manage Preproduction Environment', 'Protect system preproduction environments commensurate with risk throughout the system development life cycle for the system, system component, or system service.'),
  ('SA-3(2)', 'NIST-800-53', 'System and Services Acquisition', 'System Development Life Cycle | Use of Live or Operational Data', '(a) Approve, document, and control the use of live data in preproduction environments for the system, system component, or system service; and
(b) Protect preproduction environments for the system, system component, or system service at the same impact or classification level as any live data in use within the preproduction environments.'),
  ('SA-3(3)', 'NIST-800-53', 'System and Services Acquisition', 'System Development Life Cycle | Technology Refresh', 'Plan for and implement a technology refresh schedule for the system throughout the system development life cycle.'),
  ('SA-4', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process', 'Include the following requirements, descriptions, and criteria, explicitly or by reference, using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language] ] in the acquisition contract for the system, system component, or system service:
  a. Security and privacy functional requirements;
  b. Strength of mechanism requirements;
  c. Security and privacy assurance requirements;
  d. Controls needed to satisfy the security and privacy requirements.
  e. Security and privacy documentation requirements;
  f. Requirements for protecting security and privacy documentation;
  g. Description of the system development environment and environment in which the system is intended to operate;
  h. Allocation of responsibility or identification of parties responsible for information security, privacy, and supply chain risk management; and
  i. Acceptance criteria.'),
  ('SA-4(1)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | Functional Properties of Controls', 'Require the developer of the system, system component, or system service to provide a description of the functional properties of the controls to be implemented.'),
  ('SA-4(2)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | Design and Implementation Information for Controls', 'Require the developer of the system, system component, or system service to provide design and implementation information for the controls that includes: [Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design and implementation information] ] at [Assignment: organization-defined level of detail].'),
  ('SA-4(3)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | Development Methods, Techniques, and Practices', 'Require the developer of the system, system component, or system service to demonstrate the use of a system development life cycle process that includes:
  (a) [Assignment: organization-defined systems engineering methods];
  (b) [Selection (one or more): [Assignment: organization-defined system security engineering methods] ; [Assignment: organization-defined privacy engineering methods] ] ; and
  (c) [Selection (one or more): [Assignment: organization-defined software development methods] ; [Assignment: organization-defined testing, evaluation, assessment, verification, and validation methods] ; [Assignment: organization-defined quality control processes] ].'),
  ('SA-4(5)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | System, Component, and Service Configurations', 'Require the developer of the system, system component, or system service to:
  (a) Deliver the system, component, or service with [Assignment: organization-defined security configurations] implemented; and
  (b) Use the configurations as the default for any subsequent system, component, or service reinstallation or upgrade.'),
  ('SA-4(6)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | Use of Information Assurance Products', '(a) Employ only government off-the-shelf or commercial off-the-shelf information assurance and information assurance-enabled information technology products that compose an NSA-approved solution to protect classified information when the networks used to transmit the information are at a lower classification level than the information being transmitted; and
(b) Ensure that these products have been evaluated and/or validated by NSA or in accordance with NSA-approved procedures.'),
  ('SA-4(7)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | NIAP-approved Protection Profiles ', '(a) Limit the use of commercially provided information assurance and information assurance-enabled information technology products to those products that have been successfully evaluated against a National Information Assurance partnership (NIAP)-approved Protection Profile for a specific technology type, if such a profile exists; and
(b) Require, if no NIAP-approved Protection Profile exists for a specific technology type but a commercially provided information technology product relies on cryptographic functionality to enforce its security policy, that the cryptographic module is FIPS-validated or NSA-approved.'),
  ('SA-4(8)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | Continuous Monitoring Plan for Controls', 'Require the developer of the system, system component, or system service to produce a plan for continuous monitoring of control effectiveness that is consistent with the continuous monitoring program of the organization.'),
  ('SA-4(9)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | Functions, Ports, Protocols, and Services in Use', 'Require the developer of the system, system component, or system service to identify the functions, ports, protocols, and services intended for organizational use.'),
  ('SA-4(10)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | Use of Approved PIV Products', 'Employ only information technology products on the FIPS 201-approved products list for Personal Identity Verification (PIV) capability implemented within organizational systems.'),
  ('SA-4(11)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | System of Records', 'Include [Assignment: organization-defined Privacy Act requirements] in the acquisition contract for the operation of a system of records on behalf of an organization to accomplish an organizational mission or function.'),
  ('SA-4(12)', 'NIST-800-53', 'System and Services Acquisition', 'Acquisition Process | Data Ownership', '(a) Include organizational data ownership requirements in the acquisition contract; and
(b) Require all data to be removed from the contractor’s system and returned to the organization within [Assignment: organization-defined time frame].'),
  ('SA-5', 'NIST-800-53', 'System and Services Acquisition', 'System Documentation', 'a. Obtain or develop administrator documentation for the system, system component, or system service that describes:
  1. Secure configuration, installation, and operation of the system, component, or service;
  2. Effective use and maintenance of security and privacy functions and mechanisms; and
  3. Known vulnerabilities regarding configuration and use of administrative or privileged functions;
b. Obtain or develop user documentation for the system, system component, or system service that describes:
  1. User-accessible security and privacy functions and mechanisms and how to effectively use those functions and mechanisms;
  2. Methods for user interaction, which enables individuals to use the system, component, or service in a more secure manner and protect individual privacy; and
  3. User responsibilities in maintaining the security of the system, component, or service and privacy of individuals;
c. Document attempts to obtain system, system component, or system service documentation when such documentation is either unavailable or nonexistent and take [Assignment: organization-defined actions] in response; and
d. Distribute documentation to [Assignment: organization-defined personnel or roles].'),
  ('SA-8', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles', 'Apply the following systems security and privacy engineering principles in the specification, design, development, implementation, and modification of the system and system components: [Assignment: organization-defined systems security and privacy engineering principles].'),
  ('SA-8(1)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Clear Abstractions', 'Implement the security design principle of clear abstractions.'),
  ('SA-8(2)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Least Common Mechanism', 'Implement the security design principle of least common mechanism in [Assignment: organization-defined systems or system components].'),
  ('SA-8(3)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Modularity and Layering', 'Implement the security design principles of modularity and layering in [Assignment: organization-defined systems or system components].'),
  ('SA-8(4)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Partially Ordered Dependencies', 'Implement the security design principle of partially ordered dependencies in [Assignment: organization-defined systems or system components].'),
  ('SA-8(5)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Efficiently Mediated Access', 'Implement the security design principle of efficiently mediated access in [Assignment: organization-defined systems or system components].'),
  ('SA-8(6)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Minimized Sharing', 'Implement the security design principle of minimized sharing in [Assignment: organization-defined systems or system components].'),
  ('SA-8(7)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Reduced Complexity', 'Implement the security design principle of reduced complexity in [Assignment: organization-defined systems or system components].'),
  ('SA-8(8)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Secure Evolvability', 'Implement the security design principle of secure evolvability in [Assignment: organization-defined systems or system components].'),
  ('SA-8(9)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Trusted Components', 'Implement the security design principle of trusted components in [Assignment: organization-defined systems or system components].'),
  ('SA-8(10)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Hierarchical Trust', 'Implement the security design principle of hierarchical trust in [Assignment: organization-defined systems or system components].'),
  ('SA-8(11)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Inverse Modification Threshold', 'Implement the security design principle of inverse modification threshold in [Assignment: organization-defined systems or system components].'),
  ('SA-8(12)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Hierarchical Protection', 'Implement the security design principle of hierarchical protection in [Assignment: organization-defined systems or system components].'),
  ('SA-8(13)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Minimized Security Elements', 'Implement the security design principle of minimized security elements in [Assignment: organization-defined systems or system components].'),
  ('SA-8(14)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Least Privilege', 'Implement the security design principle of least privilege in [Assignment: organization-defined systems or system components].'),
  ('SA-8(15)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Predicate Permission', 'Implement the security design principle of predicate permission in [Assignment: organization-defined systems or system components].'),
  ('SA-8(16)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Self-reliant Trustworthiness', 'Implement the security design principle of self-reliant trustworthiness in [Assignment: organization-defined systems or system components].'),
  ('SA-8(17)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Secure Distributed Composition', 'Implement the security design principle of secure distributed composition in [Assignment: organization-defined systems or system components].'),
  ('SA-8(18)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Trusted Communications Channels', 'Implement the security design principle of trusted communications channels in [Assignment: organization-defined systems or system components].'),
  ('SA-8(19)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Continuous Protection', 'Implement the security design principle of continuous protection in [Assignment: organization-defined systems or system components].'),
  ('SA-8(20)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Secure Metadata Management', 'Implement the security design principle of secure metadata management in [Assignment: organization-defined systems or system components].'),
  ('SA-8(21)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Self-analysis', 'Implement the security design principle of self-analysis in [Assignment: organization-defined systems or system components].'),
  ('SA-8(22)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Accountability and Traceability', 'Implement the security design principle of accountability and traceability in [Assignment: organization-defined systems or system components].'),
  ('SA-8(23)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Secure Defaults', 'Implement the security design principle of secure defaults in [Assignment: organization-defined systems or system components].'),
  ('SA-8(24)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Secure Failure and Recovery', 'Implement the security design principle of secure failure and recovery in [Assignment: organization-defined systems or system components].'),
  ('SA-8(25)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Economic Security', 'Implement the security design principle of economic security in [Assignment: organization-defined systems or system components].'),
  ('SA-8(26)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Performance Security', 'Implement the security design principle of performance security in [Assignment: organization-defined systems or system components].'),
  ('SA-8(27)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Human Factored Security', 'Implement the security design principle of human factored security in [Assignment: organization-defined systems or system components].'),
  ('SA-8(28)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Acceptable Security', 'Implement the security design principle of acceptable security in [Assignment: organization-defined systems or system components].'),
  ('SA-8(29)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Repeatable and Documented Procedures', 'Implement the security design principle of repeatable and documented procedures in [Assignment: organization-defined systems or system components].'),
  ('SA-8(30)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Procedural Rigor', 'Implement the security design principle of procedural rigor in [Assignment: organization-defined systems or system components].'),
  ('SA-8(31)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Secure System Modification', 'Implement the security design principle of secure system modification in [Assignment: organization-defined systems or system components].'),
  ('SA-8(32)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Sufficient Documentation', 'Implement the security design principle of sufficient documentation in [Assignment: organization-defined systems or system components].'),
  ('SA-8(33)', 'NIST-800-53', 'System and Services Acquisition', 'Security and Privacy Engineering Principles | Minimization', 'Implement the privacy principle of minimization using [Assignment: organization-defined processes].'),
  ('SA-9', 'NIST-800-53', 'System and Services Acquisition', 'External System Services', 'a. Require that providers of external system services comply with organizational security and privacy requirements and employ the following controls: [Assignment: organization-defined controls];
b. Define and document organizational oversight and user roles and responsibilities with regard to external system services; and
c. Employ the following processes, methods, and techniques to monitor control compliance by external service providers on an ongoing basis: [Assignment: organization-defined processes, methods, and techniques].'),
  ('SA-9(1)', 'NIST-800-53', 'System and Services Acquisition', 'External System Services | Risk Assessments and Organizational Approvals', '(a) Conduct an organizational assessment of risk prior to the acquisition or outsourcing of information security services; and
(b) Verify that the acquisition or outsourcing of dedicated information security services is approved by [Assignment: organization-defined personnel or roles].'),
  ('SA-9(2)', 'NIST-800-53', 'System and Services Acquisition', 'External System Services | Identification of Functions, Ports, Protocols, and Services', 'Require providers of the following external system services to identify the functions, ports, protocols, and other services required for the use of such services: [Assignment: organization-defined external system services].'),
  ('SA-9(3)', 'NIST-800-53', 'System and Services Acquisition', 'External System Services | Establish and Maintain Trust Relationship with Providers', 'Establish, document, and maintain trust relationships with external service providers based on the following requirements, properties, factors, or conditions: [Assignment: organization-defined security and privacy requirements, properties, factors, or conditions defining acceptable trust relationships].'),
  ('SA-9(4)', 'NIST-800-53', 'System and Services Acquisition', 'External System Services | Consistent Interests of Consumers and Providers', 'Take the following actions to verify that the interests of [Assignment: organization-defined external service providers] are consistent with and reflect organizational interests: [Assignment: organization-defined actions].'),
  ('SA-9(5)', 'NIST-800-53', 'System and Services Acquisition', 'External System Services | Processing, Storage, and Service Location', 'Restrict the location of [Selection (one or more): information processing; information or data; system services] to [Assignment: organization-defined locations] based on [Assignment: organization-defined requirements].'),
  ('SA-9(6)', 'NIST-800-53', 'System and Services Acquisition', 'External System Services | Organization-controlled Cryptographic Keys', 'Maintain exclusive control of cryptographic keys for encrypted material stored or transmitted through an external system.'),
  ('SA-9(7)', 'NIST-800-53', 'System and Services Acquisition', 'External System Services | Organization-controlled Integrity Checking', 'Provide the capability to check the integrity of information while it resides in the external system.'),
  ('SA-9(8)', 'NIST-800-53', 'System and Services Acquisition', 'External System Services | Processing and Storage Location — U.S. Jurisdiction', 'Restrict the geographic location of information processing and data storage to facilities located within in the legal jurisdictional boundary of the United States.'),
  ('SA-10', 'NIST-800-53', 'System and Services Acquisition', 'Developer Configuration Management', 'Require the developer of the system, system component, or system service to:
  a. Perform configuration management during system, component, or service [Selection (one or more): design; development; implementation; operation; disposal];
  b. Document, manage, and control the integrity of changes to [Assignment: organization-defined configuration items];
  c. Implement only organization-approved changes to the system, component, or service;
  d. Document approved changes to the system, component, or service and the potential security and privacy impacts of such changes; and
  e. Track security flaws and flaw resolution within the system, component, or service and report findings to [Assignment: organization-defined personnel].'),
  ('SA-10(1)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Configuration Management | Software and Firmware Integrity Verification', 'Require the developer of the system, system component, or system service to enable integrity verification of software and firmware components.'),
  ('SA-10(2)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Configuration Management | Alternative Configuration Management Processes', 'Provide an alternate configuration management process using organizational personnel in the absence of a dedicated developer configuration management team.'),
  ('SA-10(3)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Configuration Management | Hardware Integrity Verification', 'Require the developer of the system, system component, or system service to enable integrity verification of hardware components.'),
  ('SA-10(4)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Configuration Management | Trusted Generation', 'Require the developer of the system, system component, or system service to employ tools for comparing newly generated versions of security-relevant hardware descriptions, source code, and object code with previous versions.'),
  ('SA-10(5)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Configuration Management | Mapping Integrity for Version Control', 'Require the developer of the system, system component, or system service to maintain the integrity of the mapping between the master build data describing the current version of security-relevant hardware, software, and firmware and the on-site master copy of the data for the current version.'),
  ('SA-10(6)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Configuration Management | Trusted Distribution', 'Require the developer of the system, system component, or system service to execute procedures for ensuring that security-relevant hardware, software, and firmware updates distributed to the organization are exactly as specified by the master copies.'),
  ('SA-10(7)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Configuration Management | Security and Privacy Representatives', 'Require [Assignment: organization-defined security and privacy representatives] to be included in the [Assignment: organization-defined configuration change management and control process].'),
  ('SA-11', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation', 'Require the developer of the system, system component, or system service, at all post-design stages of the system development life cycle, to:
  a. Develop and implement a plan for ongoing security and privacy control assessments;
  b. Perform [Selection (one or more): unit; integration; system; regression] testing/evaluation [Assignment: organization-defined frequency to conduct] at [Assignment: organization-defined depth and coverage];
  c. Produce evidence of the execution of the assessment plan and the results of the testing and evaluation;
  d. Implement a verifiable flaw remediation process; and
  e. Correct flaws identified during testing and evaluation.'),
  ('SA-11(1)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation | Static Code Analysis', 'Require the developer of the system, system component, or system service to employ static code analysis tools to identify common flaws and document the results of the analysis.'),
  ('SA-11(2)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation | Threat Modeling and Vulnerability Analyses', 'Require the developer of the system, system component, or system service to perform threat modeling and vulnerability analyses during development and the subsequent testing and evaluation of the system, component, or service that:
  (a) Uses the following contextual information: [Assignment: organization-defined information];
  (b) Employs the following tools and methods: [Assignment: organization-defined tools and methods];
  (c) Conducts the modeling and analyses at the following level of rigor: [Assignment: organization-defined breadth and depth of modeling and analyses] ; and
  (d) Produces evidence that meets the following acceptance criteria: [Assignment: organization-defined acceptance criteria].'),
  ('SA-11(3)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation | Independent Verification of Assessment Plans and Evidence', '(a) Require an independent agent satisfying [Assignment: organization-defined independence criteria] to verify the correct implementation of the developer security and privacy assessment plans and the evidence produced during testing and evaluation; and
(b) Verify that the independent agent is provided with sufficient information to complete the verification process or granted the authority to obtain such information.'),
  ('SA-11(4)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation | Manual Code Reviews', 'Require the developer of the system, system component, or system service to perform a manual code review of [Assignment: organization-defined specific code] using the following processes, procedures, and/or techniques: [Assignment: organization-defined processes, procedures, and/or techniques].'),
  ('SA-11(5)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation | Penetration Testing', 'Require the developer of the system, system component, or system service to perform penetration testing:
  (a) At the following level of rigor: [Assignment: organization-defined breadth and depth of testing] ; and
  (b) Under the following constraints: [Assignment: organization-defined constraints].'),
  ('SA-11(6)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation | Attack Surface Reviews', 'Require the developer of the system, system component, or system service to perform attack surface reviews.'),
  ('SA-11(7)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation | Verify Scope of Testing and Evaluation', 'Require the developer of the system, system component, or system service to verify that the scope of testing and evaluation provides complete coverage of the required controls at the following level of rigor: [Assignment: organization-defined breadth and depth of testing and evaluation].'),
  ('SA-11(8)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation | Dynamic Code Analysis', 'Require the developer of the system, system component, or system service to employ dynamic code analysis tools to identify common flaws and document the results of the analysis.'),
  ('SA-11(9)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Testing and Evaluation | Interactive Application Security Testing', 'Require the developer of the system, system component, or system service to employ interactive application security testing tools to identify flaws and document the results.'),
  ('SA-15', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools', 'a. Require the developer of the system, system component, or system service to follow a documented development process that:
  1. Explicitly addresses security and privacy requirements;
  2. Identifies the standards and tools used in the development process;
  3. Documents the specific tool options and tool configurations used in the development process; and
  4. Documents, manages, and ensures the integrity of changes to the process and/or tools used in development; and
b. Review the development process, standards, tools, tool options, and tool configurations [Assignment: organization-defined frequency] to determine if the process, standards, tools, tool options and tool configurations selected and employed can satisfy the following security and privacy requirements: [Assignment: organization-defined security and privacy requirements].'),
  ('SA-15(1)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Quality Metrics', 'Require the developer of the system, system component, or system service to:
  (a) Define quality metrics at the beginning of the development process; and
  (b) Provide evidence of meeting the quality metrics [Selection (one or more): [Assignment: organization-defined frequency] ; [Assignment: organization-defined program review] ; upon delivery].'),
  ('SA-15(2)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Security and Privacy Tracking Tools', 'Require the developer of the system, system component, or system service to select and employ security and privacy tracking tools for use during the development process.'),
  ('SA-15(3)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Criticality Analysis', 'Require the developer of the system, system component, or system service to perform a criticality analysis:
  (a) At the following decision points in the system development life cycle: [Assignment: organization-defined decision points] ; and
  (b) At the following level of rigor: [Assignment: organization-defined breadth and depth of criticality analysis].'),
  ('SA-15(5)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Attack Surface Reduction', 'Require the developer of the system, system component, or system service to reduce attack surfaces to [Assignment: organization-defined thresholds].'),
  ('SA-15(6)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Continuous Improvement', 'Require the developer of the system, system component, or system service to implement an explicit process to continuously improve the development process.'),
  ('SA-15(7)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Automated Vulnerability Analysis', 'Require the developer of the system, system component, or system service [Assignment: organization-defined frequency] to:
  (a) Perform an automated vulnerability analysis using [Assignment: organization-defined tools];
  (b) Determine the exploitation potential for discovered vulnerabilities;
  (c) Determine potential risk mitigations for delivered vulnerabilities; and
  (d) Deliver the outputs of the tools and results of the analysis to [Assignment: organization-defined personnel or roles].'),
  ('SA-15(8)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Reuse of Threat and Vulnerability Information', 'Require the developer of the system, system component, or system service to use threat modeling and vulnerability analyses from similar systems, components, or services to inform the current development process.'),
  ('SA-15(10)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Incident Response Plan', 'Require the developer of the system, system component, or system service to provide, implement, and test an incident response plan.'),
  ('SA-15(11)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Archive System or Component', 'Require the developer of the system or system component to archive the system or component to be released or delivered together with the corresponding evidence supporting the final security and privacy review.'),
  ('SA-15(12)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Minimize Personally Identifiable Information', 'Require the developer of the system or system component to minimize the use of personally identifiable information in development and test environments.'),
  ('SA-15(13)', 'NIST-800-53', 'System and Services Acquisition', 'Development Process, Standards, and Tools | Logging Syntax', 'Require the developer of the system, system component, or system service to use [Assignment: organization-defined secure logging format(s)] to log [Assignment: organization-defined events types to log] at [Assignment: organization-defined level of detail to log].'),
  ('SA-16', 'NIST-800-53', 'System and Services Acquisition', 'Developer-provided Training', 'Require the developer of the system, system component, or system service to provide the following training on the correct use and operation of the implemented security and privacy functions, controls, and/or mechanisms: [Assignment: organization-defined training].'),
  ('SA-17', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design', 'Require the developer of the system, system component, or system service to produce a design specification and security and privacy architecture that:
  a. Is consistent with the organization’s security and privacy architecture that is an integral part the organization’s enterprise architecture;
  b. Accurately and completely describes the required security and privacy functionality, and the allocation of controls among physical and logical components; and
  c. Expresses how individual security and privacy functions, mechanisms, and services work together to provide required security and privacy capabilities and a unified approach to protection.'),
  ('SA-17(1)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design | Formal Policy Model', 'Require the developer of the system, system component, or system service to:
  (a) Produce, as an integral part of the development process, a formal policy model describing the [Assignment: organization-defined elements of organizational security and privacy policy] to be enforced; and
  (b) Prove that the formal policy model is internally consistent and sufficient to enforce the defined elements of the organizational security and privacy policy when implemented.'),
  ('SA-17(2)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design | Security-relevant Components', 'Require the developer of the system, system component, or system service to:
  (a) Define security-relevant hardware, software, and firmware; and
  (b) Provide a rationale that the definition for security-relevant hardware, software, and firmware is complete.'),
  ('SA-17(3)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design | Formal Correspondence', 'Require the developer of the system, system component, or system service to:
  (a) Produce, as an integral part of the development process, a formal top-level specification that specifies the interfaces to security-relevant hardware, software, and firmware in terms of exceptions, error messages, and effects;
  (b) Show via proof to the extent feasible with additional informal demonstration as necessary, that the formal top-level specification is consistent with the formal policy model;
  (c) Show via informal demonstration, that the formal top-level specification completely covers the interfaces to security-relevant hardware, software, and firmware;
  (d) Show that the formal top-level specification is an accurate description of the implemented security-relevant hardware, software, and firmware; and
  (e) Describe the security-relevant hardware, software, and firmware mechanisms not addressed in the formal top-level specification but strictly internal to the security-relevant hardware, software, and firmware.'),
  ('SA-17(4)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design | Informal Correspondence', 'Require the developer of the system, system component, or system service to:
  (a) Produce, as an integral part of the development process, an informal descriptive top-level specification that specifies the interfaces to security-relevant hardware, software, and firmware in terms of exceptions, error messages, and effects;
  (b) Show via [Selection: informal demonstration, convincing argument with formal methods as feasible] that the descriptive top-level specification is consistent with the formal policy model;
  (c) Show via informal demonstration, that the descriptive top-level specification completely covers the interfaces to security-relevant hardware, software, and firmware;
  (d) Show that the descriptive top-level specification is an accurate description of the interfaces to security-relevant hardware, software, and firmware; and
  (e) Describe the security-relevant hardware, software, and firmware mechanisms not addressed in the descriptive top-level specification but strictly internal to the security-relevant hardware, software, and firmware.'),
  ('SA-17(5)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design | Conceptually Simple Design', 'Require the developer of the system, system component, or system service to:
  (a) Design and structure the security-relevant hardware, software, and firmware to use a complete, conceptually simple protection mechanism with precisely defined semantics; and
  (b) Internally structure the security-relevant hardware, software, and firmware with specific regard for this mechanism.'),
  ('SA-17(6)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design | Structure for Testing', 'Require the developer of the system, system component, or system service to structure security-relevant hardware, software, and firmware to facilitate testing.'),
  ('SA-17(7)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design | Structure for Least Privilege', 'Require the developer of the system, system component, or system service to structure security-relevant hardware, software, and firmware to facilitate controlling access with least privilege.'),
  ('SA-17(8)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design | Orchestration', 'Design [Assignment: organization-defined critical systems] with coordinated behavior to implement the following capabilities: [Assignment: organization-defined capabilities].'),
  ('SA-17(9)', 'NIST-800-53', 'System and Services Acquisition', 'Developer Security and Privacy Architecture and Design | Design Diversity', 'Use different designs for [Assignment: organization-defined critical systems] to satisfy a common set of requirements or to provide equivalent functionality.'),
  ('SA-20', 'NIST-800-53', 'System and Services Acquisition', 'Customized Development of Critical Components', 'Reimplement or custom develop the following critical system components: [Assignment: organization-defined critical system].'),
  ('SA-21', 'NIST-800-53', 'System and Services Acquisition', 'Developer Screening', 'Require that the developer of [Assignment: organization-defined system, systems component, or system service]:
  a. Has appropriate access authorizations as determined by assigned [Assignment: organization-defined official government duties] ; and
  b. Satisfies the following additional personnel screening criteria: [Assignment: organization-defined additional personnel screening criteria].'),
  ('SA-22', 'NIST-800-53', 'System and Services Acquisition', 'Unsupported System Components', 'a. Replace system components when support for the components is no longer available from the developer, vendor, or manufacturer; or
b. Provide the following options for alternative sources for continued support for unsupported components [Selection (one or more): in-house support; [Assignment: organization-defined support from external providers] ].'),
  ('SA-23', 'NIST-800-53', 'System and Services Acquisition', 'Specialization', 'Employ [Selection (one or more): design modification; augmentation; reconfiguration] on [Assignment: organization-defined systems or system components] supporting mission essential services or functions to increase the trustworthiness in those systems or components.'),
  ('SA-24', 'NIST-800-53', 'System and Services Acquisition', 'Design For Cyber Resiliency', 'a. Design organizational systems, system components, or system services to achieve cyber resiliency by:
  1. Defining the following cyber resiliency goals: [Assignment: organization-defined cyber resiliency goals].
  2. Defining the following cyber resiliency objectives: [Assignment: organization-defined cyber resiliency objectives].
  3. Defining the following cyber resiliency techniques: [Assignment: organization-defined cyber resiliency techniques].
  4. Defining the following cyber resiliency implementation approaches: [Assignment: organization-defined cyber resiliency implementation approaches].
  5. Defining the following cyber resiliency design principles: [Assignment: organization-defined cyber resiliency design principles].
b. Implement the selected cyber resiliency goals, objectives, techniques, implementation approaches, and design principles as part of an organizational risk management process or systems security engineering process.'),
  ('SC-1', 'NIST-800-53', 'System and Communications Protection', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the system and communications protection policy and the associated system and communications protection controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and communications protection policy and procedures; and
c. Review and update the current system and communications protection:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('SC-2', 'NIST-800-53', 'System and Communications Protection', 'Separation of System and User Functionality', 'Separate user functionality, including user interface services, from system management functionality.'),
  ('SC-2(1)', 'NIST-800-53', 'System and Communications Protection', 'Separation of System and User Functionality | Interfaces for Non-privileged Users', 'Prevent the presentation of system management functionality at interfaces to non-privileged users.'),
  ('SC-2(2)', 'NIST-800-53', 'System and Communications Protection', 'Separation of System and User Functionality | Disassociability', 'Store state information from applications and software separately.'),
  ('SC-3', 'NIST-800-53', 'System and Communications Protection', 'Security Function Isolation', 'Isolate security functions from nonsecurity functions.'),
  ('SC-3(1)', 'NIST-800-53', 'System and Communications Protection', 'Security Function Isolation | Hardware Separation', 'Employ hardware separation mechanisms to implement security function isolation.'),
  ('SC-3(2)', 'NIST-800-53', 'System and Communications Protection', 'Security Function Isolation | Access and Flow Control Functions', 'Isolate security functions enforcing access and information flow control from nonsecurity functions and from other security functions.'),
  ('SC-3(3)', 'NIST-800-53', 'System and Communications Protection', 'Security Function Isolation | Minimize Nonsecurity Functionality', 'Minimize the number of nonsecurity functions included within the isolation boundary containing security functions.'),
  ('SC-3(4)', 'NIST-800-53', 'System and Communications Protection', 'Security Function Isolation | Module Coupling and Cohesiveness', 'Implement security functions as largely independent modules that maximize internal cohesiveness within modules and minimize coupling between modules.'),
  ('SC-3(5)', 'NIST-800-53', 'System and Communications Protection', 'Security Function Isolation | Layered Structures', 'Implement security functions as a layered structure minimizing interactions between layers of the design and avoiding any dependence by lower layers on the functionality or correctness of higher layers.'),
  ('SC-4', 'NIST-800-53', 'System and Communications Protection', 'Information in Shared System Resources', 'Prevent unauthorized and unintended information transfer via shared system resources.'),
  ('SC-4(2)', 'NIST-800-53', 'System and Communications Protection', 'Information in Shared System Resources | Multilevel or Periods Processing', 'Prevent unauthorized information transfer via shared resources in accordance with [Assignment: organization-defined procedures] when system processing explicitly switches between different information classification levels or security categories.'),
  ('SC-5', 'NIST-800-53', 'System and Communications Protection', 'Denial-of-service Protection', 'a. [Selection: protect against; limit] the effects of the following types of denial-of-service events: [Assignment: organization-defined types of denial-of-service events] ; and
b. Employ the following controls to achieve the denial-of-service objective: [Assignment: organization-defined controls by type of denial-of-service event].'),
  ('SC-5(1)', 'NIST-800-53', 'System and Communications Protection', 'Denial-of-service Protection | Restrict Ability to Attack Other Systems', 'Restrict the ability of individuals to launch the following denial-of-service attacks against other systems: [Assignment: organization-defined denial-of-service attacks].'),
  ('SC-5(2)', 'NIST-800-53', 'System and Communications Protection', 'Denial-of-service Protection | Capacity, Bandwidth, and Redundancy', 'Manage capacity, bandwidth, or other redundancy to limit the effects of information flooding denial-of-service attacks.'),
  ('SC-5(3)', 'NIST-800-53', 'System and Communications Protection', 'Denial-of-service Protection | Detection and Monitoring', '(a) Employ the following monitoring tools to detect indicators of denial-of-service attacks against, or launched from, the system: [Assignment: organization-defined monitoring tools] ; and
(b) Monitor the following system resources to determine if sufficient resources exist to prevent effective denial-of-service attacks: [Assignment: organization-defined system resources].'),
  ('SC-6', 'NIST-800-53', 'System and Communications Protection', 'Resource Availability', 'Protect the availability of resources by allocating [Assignment: organization-defined resources] by [Selection (one or more): priority; quota; [Assignment: organization-defined controls] ].'),
  ('SC-7', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection', 'a. Monitor and control communications at the external managed interfaces to the system and at key internal managed interfaces within the system;
b. Implement subnetworks for publicly accessible system components that are [Selection: physically; logically] separated from internal organizational networks; and
c. Connect to external networks or systems only through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security and privacy architecture.'),
  ('SC-7(3)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Access Points', 'Limit the number of external network connections to the system.'),
  ('SC-7(4)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | External Telecommunications Services', '(a) Implement a managed interface for each external telecommunication service;
(b) Establish a traffic flow policy for each managed interface;
(c) Protect the confidentiality and integrity of the information being transmitted across each interface;
(d) Document each exception to the traffic flow policy with a supporting mission or business need and duration of that need;
(e) Review exceptions to the traffic flow policy [Assignment: organization-defined frequency] and remove exceptions that are no longer supported by an explicit mission or business need;
(f) Prevent unauthorized exchange of control plane traffic with external networks;
(g) Publish information to enable remote networks to detect unauthorized control plane traffic from internal networks; and
(h) Filter unauthorized control plane traffic from external networks.'),
  ('SC-7(5)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Deny by Default — Allow by Exception', 'Deny network communications traffic by default and allow network communications traffic by exception [Selection (one or more): at managed interfaces; for [Assignment: organization-defined systems] ].'),
  ('SC-7(7)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Split Tunneling for Remote Devices', 'Prevent split tunneling for remote devices connecting to organizational systems unless the split tunnel is securely provisioned using [Assignment: organization-defined safeguards].'),
  ('SC-7(8)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Route Traffic to Authenticated Proxy Servers', 'Route [Assignment: organization-defined internal communications traffic] to [Assignment: organization-defined external networks] through authenticated proxy servers at managed interfaces.'),
  ('SC-7(9)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Restrict Threatening Outgoing Communications Traffic', '(a) Detect and deny outgoing communications traffic posing a threat to external systems; and
(b) Audit the identity of internal users associated with denied communications.'),
  ('SC-7(10)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Prevent Exfiltration', '(a) Prevent the exfiltration of information; and
(b) Conduct exfiltration tests [Assignment: organization-defined frequency].'),
  ('SC-7(11)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Restrict Incoming Communications Traffic', 'Only allow incoming communications from [Assignment: organization-defined authorized sources] to be routed to [Assignment: organization-defined authorized destinations].'),
  ('SC-7(12)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Host-based Protection', 'Implement [Assignment: organization-defined host-based boundary protection mechanisms] at [Assignment: organization-defined system components].'),
  ('SC-7(13)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Isolation of Security Tools, Mechanisms, and Support Components', 'Isolate [Assignment: organization-defined information security tools, mechanisms, and support components] from other internal system components by implementing physically separate subnetworks with managed interfaces to other components of the system.'),
  ('SC-7(14)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Protect Against Unauthorized Physical Connections', 'Protect against unauthorized physical connections at [Assignment: organization-defined managed interfaces].'),
  ('SC-7(15)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Networked Privileged Accesses', 'Route networked, privileged accesses through a dedicated, managed interface for purposes of access control and auditing.'),
  ('SC-7(16)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Prevent Discovery of System Components', 'Prevent the discovery of specific system components that represent a managed interface.'),
  ('SC-7(17)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Automated Enforcement of Protocol Formats', 'Enforce adherence to protocol formats.'),
  ('SC-7(18)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Fail Secure', 'Prevent systems from entering unsecure states in the event of an operational failure of a boundary protection device.'),
  ('SC-7(19)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Block Communication from Non-organizationally Configured Hosts', 'Block inbound and outbound communications traffic between [Assignment: organization-defined communication clients] that are independently configured by end users and external service providers.'),
  ('SC-7(20)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Dynamic Isolation and Segregation', 'Provide the capability to dynamically isolate [Assignment: organization-defined system components] from other system components.'),
  ('SC-7(21)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Isolation of System Components', 'Employ boundary protection mechanisms to isolate [Assignment: organization-defined system components] supporting [Assignment: organization-defined missions and/or business functions].'),
  ('SC-7(22)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Separate Subnets for Connecting to Different Security Domains', 'Implement separate network addresses to connect to systems in different security domains.'),
  ('SC-7(23)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Disable Sender Feedback on Protocol Validation Failure', 'Disable feedback to senders on protocol format validation failure.'),
  ('SC-7(24)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Personally Identifiable Information', 'For systems that process personally identifiable information:
  (a) Apply the following processing rules to data elements of personally identifiable information: [Assignment: organization-defined processing rules];
  (b) Monitor for permitted processing at the external interfaces to the system and at key internal boundaries within the system;
  (c) Document each processing exception; and
  (d) Review and remove exceptions that are no longer supported.'),
  ('SC-7(25)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Unclassified National Security System Connections', 'Prohibit the direct connection of [Assignment: organization-defined unclassified national security system] to an external network without the use of [Assignment: organization-defined boundary protection device].'),
  ('SC-7(26)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Classified National Security System Connections', 'Prohibit the direct connection of a classified national security system to an external network without the use of [Assignment: organization-defined boundary protection device].'),
  ('SC-7(27)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Unclassified Non-national Security System Connections', 'Prohibit the direct connection of [Assignment: organization-defined unclassified, non-national security system] to an external network without the use of [Assignment: organization-defined boundary protection device].'),
  ('SC-7(28)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Connections to Public Networks', 'Prohibit the direct connection of [Assignment: organization-defined system] to a public network.'),
  ('SC-7(29)', 'NIST-800-53', 'System and Communications Protection', 'Boundary Protection | Separate Subnets to Isolate Functions', 'Implement [Selection: physically; logically] separate subnetworks to isolate the following critical system components and functions: [Assignment: organization-defined critical system components and functions].'),
  ('SC-8', 'NIST-800-53', 'System and Communications Protection', 'Transmission Confidentiality and Integrity', 'Protect the [Selection (one or more): confidentiality; integrity] of transmitted information.'),
  ('SC-8(1)', 'NIST-800-53', 'System and Communications Protection', 'Transmission Confidentiality and Integrity | Cryptographic Protection', 'Implement cryptographic mechanisms to [Selection (one or more): prevent unauthorized disclosure of information; detect changes to information] during transmission.'),
  ('SC-8(2)', 'NIST-800-53', 'System and Communications Protection', 'Transmission Confidentiality and Integrity | Pre- and Post-transmission Handling', 'Maintain the [Selection (one or more): confidentiality; integrity] of information during preparation for transmission and during reception.'),
  ('SC-8(3)', 'NIST-800-53', 'System and Communications Protection', 'Transmission Confidentiality and Integrity | Cryptographic Protection for Message Externals', 'Implement cryptographic mechanisms to protect message externals unless otherwise protected by [Assignment: organization-defined alternative physical controls].'),
  ('SC-8(4)', 'NIST-800-53', 'System and Communications Protection', 'Transmission Confidentiality and Integrity | Conceal or Randomize Communications', 'Implement cryptographic mechanisms to conceal or randomize communication patterns unless otherwise protected by [Assignment: organization-defined alternative physical controls].'),
  ('SC-8(5)', 'NIST-800-53', 'System and Communications Protection', 'Transmission Confidentiality and Integrity | Protected Distribution System', 'Implement [Assignment: organization-defined protected distribution system] to [Selection (one or more): prevent unauthorized disclosure of information; detect changes to information] during transmission.'),
  ('SC-10', 'NIST-800-53', 'System and Communications Protection', 'Network Disconnect', 'Terminate the network connection associated with a communications session at the end of the session or after [Assignment: organization-defined time period] of inactivity.'),
  ('SC-11', 'NIST-800-53', 'System and Communications Protection', 'Trusted Path', 'a. Provide a [Selection: physically; logically] isolated trusted communications path for communications between the user and the trusted components of the system; and
b. Permit users to invoke the trusted communications path for communications between the user and the following security functions of the system, including at a minimum, authentication and re-authentication: [Assignment: organization-defined security functions].'),
  ('SC-11(1)', 'NIST-800-53', 'System and Communications Protection', 'Trusted Path | Irrefutable Communications Path', '(a) Provide a trusted communications path that is irrefutably distinguishable from other communications paths; and
(b) Initiate the trusted communications path for communications between the [Assignment: organization-defined security functions] of the system and the user.'),
  ('SC-12', 'NIST-800-53', 'System and Communications Protection', 'Cryptographic Key Establishment and Management', 'Establish and manage cryptographic keys when cryptography is employed within the system in accordance with the following key management requirements: [Assignment: organization-defined requirements].')
ON CONFLICT (control_id) DO UPDATE
  SET family = EXCLUDED.family, title = EXCLUDED.title, description = EXCLUDED.description
  WHERE compliance_controls.framework = 'NIST-800-53';

INSERT INTO compliance_controls (control_id, framework, family, title, description) VALUES
  ('SC-12(1)', 'NIST-800-53', 'System and Communications Protection', 'Cryptographic Key Establishment and Management | Availability', 'Maintain availability of information in the event of the loss of cryptographic keys by users.'),
  ('SC-12(2)', 'NIST-800-53', 'System and Communications Protection', 'Cryptographic Key Establishment and Management | Symmetric Keys', 'Produce, control, and distribute symmetric cryptographic keys using [Selection: NIST FIPS-validated; NSA-approved] key management technology and processes.'),
  ('SC-12(3)', 'NIST-800-53', 'System and Communications Protection', 'Cryptographic Key Establishment and Management | Asymmetric Keys', 'Produce, control, and distribute asymmetric cryptographic keys using [Selection: NSA-approved key management technology and processes; prepositioned keying material; DoD-approved or DoD-issued Medium Assurance PKI certificates; DoD-approved or DoD-issued Medium Hardware Assurance PKI certificates and hardware security tokens that protect the user’s private key; certificates issued in accordance with organization-defined requirements].'),
  ('SC-12(6)', 'NIST-800-53', 'System and Communications Protection', 'Cryptographic Key Establishment and Management | Physical Control of Keys', 'Maintain physical control of cryptographic keys when stored information is encrypted by external service providers.'),
  ('SC-13', 'NIST-800-53', 'System and Communications Protection', 'Cryptographic Protection', 'a. Determine the [Assignment: organization-defined cryptographic uses] ; and
b. Implement the following types of cryptography required for each specified cryptographic use: [Assignment: organization-defined types of cryptography].'),
  ('SC-15', 'NIST-800-53', 'System and Communications Protection', 'Collaborative Computing Devices and Applications', 'a. Prohibit remote activation of collaborative computing devices and applications with the following exceptions: [Assignment: organization-defined exceptions where remote activation is to be allowed] ; and
b. Provide an explicit indication of use to users physically present at the devices.'),
  ('SC-15(1)', 'NIST-800-53', 'System and Communications Protection', 'Collaborative Computing Devices and Applications | Physical or Logical Disconnect', 'Provide [Selection (one or more): physical; logical] disconnect of collaborative computing devices in a manner that supports ease of use.'),
  ('SC-15(3)', 'NIST-800-53', 'System and Communications Protection', 'Collaborative Computing Devices and Applications | Disabling and Removal in Secure Work Areas', 'Disable or remove collaborative computing devices and applications from [Assignment: organization-defined systems or system components] in [Assignment: organization-defined secure work areas].'),
  ('SC-15(4)', 'NIST-800-53', 'System and Communications Protection', 'Collaborative Computing Devices and Applications | Explicitly Indicate Current Participants', 'Provide an explicit indication of current participants in [Assignment: organization-defined online meetings and teleconferences].'),
  ('SC-16', 'NIST-800-53', 'System and Communications Protection', 'Transmission of Security and Privacy Attributes', 'Associate [Assignment: organization-defined security and privacy attributes] with information exchanged between systems and between system components.'),
  ('SC-16(1)', 'NIST-800-53', 'System and Communications Protection', 'Transmission of Security and Privacy Attributes | Integrity Verification', 'Verify the integrity of transmitted security and privacy attributes.'),
  ('SC-16(2)', 'NIST-800-53', 'System and Communications Protection', 'Transmission of Security and Privacy Attributes | Anti-spoofing Mechanisms', 'Implement anti-spoofing mechanisms to prevent adversaries from falsifying the security attributes indicating the successful application of the security process.'),
  ('SC-16(3)', 'NIST-800-53', 'System and Communications Protection', 'Transmission of Security and Privacy Attributes | Cryptographic Binding', 'Implement [Assignment: organization-defined mechanisms or techniques] to bind security and privacy attributes to transmitted information.'),
  ('SC-17', 'NIST-800-53', 'System and Communications Protection', 'Public Key Infrastructure Certificates', 'a. Issue public key certificates under an [Assignment: organization-defined certificate policy] or obtain public key certificates from an approved service provider; and
b. Include only approved trust anchors in trust stores or certificate stores managed by the organization.'),
  ('SC-18', 'NIST-800-53', 'System and Communications Protection', 'Mobile Code', 'a. Define acceptable and unacceptable mobile code and mobile code technologies; and
b. Authorize, monitor, and control the use of mobile code within the system.'),
  ('SC-18(1)', 'NIST-800-53', 'System and Communications Protection', 'Mobile Code | Identify Unacceptable Code and Take Corrective Actions', 'Identify [Assignment: organization-defined unacceptable mobile code] and take [Assignment: organization-defined corrective actions].'),
  ('SC-18(2)', 'NIST-800-53', 'System and Communications Protection', 'Mobile Code | Acquisition, Development, and Use', 'Verify that the acquisition, development, and use of mobile code to be deployed in the system meets [Assignment: organization-defined mobile code requirements].'),
  ('SC-18(3)', 'NIST-800-53', 'System and Communications Protection', 'Mobile Code | Prevent Downloading and Execution', 'Prevent the download and execution of [Assignment: organization-defined unacceptable mobile code].'),
  ('SC-18(4)', 'NIST-800-53', 'System and Communications Protection', 'Mobile Code | Prevent Automatic Execution', 'Prevent the automatic execution of mobile code in [Assignment: organization-defined software applications] and enforce [Assignment: organization-defined actions] prior to executing the code.'),
  ('SC-18(5)', 'NIST-800-53', 'System and Communications Protection', 'Mobile Code | Allow Execution Only in Confined Environments', 'Allow execution of permitted mobile code only in confined virtual machine environments.'),
  ('SC-20', 'NIST-800-53', 'System and Communications Protection', 'Secure Name/Address Resolution Service (Authoritative Source)', 'a. Provide additional data origin authentication and integrity verification artifacts along with the authoritative name resolution data the system returns in response to external name/address resolution queries; and
b. Provide the means to indicate the security status of child zones and (if the child supports secure resolution services) to enable verification of a chain of trust among parent and child domains, when operating as part of a distributed, hierarchical namespace.'),
  ('SC-20(2)', 'NIST-800-53', 'System and Communications Protection', 'Secure Name/Address Resolution Service (Authoritative Source) | Data Origin and Integrity', 'Provide data origin and integrity protection artifacts for internal name/address resolution queries.'),
  ('SC-21', 'NIST-800-53', 'System and Communications Protection', 'Secure Name/Address Resolution Service (Recursive or Caching Resolver)', 'Request and perform data origin authentication and data integrity verification on the name/address resolution responses the system receives from authoritative sources.'),
  ('SC-22', 'NIST-800-53', 'System and Communications Protection', 'Architecture and Provisioning for Name/Address Resolution Service', 'Ensure the systems that collectively provide name/address resolution service for an organization are fault-tolerant and implement internal and external role separation.'),
  ('SC-23', 'NIST-800-53', 'System and Communications Protection', 'Session Authenticity', 'Protect the authenticity of communications sessions.'),
  ('SC-23(1)', 'NIST-800-53', 'System and Communications Protection', 'Session Authenticity | Invalidate Session Identifiers at Logout', 'Invalidate session identifiers upon user logout or other session termination.'),
  ('SC-23(3)', 'NIST-800-53', 'System and Communications Protection', 'Session Authenticity | Unique System-generated Session Identifiers', 'Generate a unique session identifier for each session with [Assignment: organization-defined randomness requirements] and recognize only session identifiers that are system-generated.'),
  ('SC-23(5)', 'NIST-800-53', 'System and Communications Protection', 'Session Authenticity | Allowed Certificate Authorities', 'Only allow the use of [Assignment: organization-defined certificated authorities] for verification of the establishment of protected sessions.'),
  ('SC-24', 'NIST-800-53', 'System and Communications Protection', 'Fail in Known State', 'Fail to a [Assignment: organization-defined known system state] for the following failures on the indicated components while preserving [Assignment: organization-defined system state information] in failure: [Assignment: organization-defined types of system failures on system components].'),
  ('SC-25', 'NIST-800-53', 'System and Communications Protection', 'Thin Nodes', 'Employ minimal functionality and information storage on the following system components: [Assignment: organization-defined system components].'),
  ('SC-26', 'NIST-800-53', 'System and Communications Protection', 'Decoys', 'Include components within organizational systems specifically designed to be the target of malicious attacks for detecting, deflecting, and analyzing such attacks.'),
  ('SC-27', 'NIST-800-53', 'System and Communications Protection', 'Platform-independent Applications', 'Include within organizational systems the following platform independent applications: [Assignment: organization-defined platform-independent applications].'),
  ('SC-28', 'NIST-800-53', 'System and Communications Protection', 'Protection of Information at Rest', 'Protect the [Selection (one or more): confidentiality; integrity] of the following information at rest: [Assignment: organization-defined information at rest].'),
  ('SC-28(1)', 'NIST-800-53', 'System and Communications Protection', 'Protection of Information at Rest | Cryptographic Protection', 'Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of the following information at rest on [Assignment: organization-defined system components or media]: [Assignment: organization-defined information].'),
  ('SC-28(2)', 'NIST-800-53', 'System and Communications Protection', 'Protection of Information at Rest | Offline Storage', 'Remove the following information from online storage and store offline in a secure location: [Assignment: organization-defined information].'),
  ('SC-28(3)', 'NIST-800-53', 'System and Communications Protection', 'Protection of Information at Rest | Cryptographic Keys', 'Provide protected storage for cryptographic keys [Selection: [Assignment: organization-defined safeguards] ; hardware-protected key store].'),
  ('SC-29', 'NIST-800-53', 'System and Communications Protection', 'Heterogeneity', 'Employ a diverse set of information technologies for the following system components in the implementation of the system: [Assignment: organization-defined system components].'),
  ('SC-29(1)', 'NIST-800-53', 'System and Communications Protection', 'Heterogeneity | Virtualization Techniques', 'Employ virtualization techniques to support the deployment of a diversity of operating systems and applications that are changed [Assignment: organization-defined frequency].'),
  ('SC-30', 'NIST-800-53', 'System and Communications Protection', 'Concealment and Misdirection', 'Employ the following concealment and misdirection techniques for [Assignment: organization-defined systems] at [Assignment: organization-defined time periods] to confuse and mislead adversaries: [Assignment: organization-defined concealment and misdirection techniques].'),
  ('SC-30(2)', 'NIST-800-53', 'System and Communications Protection', 'Concealment and Misdirection | Randomness', 'Employ [Assignment: organization-defined techniques] to introduce randomness into organizational operations and assets.'),
  ('SC-30(3)', 'NIST-800-53', 'System and Communications Protection', 'Concealment and Misdirection | Change Processing and Storage Locations', 'Change the location of [Assignment: organization-defined processing and/or storage] [Selection: [Assignment: organization-defined time frequency] ; random time intervals]].'),
  ('SC-30(4)', 'NIST-800-53', 'System and Communications Protection', 'Concealment and Misdirection | Misleading Information', 'Employ realistic, but misleading information in [Assignment: organization-defined system components] about its security state or posture.'),
  ('SC-30(5)', 'NIST-800-53', 'System and Communications Protection', 'Concealment and Misdirection | Concealment of System Components', 'Employ the following techniques to hide or conceal [Assignment: organization-defined system components]: [Assignment: organization-defined techniques].'),
  ('SC-31', 'NIST-800-53', 'System and Communications Protection', 'Covert Channel Analysis', 'a. Perform a covert channel analysis to identify those aspects of communications within the system that are potential avenues for covert [Selection (one or more): storage; timing] channels; and
b. Estimate the maximum bandwidth of those channels.'),
  ('SC-31(1)', 'NIST-800-53', 'System and Communications Protection', 'Covert Channel Analysis | Test Covert Channels for Exploitability', 'Test a subset of the identified covert channels to determine the channels that are exploitable.'),
  ('SC-31(2)', 'NIST-800-53', 'System and Communications Protection', 'Covert Channel Analysis | Maximum Bandwidth', 'Reduce the maximum bandwidth for identified covert [Selection (one or more): storage; timing] channels to [Assignment: organization-defined values].'),
  ('SC-31(3)', 'NIST-800-53', 'System and Communications Protection', 'Covert Channel Analysis | Measure Bandwidth in Operational Environments', 'Measure the bandwidth of [Assignment: organization-defined subset of identified covert channels] in the operational environment of the system.'),
  ('SC-32', 'NIST-800-53', 'System and Communications Protection', 'System Partitioning', 'Partition the system into [Assignment: organization-defined system components] residing in separate [Selection: physical; logical] domains or environments based on [Assignment: organization-defined circumstances for the physical or logical separation of components].'),
  ('SC-32(1)', 'NIST-800-53', 'System and Communications Protection', 'System Partitioning | Separate Physical Domains for Privileged Functions', 'Partition privileged functions into separate physical domains.'),
  ('SC-34', 'NIST-800-53', 'System and Communications Protection', 'Non-modifiable Executable Programs', 'For [Assignment: organization-defined system components] , load and execute:
  a. The operating environment from hardware-enforced, read-only media; and
  b. The following applications from hardware-enforced, read-only media: [Assignment: organization-defined applications].'),
  ('SC-34(1)', 'NIST-800-53', 'System and Communications Protection', 'Non-modifiable Executable Programs | No Writable Storage', 'Employ [Assignment: organization-defined system components] with no writeable storage that is persistent across component restart or power on/off.'),
  ('SC-34(2)', 'NIST-800-53', 'System and Communications Protection', 'Non-modifiable Executable Programs | Integrity Protection on Read-only Media', 'Protect the integrity of information prior to storage on read-only media and control the media after such information has been recorded onto the media.'),
  ('SC-35', 'NIST-800-53', 'System and Communications Protection', 'External Malicious Code Identification', 'Include system components that proactively seek to identify network-based malicious code or malicious websites.'),
  ('SC-36', 'NIST-800-53', 'System and Communications Protection', 'Distributed Processing and Storage', 'Distribute the following processing and storage components across multiple [Selection: physical locations; logical domains]: [Assignment: organization-defined processing and storage components].'),
  ('SC-36(1)', 'NIST-800-53', 'System and Communications Protection', 'Distributed Processing and Storage | Polling Techniques', '(a) Employ polling techniques to identify potential faults, errors, or compromises to the following processing and storage components: [Assignment: organization-defined distributed processing and storage components] ; and
(b) Take the following actions in response to identified faults, errors, or compromises: [Assignment: organization-defined actions].'),
  ('SC-36(2)', 'NIST-800-53', 'System and Communications Protection', 'Distributed Processing and Storage | Synchronization', 'Synchronize the following duplicate systems or system components: [Assignment: organization-defined duplicate systems or system components].'),
  ('SC-37', 'NIST-800-53', 'System and Communications Protection', 'Out-of-band Channels', 'Employ the following out-of-band channels for the physical delivery or electronic transmission of [Assignment: organization-defined information, system components, or devices] to [Assignment: organization-defined individuals or systems]: [Assignment: organization-defined out-of-band channels].'),
  ('SC-37(1)', 'NIST-800-53', 'System and Communications Protection', 'Out-of-band Channels | Ensure Delivery and Transmission', 'Employ [Assignment: organization-defined controls] to ensure that only [Assignment: organization-defined individuals or systems] receive the following information, system components, or devices: [Assignment: organization-defined information, system components, or devices].'),
  ('SC-38', 'NIST-800-53', 'System and Communications Protection', 'Operations Security', 'Employ the following operations security controls to protect key organizational information throughout the system development life cycle: [Assignment: organization-defined operations security controls].'),
  ('SC-39', 'NIST-800-53', 'System and Communications Protection', 'Process Isolation', 'Maintain a separate execution domain for each executing system process.'),
  ('SC-39(1)', 'NIST-800-53', 'System and Communications Protection', 'Process Isolation | Hardware Separation', 'Implement hardware separation mechanisms to facilitate process isolation.'),
  ('SC-39(2)', 'NIST-800-53', 'System and Communications Protection', 'Process Isolation | Separate Execution Domain Per Thread', 'Maintain a separate execution domain for each thread in [Assignment: organization-defined multi-threaded processing].'),
  ('SC-40', 'NIST-800-53', 'System and Communications Protection', 'Wireless Link Protection', 'Protect external and internal [Assignment: organization-defined wireless links] from the following signal parameter attacks: [Assignment: organization-defined types of signal parameter attacks or references to sources for such attacks].'),
  ('SC-40(1)', 'NIST-800-53', 'System and Communications Protection', 'Wireless Link Protection | Electromagnetic Interference', 'Implement cryptographic mechanisms that achieve [Assignment: organization-defined level of protection] against the effects of intentional electromagnetic interference.'),
  ('SC-40(2)', 'NIST-800-53', 'System and Communications Protection', 'Wireless Link Protection | Reduce Detection Potential', 'Implement cryptographic mechanisms to reduce the detection potential of wireless links to [Assignment: organization-defined level of reduction].'),
  ('SC-40(3)', 'NIST-800-53', 'System and Communications Protection', 'Wireless Link Protection | Imitative or Manipulative Communications Deception', 'Implement cryptographic mechanisms to identify and reject wireless transmissions that are deliberate attempts to achieve imitative or manipulative communications deception based on signal parameters.'),
  ('SC-40(4)', 'NIST-800-53', 'System and Communications Protection', 'Wireless Link Protection | Signal Parameter Identification', 'Implement cryptographic mechanisms to prevent the identification of [Assignment: organization-defined wireless transmitters] by using the transmitter signal parameters.'),
  ('SC-41', 'NIST-800-53', 'System and Communications Protection', 'Port and I/O Device Access', '[Selection: physically; logically] disable or remove [Assignment: organization-defined connection ports or input/output devices] on the following systems or system components: [Assignment: organization-defined systems or system components].'),
  ('SC-42', 'NIST-800-53', 'System and Communications Protection', 'Sensor Capability and Data', 'a. Prohibit [Selection (one or more): the use of devices possessing [Assignment: organization-defined environmental sensing capabilities] in [Assignment: organization-defined facilities, areas, or systems] ; the remote activation of environmental sensing capabilities on organizational systems or system components with the following exceptions: [Assignment: organization-defined exceptions where remote activation of sensors is allowed] ] ; and
b. Provide an explicit indication of sensor use to [Assignment: organization-defined group of users].'),
  ('SC-42(1)', 'NIST-800-53', 'System and Communications Protection', 'Sensor Capability and Data | Reporting to Authorized Individuals or Roles', 'Verify that the system is configured so that data or information collected by the [Assignment: organization-defined sensors] is only reported to authorized individuals or roles.'),
  ('SC-42(2)', 'NIST-800-53', 'System and Communications Protection', 'Sensor Capability and Data | Authorized Use', 'Employ the following measures so that data or information collected by [Assignment: organization-defined value] is only used for authorized purposes: [Assignment: organization-defined measures].'),
  ('SC-42(4)', 'NIST-800-53', 'System and Communications Protection', 'Sensor Capability and Data | Notice of Collection', 'Employ the following measures to facilitate an individual’s awareness that personally identifiable information is being collected by [Assignment: organization-defined sensors]: [Assignment: organization-defined measures].'),
  ('SC-42(5)', 'NIST-800-53', 'System and Communications Protection', 'Sensor Capability and Data | Collection Minimization', 'Employ [Assignment: organization-defined sensors] that are configured to minimize the collection of information about individuals that is not needed.'),
  ('SC-43', 'NIST-800-53', 'System and Communications Protection', 'Usage Restrictions', 'a. Establish usage restrictions and implementation guidelines for the following system components: [Assignment: organization-defined components] ; and
b. Authorize, monitor, and control the use of such components within the system.'),
  ('SC-44', 'NIST-800-53', 'System and Communications Protection', 'Detonation Chambers', 'Employ a detonation chamber capability within [Assignment: organization-defined system, system component, or location].'),
  ('SC-45', 'NIST-800-53', 'System and Communications Protection', 'System Time Synchronization', 'Synchronize system clocks within and between systems and system components.'),
  ('SC-45(1)', 'NIST-800-53', 'System and Communications Protection', 'System Time Synchronization | Synchronization with Authoritative Time Source', '(a) Compare the internal system clocks [Assignment: organization-defined frequency] with [Assignment: organization-defined authoritative time source] ; and
(b) Synchronize the internal system clocks to the authoritative time source when the time difference is greater than [Assignment: organization-defined time period].'),
  ('SC-45(2)', 'NIST-800-53', 'System and Communications Protection', 'System Time Synchronization | Secondary Authoritative Time Source', '(a) Identify a secondary authoritative time source that is in a different geographic region than the primary authoritative time source; and
(b) Synchronize the internal system clocks to the secondary authoritative time source if the primary authoritative time source is unavailable.'),
  ('SC-46', 'NIST-800-53', 'System and Communications Protection', 'Cross Domain Policy Enforcement', 'Implement a policy enforcement mechanism [Selection: physically; logically] between the physical and/or network interfaces for the connecting security domains.'),
  ('SC-47', 'NIST-800-53', 'System and Communications Protection', 'Alternate Communications Paths', 'Establish [Assignment: organization-defined alternate communication paths] for system operations organizational command and control.'),
  ('SC-48', 'NIST-800-53', 'System and Communications Protection', 'Sensor Relocation', 'Relocate [Assignment: organization-defined sensors and monitoring capabilities] to [Assignment: organization-defined locations] under the following conditions or circumstances: [Assignment: organization-defined conditions or circumstances].'),
  ('SC-48(1)', 'NIST-800-53', 'System and Communications Protection', 'Sensor Relocation | Dynamic Relocation of Sensors or Monitoring Capabilities', 'Dynamically relocate [Assignment: organization-defined sensors and monitoring capabilities] to [Assignment: organization-defined locations] under the following conditions or circumstances: [Assignment: organization-defined conditions or circumstances].'),
  ('SC-49', 'NIST-800-53', 'System and Communications Protection', 'Hardware-enforced Separation and Policy Enforcement', 'Implement hardware-enforced separation and policy enforcement mechanisms between [Assignment: organization-defined security domains].'),
  ('SC-50', 'NIST-800-53', 'System and Communications Protection', 'Software-enforced Separation and Policy Enforcement', 'Implement software-enforced separation and policy enforcement mechanisms between [Assignment: organization-defined security domains].'),
  ('SC-51', 'NIST-800-53', 'System and Communications Protection', 'Hardware-based Protection', 'a. Employ hardware-based, write-protect for [Assignment: organization-defined system firmware components] ; and
b. Implement specific procedures for [Assignment: organization-defined authorized individuals] to manually disable hardware write-protect for firmware modifications and re-enable the write-protect prior to returning to operational mode.'),
  ('SI-1', 'NIST-800-53', 'System and Information Integrity', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the system and information integrity policy and the associated system and information integrity controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and information integrity policy and procedures; and
c. Review and update the current system and information integrity:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('SI-2', 'NIST-800-53', 'System and Information Integrity', 'Flaw Remediation', 'a. Identify, report, and correct system flaws;
b. Test software and firmware updates related to flaw remediation for effectiveness and potential side effects before installation;
c. Install security-relevant software and firmware updates within [Assignment: organization-defined time period] of the release of the updates; and
d. Incorporate flaw remediation into the organizational configuration management process.'),
  ('SI-2(2)', 'NIST-800-53', 'System and Information Integrity', 'Flaw Remediation | Automated Flaw Remediation Status', 'Determine if system components have applicable security-relevant software and firmware updates installed using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency].'),
  ('SI-2(3)', 'NIST-800-53', 'System and Information Integrity', 'Flaw Remediation | Time to Remediate Flaws and Benchmarks for Corrective Actions', '(a) Measure the time between flaw identification and flaw remediation; and
(b) Establish the following benchmarks for taking corrective actions: [Assignment: organization-defined benchmarks].'),
  ('SI-2(4)', 'NIST-800-53', 'System and Information Integrity', 'Flaw Remediation | Automated Patch Management Tools', 'Employ automated patch management tools to facilitate flaw remediation to the following system components: [Assignment: organization-defined components].'),
  ('SI-2(5)', 'NIST-800-53', 'System and Information Integrity', 'Flaw Remediation | Automatic Software and Firmware Updates', 'Install [Assignment: organization-defined security-relevant software and firmware updates] automatically to [Assignment: organization-defined system components].'),
  ('SI-2(6)', 'NIST-800-53', 'System and Information Integrity', 'Flaw Remediation | Removal of Previous Versions of Software and Firmware', 'Remove previous versions of [Assignment: organization-defined software and firmware components] after updated versions have been installed.'),
  ('SI-2(7)', 'NIST-800-53', 'System and Information Integrity', 'Flaw Remediation | Root Cause Analysis', 'a. Conduct root cause analysis to identify underlying causes of issues or failures.
b. Develop actions to address the root cause of the issue or failure.
c. Implement the actions and monitor the implementation for effectiveness.'),
  ('SI-3', 'NIST-800-53', 'System and Information Integrity', 'Malicious Code Protection', 'a. Implement [Selection (one or more): signature-based; non-signature-based] malicious code protection mechanisms at system entry and exit points to detect and eradicate malicious code;
b. Automatically update malicious code protection mechanisms as new releases are available in accordance with organizational configuration management policy and procedures;
c. Configure malicious code protection mechanisms to:
  1. Perform periodic scans of the system [Assignment: organization-defined frequency] and real-time scans of files from external sources at [Selection (one or more): endpoint; network entry and exit points] as the files are downloaded, opened, or executed in accordance with organizational policy; and
  2. [Selection (one or more): block malicious code; quarantine malicious code; take [Assignment: organization-defined action] ] ; and send alert to [Assignment: organization-defined personnel or roles] in response to malicious code detection; and
d. Address the receipt of false positives during malicious code detection and eradication and the resulting potential impact on the availability of the system.'),
  ('SI-3(4)', 'NIST-800-53', 'System and Information Integrity', 'Malicious Code Protection | Updates Only by Privileged Users', 'Update malicious code protection mechanisms only when directed by a privileged user.'),
  ('SI-3(6)', 'NIST-800-53', 'System and Information Integrity', 'Malicious Code Protection | Testing and Verification', '(a) Test malicious code protection mechanisms [Assignment: organization-defined frequency] by introducing known benign code into the system; and
(b) Verify that the detection of the code and the associated incident reporting occur.'),
  ('SI-3(8)', 'NIST-800-53', 'System and Information Integrity', 'Malicious Code Protection | Detect Unauthorized Commands', '(a) Detect the following unauthorized operating system commands through the kernel application programming interface on [Assignment: organization-defined system hardware components]: [Assignment: organization-defined unauthorized operating system commands] ; and
(b) [Selection (one or more): issue a warning; audit the command execution; prevent the execution of the command].'),
  ('SI-3(10)', 'NIST-800-53', 'System and Information Integrity', 'Malicious Code Protection | Malicious Code Analysis', '(a) Employ the following tools and techniques to analyze the characteristics and behavior of malicious code: [Assignment: organization-defined tools and techniques] ; and
(b) Incorporate the results from malicious code analysis into organizational incident response and flaw remediation processes.'),
  ('SI-4', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring', 'a. Monitor the system to detect:
  1. Attacks and indicators of potential attacks in accordance with the following monitoring objectives: [Assignment: organization-defined monitoring objectives] ; and
  2. Unauthorized local, network, and remote connections;
b. Identify unauthorized use of the system through the following techniques and methods: [Assignment: organization-defined techniques and methods];
c. Invoke internal monitoring capabilities or deploy monitoring devices:
  1. Strategically within the system to collect organization-determined essential information; and
  2. At ad hoc locations within the system to track specific types of transactions of interest to the organization;
d. Analyze detected events and anomalies;
e. Adjust the level of system monitoring activity when there is a change in risk to organizational operations and assets, individuals, other organizations, or the Nation;
f. Obtain legal opinion regarding system monitoring activities; and
g. Provide [Assignment: organization-defined system monitoring information] to [Assignment: organization-defined personnel or roles] [Selection (one or more): as needed; [Assignment: organization-defined frequency] ].'),
  ('SI-4(1)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | System-wide Intrusion Detection System', 'Connect and configure individual intrusion detection tools into a system-wide intrusion detection system.'),
  ('SI-4(2)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Automated Tools and Mechanisms for Real-time Analysis', 'Employ automated tools and mechanisms to support near real-time analysis of events.'),
  ('SI-4(3)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Automated Tool and Mechanism Integration', 'Employ automated tools and mechanisms to integrate intrusion detection tools and mechanisms into access control and flow control mechanisms.'),
  ('SI-4(4)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Inbound and Outbound Communications Traffic', '(a) Determine criteria for unusual or unauthorized activities or conditions for inbound and outbound communications traffic;
(b) Monitor inbound and outbound communications traffic [Assignment: organization-defined frequency] for [Assignment: organization-defined unusual or unauthorized activities or conditions].'),
  ('SI-4(5)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | System-generated Alerts', 'Alert [Assignment: organization-defined personnel or roles] when the following system-generated indications of compromise or potential compromise occur: [Assignment: organization-defined compromise indicators].'),
  ('SI-4(7)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Automated Response to Suspicious Events', '(a) Notify [Assignment: organization-defined incident response personnel] of detected suspicious events; and
(b) Take the following actions upon detection: [Assignment: organization-defined least-disruptive actions].'),
  ('SI-4(9)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Testing of Monitoring Tools and Mechanisms', 'Test intrusion-monitoring tools and mechanisms [Assignment: organization-defined frequency].'),
  ('SI-4(10)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Visibility of Encrypted Communications', 'Make provisions so that [Assignment: organization-defined encrypted communications traffic] is visible to [Assignment: organization-defined system monitoring tools and mechanisms].'),
  ('SI-4(11)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Analyze Communications Traffic Anomalies', 'Analyze outbound communications traffic at the external interfaces to the system and selected [Assignment: organization-defined interior points] to discover anomalies.'),
  ('SI-4(12)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Automated Organization-generated Alerts', 'Alert [Assignment: organization-defined personnel or roles] using [Assignment: organization-defined automated mechanisms] when the following indications of inappropriate or unusual activities with security or privacy implications occur: [Assignment: organization-defined activities that trigger alerts].'),
  ('SI-4(13)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Analyze Traffic and Event Patterns', '(a) Analyze communications traffic and event patterns for the system;
(b) Develop profiles representing common traffic and event patterns; and
(c) Use the traffic and event profiles in tuning system-monitoring devices.'),
  ('SI-4(14)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Wireless Intrusion Detection', 'Employ a wireless intrusion detection system to identify rogue wireless devices and to detect attack attempts and potential compromises or breaches to the system.'),
  ('SI-4(15)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Wireless to Wireline Communications', 'Employ an intrusion detection system to monitor wireless communications traffic as the traffic passes from wireless to wireline networks.'),
  ('SI-4(16)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Correlate Monitoring Information', 'Correlate information from monitoring tools and mechanisms employed throughout the system.'),
  ('SI-4(17)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Integrated Situational Awareness', 'Correlate information from monitoring physical, cyber, and supply chain activities to achieve integrated, organization-wide situational awareness.'),
  ('SI-4(18)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Analyze Traffic and Covert Exfiltration', 'Analyze outbound communications traffic at external interfaces to the system and at the following interior points to detect covert exfiltration of information: [Assignment: organization-defined interior points].'),
  ('SI-4(19)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Risk for Individuals', 'Implement [Assignment: organization-defined additional monitoring] of individuals who have been identified by [Assignment: organization-defined sources] as posing an increased level of risk.'),
  ('SI-4(20)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Privileged Users', 'Implement the following additional monitoring of privileged users: [Assignment: organization-defined additional monitoring].'),
  ('SI-4(21)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Probationary Periods', 'Implement the following additional monitoring of individuals during [Assignment: organization-defined probationary period]: [Assignment: organization-defined additional monitoring].'),
  ('SI-4(22)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Unauthorized Network Services', '(a) Detect network services that have not been authorized or approved by [Assignment: organization-defined authorization or approval processes] ; and
(b) [Selection (one or more): audit; alert [Assignment: organization-defined personnel or roles] ] when detected.'),
  ('SI-4(23)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Host-based Devices', 'Implement the following host-based monitoring mechanisms at [Assignment: organization-defined system components]: [Assignment: organization-defined host-based monitoring mechanisms].'),
  ('SI-4(24)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Indicators of Compromise', 'Discover, collect, and distribute to [Assignment: organization-defined personnel or roles] , indicators of compromise provided by [Assignment: organization-defined sources].'),
  ('SI-4(25)', 'NIST-800-53', 'System and Information Integrity', 'System Monitoring | Optimize Network Traffic Analysis', 'Provide visibility into network traffic at external and key internal system interfaces to optimize the effectiveness of monitoring devices.'),
  ('SI-5', 'NIST-800-53', 'System and Information Integrity', 'Security Alerts, Advisories, and Directives', 'a. Receive system security alerts, advisories, and directives from [Assignment: organization-defined external organizations] on an ongoing basis;
b. Generate internal security alerts, advisories, and directives as deemed necessary;
c. Disseminate security alerts, advisories, and directives to: [Selection (one or more): [Assignment: organization-defined personnel or roles] ; [Assignment: organization-defined elements] ; [Assignment: organization-defined external organizations] ] ; and
d. Implement security directives in accordance with established time frames, or notify the issuing organization of the degree of noncompliance.'),
  ('SI-5(1)', 'NIST-800-53', 'System and Information Integrity', 'Security Alerts, Advisories, and Directives | Automated Alerts and Advisories', 'Broadcast security alert and advisory information throughout the organization using [Assignment: organization-defined automated mechanisms].'),
  ('SI-6', 'NIST-800-53', 'System and Information Integrity', 'Security and Privacy Function Verification', 'a. Verify the correct operation of [Assignment: organization-defined security and privacy functions];
b. Perform the verification of the functions specified in SI-6a [Selection (one or more): [Assignment: organization-defined system transitional states] ; upon command by user with appropriate privilege; [Assignment: organization-defined frequency] ];
c. Alert [Assignment: organization-defined personnel or roles] to failed security and privacy verification tests; and
d. [Selection (one or more): shut the system down; restart the system; [Assignment: organization-defined alternative action(s)] ] when anomalies are discovered.'),
  ('SI-6(2)', 'NIST-800-53', 'System and Information Integrity', 'Security and Privacy Function Verification | Automation Support for Distributed Testing', 'Implement automated mechanisms to support the management of distributed security and privacy function testing.'),
  ('SI-6(3)', 'NIST-800-53', 'System and Information Integrity', 'Security and Privacy Function Verification | Report Verification Results', 'Report the results of security and privacy function verification to [Assignment: organization-defined personnel or roles].'),
  ('SI-7', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity', 'a. Employ integrity verification tools to detect unauthorized changes to the following software, firmware, and information: [Assignment: organization-defined software, firmware, and information] ; and
b. Take the following actions when unauthorized changes to the software, firmware, and information are detected: [Assignment: organization-defined actions].'),
  ('SI-7(1)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Integrity Checks', 'Perform an integrity check of [Assignment: organization-defined software, firmware, and information] [Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events] ; [Assignment: organization-defined frequency] ].'),
  ('SI-7(2)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Automated Notifications of Integrity Violations', 'Employ automated tools that provide notification to [Assignment: organization-defined personnel or roles] upon discovering discrepancies during integrity verification.'),
  ('SI-7(3)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Centrally Managed Integrity Tools', 'Employ centrally managed integrity verification tools.'),
  ('SI-7(5)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Automated Response to Integrity Violations', 'Automatically [Selection (one or more): shut down the system; restart the system; implement [Assignment: organization-defined controls] ] when integrity violations are discovered.'),
  ('SI-7(6)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Cryptographic Protection', 'Implement cryptographic mechanisms to detect unauthorized changes to software, firmware, and information.'),
  ('SI-7(7)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Integration of Detection and Response', 'Incorporate the detection of the following unauthorized changes into the organizational incident response capability: [Assignment: organization-defined changes].'),
  ('SI-7(8)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Auditing Capability for Significant Events', 'Upon detection of a potential integrity violation, provide the capability to audit the event and initiate the following actions: [Selection (one or more): generate an audit record; alert current user; alert [Assignment: organization-defined personnel or roles] ; [Assignment: organization-defined other actions] ].'),
  ('SI-7(9)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Verify Boot Process', 'Verify the integrity of the boot process of the following system components: [Assignment: organization-defined system components].'),
  ('SI-7(10)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Protection of Boot Firmware', 'Implement the following mechanisms to protect the integrity of boot firmware in [Assignment: organization-defined system components]: [Assignment: organization-defined mechanisms].'),
  ('SI-7(12)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Integrity Verification', 'Require that the integrity of the following user-installed software be verified prior to execution: [Assignment: organization-defined user-installed software].'),
  ('SI-7(15)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Code Authentication', 'Implement cryptographic mechanisms to authenticate the following software or firmware components prior to installation: [Assignment: organization-defined software or firmware components].'),
  ('SI-7(16)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Time Limit on Process Execution Without Supervision', 'Prohibit processes from executing without supervision for more than [Assignment: organization-defined time period].'),
  ('SI-7(17)', 'NIST-800-53', 'System and Information Integrity', 'Software, Firmware, and Information Integrity | Runtime Application Self-protection', 'Implement [Assignment: organization-defined controls] for application self-protection at runtime.'),
  ('SI-8', 'NIST-800-53', 'System and Information Integrity', 'Spam Protection', 'a. Employ spam protection mechanisms at system entry and exit points to detect and act on unsolicited messages; and
b. Update spam protection mechanisms when new releases are available in accordance with organizational configuration management policy and procedures.'),
  ('SI-8(2)', 'NIST-800-53', 'System and Information Integrity', 'Spam Protection | Automatic Updates', 'Automatically update spam protection mechanisms [Assignment: organization-defined frequency].'),
  ('SI-8(3)', 'NIST-800-53', 'System and Information Integrity', 'Spam Protection | Continuous Learning Capability', 'Implement spam protection mechanisms with a learning capability to more effectively identify legitimate communications traffic.'),
  ('SI-10', 'NIST-800-53', 'System and Information Integrity', 'Information Input Validation', 'Check the validity of the following information inputs: [Assignment: organization-defined information inputs].'),
  ('SI-10(1)', 'NIST-800-53', 'System and Information Integrity', 'Information Input Validation | Manual Override Capability', '(a) Provide a manual override capability for input validation of the following information inputs: [Assignment: organization-defined information inputs];
(b) Restrict the use of the manual override capability to only [Assignment: organization-defined authorized individuals] ; and
(c) Audit the use of the manual override capability.'),
  ('SI-10(2)', 'NIST-800-53', 'System and Information Integrity', 'Information Input Validation | Review and Resolve Errors', 'Review and resolve input validation errors within [Assignment: organization-defined time period].'),
  ('SI-10(3)', 'NIST-800-53', 'System and Information Integrity', 'Information Input Validation | Predictable Behavior', 'Verify that the system behaves in a predictable and documented manner when invalid inputs are received.'),
  ('SI-10(4)', 'NIST-800-53', 'System and Information Integrity', 'Information Input Validation | Timing Interactions', 'Account for timing interactions among system components in determining appropriate responses for invalid inputs.'),
  ('SI-10(5)', 'NIST-800-53', 'System and Information Integrity', 'Information Input Validation | Restrict Inputs to Trusted Sources and Approved Formats', 'Restrict the use of information inputs to [Assignment: organization-defined trusted sources] and/or [Assignment: organization-defined formats].'),
  ('SI-10(6)', 'NIST-800-53', 'System and Information Integrity', 'Information Input Validation | Injection Prevention', 'Prevent untrusted data injections.'),
  ('SI-11', 'NIST-800-53', 'System and Information Integrity', 'Error Handling', 'a. Generate error messages that provide information necessary for corrective actions without revealing information that could be exploited; and
b. Reveal error messages only to [Assignment: organization-defined personnel or roles].'),
  ('SI-12', 'NIST-800-53', 'System and Information Integrity', 'Information Management and Retention', 'Manage and retain information within the system and information output from the system in accordance with applicable laws, executive orders, directives, regulations, policies, standards, guidelines and operational requirements.'),
  ('SI-12(1)', 'NIST-800-53', 'System and Information Integrity', 'Information Management and Retention | Limit Personally Identifiable Information Elements', 'Limit personally identifiable information being processed in the information life cycle to the following elements of personally identifiable information: [Assignment: organization-defined elements of personally identifiable information].'),
  ('SI-12(2)', 'NIST-800-53', 'System and Information Integrity', 'Information Management and Retention | Minimize Personally Identifiable Information in Testing, Training, and Research', 'Use the following techniques to minimize the use of personally identifiable information for research, testing, or training: [Assignment: organization-defined techniques].'),
  ('SI-12(3)', 'NIST-800-53', 'System and Information Integrity', 'Information Management and Retention | Information Disposal', 'Use the following techniques to dispose of, destroy, or erase information following the retention period: [Assignment: organization-defined techniques].'),
  ('SI-13', 'NIST-800-53', 'System and Information Integrity', 'Predictable Failure Prevention', 'a. Determine mean time to failure (MTTF) for the following system components in specific environments of operation: [Assignment: organization-defined system components] ; and
b. Provide substitute system components and a means to exchange active and standby components in accordance with the following criteria: [Assignment: organization-defined mean time to failure (MTTF) substitution criteria].'),
  ('SI-13(1)', 'NIST-800-53', 'System and Information Integrity', 'Predictable Failure Prevention | Transferring Component Responsibilities', 'Take system components out of service by transferring component responsibilities to substitute components no later than [Assignment: organization-defined fraction or percentage] of mean time to failure.'),
  ('SI-13(3)', 'NIST-800-53', 'System and Information Integrity', 'Predictable Failure Prevention | Manual Transfer Between Components', 'Manually initiate transfers between active and standby system components when the use of the active component reaches [Assignment: organization-defined percentage] of the mean time to failure.'),
  ('SI-13(4)', 'NIST-800-53', 'System and Information Integrity', 'Predictable Failure Prevention | Standby Component Installation and Notification', 'If system component failures are detected:
  (a) Ensure that the standby components are successfully and transparently installed within [Assignment: organization-defined time period] ; and
  (b) [Selection (one or more): activate [Assignment: organization-defined alarm] ; automatically shut down the system; [Assignment: organization-defined action] ].'),
  ('SI-13(5)', 'NIST-800-53', 'System and Information Integrity', 'Predictable Failure Prevention | Failover Capability', 'Provide [Selection: real-time; near real-time] [Assignment: organization-defined failover capability] for the system.'),
  ('SI-14', 'NIST-800-53', 'System and Information Integrity', 'Non-persistence', 'Implement non-persistent [Assignment: organization-defined system components and services] that are initiated in a known state and terminated [Selection (one or more): upon end of session of use; [Assignment: organization-defined frequency] ].'),
  ('SI-14(1)', 'NIST-800-53', 'System and Information Integrity', 'Non-persistence | Refresh from Trusted Sources', 'Obtain software and data employed during system component and service refreshes from the following trusted sources: [Assignment: organization-defined trusted sources].'),
  ('SI-14(2)', 'NIST-800-53', 'System and Information Integrity', 'Non-persistence | Non-persistent Information', '(a) [Selection: refresh [Assignment: organization-defined information] [Assignment: organization-defined frequency] ; generate [Assignment: organization-defined information] on demand] ; and
(b) Delete information when no longer needed.'),
  ('SI-14(3)', 'NIST-800-53', 'System and Information Integrity', 'Non-persistence | Non-persistent Connectivity', 'Establish connections to the system on demand and terminate connections after [Selection: completion of a request; a period of non-use].'),
  ('SI-15', 'NIST-800-53', 'System and Information Integrity', 'Information Output Filtering', 'Validate information output from the following software programs and/or applications to ensure that the information is consistent with the expected content: [Assignment: organization-defined software programs and/or applications].'),
  ('SI-16', 'NIST-800-53', 'System and Information Integrity', 'Memory Protection', 'Implement the following controls to protect the system memory from unauthorized code execution: [Assignment: organization-defined controls].'),
  ('SI-17', 'NIST-800-53', 'System and Information Integrity', 'Fail-safe Procedures', 'Implement the indicated fail-safe procedures when the indicated failures occur: [Assignment: organization-defined list of failure conditions and associated fail-safe procedures].'),
  ('SI-18', 'NIST-800-53', 'System and Information Integrity', 'Personally Identifiable Information Quality Operations', 'a. Check the accuracy, relevance, timeliness, and completeness of personally identifiable information across the information life cycle [Assignment: organization-defined frequency] ; and
b. Correct or delete inaccurate or outdated personally identifiable information.'),
  ('SI-18(1)', 'NIST-800-53', 'System and Information Integrity', 'Personally Identifiable Information Quality Operations | Automation Support', 'Correct or delete personally identifiable information that is inaccurate or outdated, incorrectly determined regarding impact, or incorrectly de-identified using [Assignment: organization-defined automated mechanisms].'),
  ('SI-18(2)', 'NIST-800-53', 'System and Information Integrity', 'Personally Identifiable Information Quality Operations | Data Tags', 'Employ data tags to automate the correction or deletion of personally identifiable information across the information life cycle within organizational systems.'),
  ('SI-18(3)', 'NIST-800-53', 'System and Information Integrity', 'Personally Identifiable Information Quality Operations | Collection', 'Collect personally identifiable information directly from the individual.'),
  ('SI-18(4)', 'NIST-800-53', 'System and Information Integrity', 'Personally Identifiable Information Quality Operations | Individual Requests', 'Correct or delete personally identifiable information upon request by individuals or their designated representatives.'),
  ('SI-18(5)', 'NIST-800-53', 'System and Information Integrity', 'Personally Identifiable Information Quality Operations | Notice of Correction or Deletion', 'Notify [Assignment: organization-defined recipients] and individuals that the personally identifiable information has been corrected or deleted.'),
  ('SI-19', 'NIST-800-53', 'System and Information Integrity', 'De-identification', 'a. Remove the following elements of personally identifiable information from datasets: [Assignment: organization-defined elements] ; and
b. Evaluate [Assignment: organization-defined frequency] for effectiveness of de-identification.'),
  ('SI-19(1)', 'NIST-800-53', 'System and Information Integrity', 'De-identification | Collection', 'De-identify the dataset upon collection by not collecting personally identifiable information.'),
  ('SI-19(2)', 'NIST-800-53', 'System and Information Integrity', 'De-identification | Archiving', 'Prohibit archiving of personally identifiable information elements if those elements in a dataset will not be needed after the dataset is archived.'),
  ('SI-19(3)', 'NIST-800-53', 'System and Information Integrity', 'De-identification | Release', 'Remove personally identifiable information elements from a dataset prior to its release if those elements in the dataset do not need to be part of the data release.'),
  ('SI-19(4)', 'NIST-800-53', 'System and Information Integrity', 'De-identification | Removal, Masking, Encryption, Hashing, or Replacement of Direct Identifiers', 'Remove, mask, encrypt, hash, or replace direct identifiers in a dataset.'),
  ('SI-19(5)', 'NIST-800-53', 'System and Information Integrity', 'De-identification | Statistical Disclosure Control', 'Manipulate numerical data, contingency tables, and statistical findings so that no individual or organization is identifiable in the results of the analysis.'),
  ('SI-19(6)', 'NIST-800-53', 'System and Information Integrity', 'De-identification | Differential Privacy', 'Prevent disclosure of personally identifiable information by adding non-deterministic noise to the results of mathematical operations before the results are reported.'),
  ('SI-19(7)', 'NIST-800-53', 'System and Information Integrity', 'De-identification | Validated Algorithms and Software', 'Perform de-identification using validated algorithms and software that is validated to implement the algorithms.'),
  ('SI-19(8)', 'NIST-800-53', 'System and Information Integrity', 'De-identification | Motivated Intruder', 'Perform a motivated intruder test on the de-identified dataset to determine if the identified data remains or if the de-identified data can be re-identified.'),
  ('SI-20', 'NIST-800-53', 'System and Information Integrity', 'Tainting', 'Embed data or capabilities in the following systems or system components to determine if organizational data has been exfiltrated or improperly removed from the organization: [Assignment: organization-defined systems or system components].'),
  ('SI-21', 'NIST-800-53', 'System and Information Integrity', 'Information Refresh', 'Refresh [Assignment: organization-defined information] at [Assignment: organization-defined frequencies] or generate the information on demand and delete the information when no longer needed.'),
  ('SI-22', 'NIST-800-53', 'System and Information Integrity', 'Information Diversity', 'a. Identify the following alternative sources of information for [Assignment: organization-defined essential functions and services]: [Assignment: organization-defined alternative information sources] ; and
b. Use an alternative information source for the execution of essential functions or services on [Assignment: organization-defined systems or system components] when the primary source of information is corrupted or unavailable.'),
  ('SI-23', 'NIST-800-53', 'System and Information Integrity', 'Information Fragmentation', 'Based on [Assignment: organization-defined circumstances]:
  a. Fragment the following information: [Assignment: organization-defined information] ; and
  b. Distribute the fragmented information across the following systems or system components: [Assignment: organization-defined systems or system components].'),
  ('SR-1', 'NIST-800-53', 'Supply Chain Risk Management', 'Policy and Procedures', 'a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:
  1. [Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy that:
    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and
    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and
  2. Procedures to facilitate the implementation of the supply chain risk management policy and the associated supply chain risk management controls;
b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the supply chain risk management policy and procedures; and
c. Review and update the current supply chain risk management:
  1. Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events] ; and
  2. Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].'),
  ('SR-2', 'NIST-800-53', 'Supply Chain Risk Management', 'Supply Chain Risk Management Plan', 'a. Develop a plan for managing supply chain risks associated with the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of the following systems, system components or system services: [Assignment: organization-defined systems, system components, or system services];
b. Review and update the supply chain risk management plan [Assignment: organization-defined frequency] or as required, to address threat, organizational or environmental changes; and
c. Protect the supply chain risk management plan from unauthorized disclosure and modification.'),
  ('SR-2(1)', 'NIST-800-53', 'Supply Chain Risk Management', 'Supply Chain Risk Management Plan | Establish SCRM Team', 'Establish a supply chain risk management team consisting of [Assignment: organization-defined personnel, roles and responsibilities] to lead and support the following SCRM activities: [Assignment: organization-defined supply chain risk management activities].'),
  ('SR-3', 'NIST-800-53', 'Supply Chain Risk Management', 'Supply Chain Controls and Processes', 'a. Establish a process or processes to identify and address weaknesses or deficiencies in the supply chain elements and processes of [Assignment: organization-defined system or system component] in coordination with [Assignment: organization-defined supply chain personnel];
b. Employ the following controls to protect against supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain-related events: [Assignment: organization-defined supply chain controls] ; and
c. Document the selected and implemented supply chain processes and controls in [Selection (one or more): security and privacy plans; supply chain risk management plan; [Assignment: organization-defined document] ].'),
  ('SR-3(1)', 'NIST-800-53', 'Supply Chain Risk Management', 'Supply Chain Controls and Processes | Diverse Supply Base', 'Employ a diverse set of sources for the following system components and services: [Assignment: organization-defined system components and services].'),
  ('SR-3(2)', 'NIST-800-53', 'Supply Chain Risk Management', 'Supply Chain Controls and Processes | Limitation of Harm', 'Employ the following controls to limit harm from potential adversaries identifying and targeting the organizational supply chain: [Assignment: organization-defined controls].'),
  ('SR-3(3)', 'NIST-800-53', 'Supply Chain Risk Management', 'Supply Chain Controls and Processes | Sub-tier Flow Down', 'Ensure that the controls included in the contracts of prime contractors are also included in the contracts of subcontractors.'),
  ('SR-4', 'NIST-800-53', 'Supply Chain Risk Management', 'Provenance', 'Document, monitor, and maintain valid provenance of the following systems, system components, and associated data: [Assignment: organization-defined systems, system components, and associated data].'),
  ('SR-4(1)', 'NIST-800-53', 'Supply Chain Risk Management', 'Provenance | Identity', 'Establish and maintain unique identification of the following supply chain elements, processes, and personnel associated with the identified system and critical system components: [Assignment: organization-defined supply chain elements, processes, and personnel].'),
  ('SR-4(2)', 'NIST-800-53', 'Supply Chain Risk Management', 'Provenance | Track and Trace', 'Establish and maintain unique identification of the following systems and critical system components for tracking through the supply chain: [Assignment: organization-defined systems and critical system components].'),
  ('SR-4(3)', 'NIST-800-53', 'Supply Chain Risk Management', 'Provenance | Validate as Genuine and Not Altered', 'Employ the following controls to validate that the system or system component received is genuine and has not been altered: [Assignment: organization-defined controls].'),
  ('SR-4(4)', 'NIST-800-53', 'Supply Chain Risk Management', 'Provenance | Supply Chain Integrity — Pedigree', 'Employ [Assignment: organization-defined controls] and conduct [Assignment: organization-defined analysis method] to ensure the integrity of the system and system components by validating the internal composition and provenance of critical or mission-essential technologies, products, and services.'),
  ('SR-5', 'NIST-800-53', 'Supply Chain Risk Management', 'Acquisition Strategies, Tools, and Methods', 'Employ the following acquisition strategies, contract tools, and procurement methods to protect against, identify, and mitigate supply chain risks: [Assignment: organization-defined strategies, tools, and methods].')
ON CONFLICT (control_id) DO UPDATE
  SET family = EXCLUDED.family, title = EXCLUDED.title, description = EXCLUDED.description
  WHERE compliance_controls.framework = 'NIST-800-53';

INSERT INTO compliance_controls (control_id, framework, family, title, description) VALUES
  ('SR-5(1)', 'NIST-800-53', 'Supply Chain Risk Management', 'Acquisition Strategies, Tools, and Methods | Adequate Supply', 'Employ the following controls to ensure an adequate supply of [Assignment: organization-defined critical system components]: [Assignment: organization-defined controls].'),
  ('SR-5(2)', 'NIST-800-53', 'Supply Chain Risk Management', 'Acquisition Strategies, Tools, and Methods | Assessments Prior to Selection, Acceptance, Modification, or Update', 'Assess the system, system component, or system service prior to selection, acceptance, modification, or update.'),
  ('SR-6', 'NIST-800-53', 'Supply Chain Risk Management', 'Supplier Assessments and Reviews', 'Assess and review the supply chain-related risks associated with suppliers or contractors and the system, system component, or system service they provide [Assignment: organization-defined frequency].'),
  ('SR-6(1)', 'NIST-800-53', 'Supply Chain Risk Management', 'Supplier Assessments and Reviews | Testing and Analysis', 'Employ [Selection (one or more): organizational analysis; independent third-party analysis; organizational testing; independent third-party testing] of the following supply chain elements, processes, and actors associated with the system, system component, or system service: [Assignment: organization-defined supply chain elements, processes, and actors].'),
  ('SR-7', 'NIST-800-53', 'Supply Chain Risk Management', 'Supply Chain Operations Security', 'Employ the following Operations Security (OPSEC) controls to protect supply chain-related information for the system, system component, or system service: [Assignment: organization-defined OPSEC controls].'),
  ('SR-8', 'NIST-800-53', 'Supply Chain Risk Management', 'Notification Agreements', 'Establish agreements and procedures with entities involved in the supply chain for the system, system component, or system service for the [Selection (one or more): notification of supply chain compromises; [Assignment: organization-defined results of assessments or audits] ].'),
  ('SR-9', 'NIST-800-53', 'Supply Chain Risk Management', 'Tamper Resistance and Detection', 'Implement a tamper protection program for the system, system component, or system service.'),
  ('SR-9(1)', 'NIST-800-53', 'Supply Chain Risk Management', 'Tamper Resistance and Detection | Multiple Stages of System Development Life Cycle', 'Employ anti-tamper technologies, tools, and techniques throughout the system development life cycle.'),
  ('SR-10', 'NIST-800-53', 'Supply Chain Risk Management', 'Inspection of Systems or Components', 'Inspect the following systems or system components [Selection (one or more): at random; at [Assignment: organization-defined frequency] ; upon [Assignment: organization-defined indications of need for inspection] ] to detect tampering: [Assignment: organization-defined systems or system components].'),
  ('SR-11', 'NIST-800-53', 'Supply Chain Risk Management', 'Component Authenticity', 'a. Develop and implement anti-counterfeit policy and procedures that include the means to detect and prevent counterfeit components from entering the system; and
b. Report counterfeit system components to [Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations] ; [Assignment: organization-defined personnel or roles] ].'),
  ('SR-11(1)', 'NIST-800-53', 'Supply Chain Risk Management', 'Component Authenticity | Anti-counterfeit Training', 'Train [Assignment: organization-defined personnel or roles] to detect counterfeit system components (including hardware, software, and firmware).'),
  ('SR-11(2)', 'NIST-800-53', 'Supply Chain Risk Management', 'Component Authenticity | Configuration Control for Component Service and Repair', 'Maintain configuration control over the following system components awaiting service or repair and serviced or repaired components awaiting return to service: [Assignment: organization-defined system components].'),
  ('SR-11(3)', 'NIST-800-53', 'Supply Chain Risk Management', 'Component Authenticity | Anti-counterfeit Scanning', 'Scan for counterfeit system components [Assignment: organization-defined frequency].'),
  ('SR-12', 'NIST-800-53', 'Supply Chain Risk Management', 'Component Disposal', 'Dispose of [Assignment: organization-defined data, documentation, tools, or system components] using the following techniques and methods: [Assignment: organization-defined techniques and methods].')
ON CONFLICT (control_id) DO UPDATE
  SET family = EXCLUDED.family, title = EXCLUDED.title, description = EXCLUDED.description
  WHERE compliance_controls.framework = 'NIST-800-53';
